/**
 * STAMP: 2026-08-18 - Keep content-dependent commands out of a blank slide.
 * A slide containing canvas objects, HTML, media, or authored actions is not blank.
 * This intentionally does not treat the white canvas background as content.
 *
 * @returns {boolean} True when the active slide has no authored content.
 */
function isCurrentSlideBlank() {
    var slide = generated_slides && slide_index >= 0 ? generated_slides[slide_index] : null;
    var hasCanvasObjects = !!(canvas && typeof canvas.getObjects === "function" && canvas.getObjects().length);
    var hasTextValue = function (value) {
        return typeof value === "string" && value.trim().length > 0;
    };
    var hasCollection = function (value) {
        return Array.isArray(value) ? value.length > 0 : !!value && typeof value === "object" && Object.keys(value).length > 0;
    };

    if (hasCanvasObjects) return false;
    if (!slide) return true;

    return !hasTextValue(slide.HTMlcontent)
        && !hasTextValue(slide.SlideAudio)
        && !hasTextValue(slide.SlideVideo)
        && !hasCollection(slide.actions)
        && !hasCollection(slide.loadActions);
}

/**
 * Synchronize all controls whose commands require an authored active slide.
 * The body class provides a CSS safety net when legacy selection handlers run.
 *
 * @returns {boolean} The resulting blank-slide state.
 */
function syncBlankSlideActions() {
    var isBlank = isCurrentSlideBlank();
    document.body.classList.toggle("cg-slide-is-blank", isBlank);
    return isBlank;
}

window.isCurrentSlideBlank = isCurrentSlideBlank;
window.syncBlankSlideActions = syncBlankSlideActions;

