function buildBlankCanvasState() {
    return JSON.stringify({
        version: (fabric && fabric.version) ? fabric.version : "3.4.0",
        objects: [],
        background: "#fff"
    });
}

function serializeCanvasState(canvasState) {
    if (!canvasState) {
        return buildBlankCanvasState();
    }

    return (typeof canvasState === "string") ? canvasState : JSON.stringify(canvasState);
}

/**
 * Normalize the legacy full-circle angle written by older Fabric runtimes.
 *
 * STAMP: 2026-09-13 - Fabric 7 reads circle angles as degrees, while historic
 * IAOTCORE content can contain the former full-circle value of 2 * PI radians.
 * Without this compatibility pass Fabric draws only a 6.28-degree sliver but
 * keeps the full selection bounds, making the object appear invisible. Only
 * the exact legacy full-circle signature is converted so authored arcs retain
 * their original angles. Nested groups and clip paths are covered recursively.
 *
 * @param {*} canvasJson Serialized Fabric canvas data as an object or string.
 * @returns {*} Parsed/normalized canvas data, or the original value when it
 * cannot be parsed here so the existing loader error handling remains intact.
 */
function normalizeLegacyFabricCircleAngles(canvasJson) {
    var normalized = canvasJson;
    if (typeof normalized === "string") {
        try {
            normalized = JSON.parse(normalized);
        } catch (error) {
            return canvasJson;
        }
    }

    var fullCircleRadians = Math.PI * 2;
    var angleTolerance = 0.000001;
    var visit = function (value) {
        if (!value || typeof value !== "object") return;
        if (Array.isArray(value)) {
            value.forEach(visit);
            return;
        }

        if (String(value.type || "").toLowerCase() === "circle") {
            var startAngle = Number(value.startAngle);
            var endAngle = Number(value.endAngle);
            if (Number.isFinite(startAngle)
                && Number.isFinite(endAngle)
                && Math.abs(startAngle) <= angleTolerance
                && Math.abs(endAngle - fullCircleRadians) <= angleTolerance) {
                value.startAngle = 0;
                value.endAngle = 360;
            }
        }

        Object.keys(value).forEach(function (key) { visit(value[key]); });
    };

    visit(normalized);
    return normalized;
}

function getCanvasStateSnapshot() {
    return JSON.stringify(canvas.toJSON(HISTORY_OBJECT_PROPERTIES));
}

function createSlideHistory(initialState) {
    return {
        canvasState: [serializeCanvasState(initialState)],
        currentStateIndex: 0
    };
}

function getSlideHistory(slideId) {
    if (!slideId) {
        return null;
    }

    return ruConfig.slideHistory[slideId] || null;
}

function seedSlideHistory(slideId, initialState) {
    if (!slideId) {
        return null;
    }

    ruConfig.slideHistory[slideId] = createSlideHistory(initialState);
    return ruConfig.slideHistory[slideId];
}

function ensureSlideHistoryState(slideId, initialState) {
    var history = getSlideHistory(slideId);
    if (!history || !Array.isArray(history.canvasState) || history.canvasState.length === 0) {
        history = seedSlideHistory(slideId, initialState);
    }

    return history;
}

function refreshUndoRedoButtons(slideId) {
    var history = getSlideHistory(slideId);
    var hasUndo = !!(!ruConfig.isRestoring && history && history.currentStateIndex > 0);
    var hasRedo = !!(!ruConfig.isRestoring && history && history.currentStateIndex >= 0 && history.currentStateIndex < history.canvasState.length - 1);

    /* STAMP: 2026-08-27 - Only expose history actions that can move the
       active slide. Fresh/earliest states hide Undo; live/latest states hide
       Redo, while intermediate states expose both available directions. */
    $("#undo").prop("hidden", !hasUndo).attr("aria-disabled", hasUndo ? "false" : "true").attr("title", "Undo (Ctrl+Z)");
    $("#redo").prop("hidden", !hasRedo).attr("aria-disabled", hasRedo ? "false" : "true").attr("title", "Redo (Ctrl+Y / Ctrl+Shift+Z)");
    ruConfig.undoButton.parent().toggleClass("disabled-li", !hasUndo);
    ruConfig.redoButton.parent().toggleClass("disabled-li", !hasRedo);
}

function syncCanvasStateUi() {
    $("#sel_control option").hide();
    canvas.getObjects().forEach(function (object) {
        if (object.type == "rect") {
            object.strokeUniform = true;
        }
        $('#sel_control option[value="' + object.id + '"]').show();
    });
    updateDropdownList();
    canvas.renderAll();
}

function loadCanvasStateSnapshot(canvasState, callback) {
    ruConfig.isRestoring = true;
    canvas.disableEvents();
    canvas.discardActiveObject();
    var normalizedCanvasState = normalizeLegacyFabricCircleAngles(serializeCanvasState(canvasState));
    return canvas.loadFromJSON(normalizedCanvasState).then(function () {
        /* STAMP: 2026-09-05 - Navigation/clone/history loads suppress
           object:added, so explicitly restore the controls normally installed
           by that event and recompute their pointer hit areas. Preserve saved
           selectability and locks, including intentionally locked backgrounds. */
        canvas.getObjects().forEach(function (object) {
            /* STAMP: 2026-09-09 - Fabric temporarily makes IText/Textbox
               objects unselectable while their hidden textarea owns editing.
               Older history snapshots could persist that transient flag and
               reload visible text that could never be clicked again. A visible
               top-level text object is always an editor object, including when
               its movement is locked, so restore pointer participation here. */
            var objectType = String(object.type || "").toLowerCase();
            if ((objectType === "textbox" || objectType === "i-text") && object.visible !== false) {
                var isFullyLocked = object.lockMovementX === true
                    && object.lockMovementY === true
                    && object.lockScalingX === true
                    && object.lockScalingY === true
                    && object.lockRotation === true;
                var recoveredTextState = { selectable: true, evented: true };
                /* Fabric also applies temporary movement locks in text-edit
                   mode. Only remove that pair when the object is not using the
                   editor's explicit full-object lock contract. */
                if (!isFullyLocked && object.lockMovementX === true && object.lockMovementY === true) {
                    recoveredTextState.lockMovementX = false;
                    recoveredTextState.lockMovementY = false;
                }
                object.set(recoveredTextState);
            }
            if (typeof window.applyCanvasObjectActionControls === "function") {
                window.applyCanvasObjectActionControls(object);
            }
            object.setCoords();
        });
        syncCanvasStateUi();
        if (typeof callback === "function") callback();
        return true;
    }).catch(function (error) {
        console.error("Unable to restore canvas history state:", error);
        return false;
    }).finally(function () {
        canvas.enableEvents();
        ruConfig.isRestoring = false;
    });
}

