    /**
     * Normalize the shared color picker popup stamped 2026-04-29.
     * Keep it attached to document.body and above the property dock so the
     * palette never renders behind sticky editor panels.
     * @returns {jQuery} Shared color popup reference.
     */
    function ensureColorPickerPopupHost() {
        var $popup = $("#colorPickerPopup");
        var popupElement = $popup.get(0);

        if (popupElement && popupElement.parentNode !== document.body) {
            document.body.appendChild(popupElement);
        }

        /* STAMP: 2026-08-26 - Keep the shared palette above every contextual
           Quick Action popover while retaining its document.body host. */
        $popup.css("z-index", 2147483646);
        return $popup;
    }

    function getColorPickerPopupSize() {
        var $popup = ensureColorPickerPopupHost();
        var popup = $popup.get(0);
        var restoreState = null;

        if (!$popup.is(":visible")) {
            restoreState = {
                display: popup.style.display,
                visibility: popup.style.visibility
            };
            $popup.css({
                display: "block",
                visibility: "hidden"
            });
        }

        var size = {
            width: $popup.outerWidth() || 360,
            height: $popup.outerHeight() || 420
        };

        if (restoreState) {
            $popup.css(restoreState);
        }

        return size;
    }

    function clampColorPickerPopupPosition(left, top) {
        var popupSize = getColorPickerPopupSize();
        var margin = 16;
        var viewportLeft = $(window).scrollLeft();
        var viewportTop = $(window).scrollTop();
        var maxLeft = Math.max(viewportLeft + margin, viewportLeft + $(window).width() - popupSize.width - margin);
        var maxTop = Math.max(viewportTop + margin, viewportTop + $(window).height() - popupSize.height - margin);

        return {
            left: Math.min(Math.max(viewportLeft + margin, left), maxLeft),
            top: Math.min(Math.max(viewportTop + margin, top), maxTop)
        };
    }

    /** STAMP: 2026-09-05 - Keep at least 80% of the selected object's visible
     * bounds clear whenever viewport space permits. Evaluate all four sides
     * and viewport edges, preferring zero overlap, then proximity to the trigger.
     * Fabric viewport transforms and CSS canvas scaling are both respected.
     * On constrained screens choose the least overlap without moving the object.
     */
    function positionColorPickerBesideSelection(preferred) {
        var target = canvas && canvas.getActiveObject ? canvas.getActiveObject() : null;
        if (!target || !canvas.upperCanvasEl || !target.getCoords) return preferred;
        var rect = canvas.upperCanvasEl.getBoundingClientRect();
        var transform = canvas.viewportTransform || [1, 0, 0, 1, 0, 0];
        var scaleX = rect.width / canvas.getWidth();
        var scaleY = rect.height / canvas.getHeight();
        var scrollX = window.scrollX || 0;
        var scrollY = window.scrollY || 0;
        var points = target.getCoords().map(function (point) {
            return {
                x: rect.left + (transform[0] * point.x + transform[2] * point.y + transform[4]) * scaleX + scrollX,
                y: rect.top + (transform[1] * point.x + transform[3] * point.y + transform[5]) * scaleY + scrollY
            };
        });
        var left = Math.max(scrollX, rect.left + scrollX, Math.min.apply(null, points.map(function (point) { return point.x; })));
        var right = Math.min(scrollX + window.innerWidth, rect.right + scrollX, Math.max.apply(null, points.map(function (point) { return point.x; })));
        var top = Math.max(scrollY, rect.top + scrollY, Math.min.apply(null, points.map(function (point) { return point.y; })));
        var bottom = Math.min(scrollY + window.innerHeight, rect.bottom + scrollY, Math.max.apply(null, points.map(function (point) { return point.y; })));
        if (right <= left || bottom <= top) return preferred;
        var size = getColorPickerPopupSize();
        var gap = 12;
        var xs = [left - size.width - gap, right + gap, left, right - size.width,
            scrollX + 16, scrollX + window.innerWidth - size.width - 16, preferred.left];
        var ys = [top - size.height - gap, bottom + gap, top, bottom - size.height,
            scrollY + 16, scrollY + window.innerHeight - size.height - 16, preferred.top];
        var best = null;
        xs.forEach(function (x) {
            ys.forEach(function (y) {
                var candidate = {
                    left: Math.max(scrollX + 16, Math.min(scrollX + window.innerWidth - size.width - 16, x)),
                    top: Math.max(scrollY + 16, Math.min(scrollY + window.innerHeight - size.height - 16, y))
                };
                var overlap = Math.max(0, Math.min(right, candidate.left + size.width) - Math.max(left, candidate.left))
                    * Math.max(0, Math.min(bottom, candidate.top + size.height) - Math.max(top, candidate.top));
                var distance = Math.pow(candidate.left - preferred.left, 2) + Math.pow(candidate.top - preferred.top, 2);
                if (!best || overlap < best.overlap || (overlap === best.overlap && distance < best.distance)) {
                    best = { left: candidate.left, top: candidate.top, overlap: overlap, distance: distance };
                }
            });
        });
        return { left: best.left, top: best.top };
    }

    // Shared by Quick Actions so its deferred placement cannot cover the selection again.
    window.CGPositionColorPickerForSelection = function (trigger) {
        var $popup = ensureColorPickerPopupHost();
        if (!$popup.is(":visible")) return;
        var rect = trigger.getBoundingClientRect();
        var next = positionColorPickerBesideSelection({ left: rect.left + window.scrollX, top: rect.bottom + window.scrollY + 12 });
        $popup.css({ position: "absolute", left: next.left, top: next.top });
    };

    // STAMP: 2026-09-05 - Radius belongs to shapes, excluding circles,
    // text, images, widgets, and mixed/group selections.
    function supportsPaletteStrokeRadius(target) {
        return target && ["rect", "ellipse", "triangle", "polygon", "polyline", "path", "line"]
            .indexOf(String(target.type).toLowerCase()) !== -1;
    }

    function positionColorPickerPopup($trigger, leftOffset, topOffset) {
        if (!$trigger || !$trigger.length) {
            return;
        }

        // STAMP: 2026-09-05 - A palette replaces any open quick-action dropdown.
        window.dispatchEvent(new Event("cg:color-palette-opening"));

        var $popup = ensureColorPickerPopupHost();
        var isStrokeMode = colorMode === "objstroke"
            || colorMode === "objtextstroke"
            || colorMode === "objstrokehover";
        var activeStrokeObject = canvas && canvas.getActiveObject ? canvas.getActiveObject() : null;
        var activeStrokeWidth = activeStrokeObject && String(activeStrokeObject.type).toLowerCase() === "activeselection"
            ? Number(activeStrokeObject.getObjects()[0] && activeStrokeObject.getObjects()[0].strokeWidth)
            : Number(activeStrokeObject && activeStrokeObject.strokeWidth);
        activeStrokeWidth = Number.isFinite(activeStrokeWidth) ? activeStrokeWidth : 1;
        $("#colorPickerStrokeWidthArea").prop("hidden", !isStrokeMode);
        $("#colorPickerHighlightStyleArea").prop("hidden", colorMode !== "objtexthighlight");
        $("#colorPickerStrokeWidth").val(Math.max(0, Math.min(100, activeStrokeWidth)));
        $("#colorPickerStrokeWidthValue").text(Math.max(0, Math.min(100, activeStrokeWidth)));
        var showRadius = isStrokeMode && supportsPaletteStrokeRadius(activeStrokeObject);
        $("#colorPickerStrokeRadiusArea").prop("hidden", !showRadius);
        var radius = showRadius ? Math.max(0, Math.min(50, Math.round(Number(activeStrokeObject.rx || 0) * Math.abs(activeStrokeObject.scaleX || 1)))) : 0;
        $("#colorPickerStrokeRadius").val(radius);
        $("#colorPickerStrokeRadiusValue").text(radius);

        var triggerElement = $trigger.get(0);
        var triggerOffset = $trigger.offset();

        if (!triggerOffset || !triggerElement) {
            return;
        }

        var propertyDock = $trigger.closest("#propertybars, #canvassettings");
        var isPropertyDockTrigger = propertyDock.length > 0;
        var nextPosition;

        /* Property-dock aware placement stamped 2026-04-29:
           the shared color popup should open beside the inspector when the
           trigger lives inside the right/left property dock. Prefer the side
           with enough room; if one side is constrained, flip to the other. */
        if (isPropertyDockTrigger) {
            var popupSize = getColorPickerPopupSize();
            var dockRect = propertyDock.get(0).getBoundingClientRect();
            var triggerRect = triggerElement.getBoundingClientRect();
            var viewportWidth = $(window).width();
            var viewportTop = $(window).scrollTop();
            var viewportLeft = $(window).scrollLeft();
            var horizontalGap = 18;
            var verticalOffset = Math.abs(topOffset || 0) > 60 ? -24 : (topOffset || -24);
            var leftSpace = dockRect.left - horizontalGap;
            var rightSpace = viewportWidth - dockRect.right - horizontalGap;
            var openOnLeft = leftSpace >= popupSize.width || leftSpace >= rightSpace;
            var sideAlignedLeft = openOnLeft
                ? viewportLeft + dockRect.left - popupSize.width - horizontalGap
                : viewportLeft + dockRect.right + horizontalGap;
            var sideAlignedTop = viewportTop + triggerRect.top + verticalOffset;

            nextPosition = clampColorPickerPopupPosition(sideAlignedLeft, sideAlignedTop);
        } else {
            nextPosition = clampColorPickerPopupPosition(
                triggerOffset.left + (leftOffset || 0),
                triggerOffset.top + $trigger.outerHeight() + (topOffset || 0)
            );
        }

        nextPosition = positionColorPickerBesideSelection(nextPosition);
        $popup.css({
            position: "absolute",
            left: nextPosition.left,
            top: nextPosition.top
        }).show();
    }

    function keepColorPickerPopupInView() {
        var $popup = ensureColorPickerPopupHost();

        if (!$popup.is(":visible")) {
            return;
        }

        var nextPosition = clampColorPickerPopupPosition(
            parseFloat($popup.css("left")) || 0,
            parseFloat($popup.css("top")) || 0
        );

        $popup.css({
            left: nextPosition.left,
            top: nextPosition.top
        });
    }

    function stopColorPickerPopupDrag() {
        if (!colorPickerPopupDragState.isDragging) {
            return;
        }

        colorPickerPopupDragState.isDragging = false;
        ensureColorPickerPopupHost().removeClass("cg-color-popup--dragging");
        $(document.body).css("user-select", "");
    }

