    function isValidHexColor(color) {
        return /^#(?:[0-9a-fA-F]{3}|[0-9a-fA-F]{6})$/.test(color);
    }

    $('#hexColorInput').on('input', function () {
        let val = $(this).val().replace(/[^#0-9a-fA-F]/g, ''); // remove invalid characters
        val = val.replace(/^#+/, ''); // remove all leading #

        if (val.length > 6) {
            val = val.substring(0, 6); // limit to 6 characters max
        }

        // Add # prefix
        if (val.length > 0) {
            val = '#' + val;
        }

        $(this).val(val);

        /* STAMP: Direct hex colour entry (2026-08-17)
           Apply a complete six-digit value immediately; three-digit values
           remain available through Enter or normal field change. */
        $(this).toggleClass("is-invalid", val.length > 0 && !isValidHexColor(val));
        if (/^#[0-9a-fA-F]{6}$/.test(val)) {
            $(this).trigger("change");
        }
    }).on('keydown', function (e) {
        if (e.key !== "Enter") {
            return;
        }

        e.preventDefault();
        if (isValidHexColor($(this).val().trim())) {
            $(this).removeClass("is-invalid").trigger("change");
        } else {
            $(this).addClass("is-invalid");
        }
    });


