    /**
     * Structured reference for create listeners keyboard.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    function createListenersKeyboard() {
        if (hdnincanvas == "1") {
            document.onkeydown = onKeyDownHandler;
            //document.onkeyup = onKeyUpHandler;
        }
    }

    /**
     * Structured reference for on key down handler.
     *
     * @param {*} event Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    function onKeyDownHandler(event) {
        //event.preventDefault();
        var key;
        if (window.event) {
            key = window.e.which;
        }
        else {
            key = e.which;
        }

        switch (key) {
            //////////////
            // Shortcuts
            //////////////
            // Zoom In (Ctrl+"+")
            case 187: // Ctrl+"+"
                if (ableToShortcut()) {
                    if (event.ctrlKey) {
                        event.preventDefault();
                        zoomIn();
                    }
                }
                break;
            // Zoom Out (Ctrl+"-")
            case 189: // Ctrl+"-"
                if (ableToShortcut()) {
                    if (event.ctrlKey) {
                        event.preventDefault();
                        zoomOut();
                    }
                }
                break;
            // Reset Zoom (Ctrl+"0")
            case 48: // Ctrl+"0"
                if (ableToShortcut()) {
                    if (event.ctrlKey) {
                        event.preventDefault();
                        resetZoom();
                    }
                }
                break;
            // Reset Zoom (Ctrl+"0")
            case 65: // Ctrl+"0"
                if (ableToShortcut()) {
                    if (event.ctrlKey) {
                        event.preventDefault();
                        if (hdnincanvas == "1") {
                            selectAllCanvasObjects();
                        }
                    }
                }
                break;
            default:
                // TODO
                break;
        }
    }

    /**
     * Structured reference for able to shortcut.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    function ableToShortcut() {
        //TODO check all cases for this    
        if ($("textarea").is(":focus")) {
            return false;
        }
        if ($(":text").is(":focus")) {
            return false;
        }
        return true;
    }

    //Reset Cnavas Objects
    /**
     * Structured reference for reset canvas objects.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    function ResetCanvasObjects() {
        $(".chkobjsel").prop("checked", false);
        $("#propertybars").fadeOut();
        $("#divGeneralProperties").fadeOut();
        IsTarget = 0;
        resetFormatPainterState();
        canvas.discardActiveObject();
        canvas.requestRenderAll();
    }

    //panToByMouseCoords
    /**
     * Structured reference for pan to by mouse coords.
     *
     * @param {*} xDelta Runtime parameter preserved from the source implementation.
     * @param {*} yDelta Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    function panToByMouseCoords(xDelta, yDelta) {

        getFabricCanvases().forEach(function (elementValue) {
            var currentTop = Number(elementValue.css("top").replace(/[^\d\.\-]/g, ''));
            var currentLeft = Number(elementValue.css("left").replace(/[^\d\.\-]/g, ''));
            currentTop = zoomCalcYpos(currentTop + yDelta);
            currentLeft = zoomCalcXpos(currentLeft + xDelta);
            elementValue.css("top", currentTop);
            elementValue.css("left", currentLeft);
        });
    }

    //Zoom By Mouse Coordinates
    /**
     * Structured reference for zoom by mouse coords.
     *
     * @param {*} event Runtime parameter preserved from the source implementation.
     * @param {*} direction Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    function zoomByMouseCoords(event, direction) {
        //if selectable element was clicked, don't zoom, just return:
        /*if (canvas.getActiveObject()) {
         return false;
         }*/

        if (!direction || !event.e) return;

        var pointer = canvas.getScenePoint(event.e);
        if (direction.toLowerCase() == "in") {
            if (canvas.getZoom().toFixed(5) > zoomMax) {

                return;
            }
            zoomIn();
        }
        if (direction.toLowerCase() == "out") {
            if (canvas.getZoom().toFixed(5) <= 1) {
                return;
            }
            zoomOut();
        }
        zoomToPosition(zoomInCalcXpos(pointer.x), zoomInCalcYpos(pointer.y));
    }

    // Zoom In
    /**
     * Increase the editor canvas zoom while keeping UI zoom state synchronized.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    zoomIn = function () {
        // TODO limit the max canvas zoom in
        scaleFactorValue = scaleFactorValue + 10;
        $("#lblScaleFactor").val(scaleFactorValue);
        zoomInValue = canvas.getZoom() + 0.20;
        canvas.zoomToPoint({ x: canvas.width / 2, y: canvas.height / 2 }, zoomInValue);
    };

    //Zoom Out
    /**
     * Decrease the editor canvas zoom while keeping UI zoom state synchronized.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    zoomOut = function () {
        zoomValue = canvas.getZoom();
        if (zoomValue <= 1) {
            return;
        }
        scaleFactorValue = scaleFactorValue - 10;
        $("#lblScaleFactor").val(scaleFactorValue);
        zoomOutValue = canvas.getZoom() - 0.20;
        canvas.zoomToPoint({ x: canvas.width / 2, y: canvas.height / 2 }, zoomOutValue);
        var zoom = canvas.getZoom();
        var vpt = canvas.viewportTransform;
        vpt[4] = (canvas.getWidth() - canvas_width * zoom) / 2;
        vpt[5] = (canvas.getHeight() - canvas_height * zoom) / 2;
        canvas.requestRenderAll();
    };

    //Reset Zoom
    /**
     * Restore the canvas zoom level and related viewport offsets to defaults.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    resetZoom = function () {
        scaleFactorValue = 100;
        $("#lblScaleFactor").val(scaleFactorValue);
        zoomOutValue = 1;
        canvas.zoomToPoint(new fabric.Point(canvas.width / 2, canvas.height / 2), zoomOutValue);
        canvas.setViewportTransform([1, 0, 0, 1, 0, 0]);
    };

    /**
     * Structured reference for reload.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    function Reload() {
        location.reload();
    }
    /**
     * Structured reference for zoom canvas selection.
     *
     * @param {*} isSelectable Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    function zoomCanvasSelection(isSelectable) {
        isSelectable = (isSelectable == true);
        canvas.selection = isSelectable;
        canvas.forEachObject(function (o) {
            o.selectable = isSelectable;
        });
    }
    /**
     * Structured reference for zoom in calc xpos.
     *
     * @param {*} xPos Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    function zoomInCalcXpos(xPos) {
        xPos *= canvas.getZoom();
        return zoomCalcXpos((canvasWidth / 2) - xPos);
    }
    /**
     * Structured reference for zoom calc xpos.
     *
     * @param {*} xPos Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    function zoomCalcXpos(xPos) {
        if (xPos > 0) {
            return 0;
        }
        if (xPos + canvas.getWidth() < canvasWidth) {
            return canvasWidth - canvas.getWidth();
        }
        return xPos;
    }
    /**
     * Structured reference for zoom in calc ypos.
     *
     * @param {*} yPos Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    function zoomInCalcYpos(yPos) {
        yPos *= canvas.getZoom();
        return zoomCalcYpos((canvasHeight / 2) - yPos);
    }
    /**
     * Structured reference for zoom calc ypos.
     *
     * @param {*} yPos Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    function zoomCalcYpos(yPos) {
        if (yPos > 0) {
            return 0;
        }
        if (yPos + canvas.getHeight() < canvasHeight) {
            return canvasHeight - canvas.getHeight();
        }
        return yPos;
    }
    /**
     * Structured reference for zoom to position.
     *
     * @param {*} x Runtime parameter preserved from the source implementation.
     * @param {*} y Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    function zoomToPosition(x, y) {
        zoomMoveToPosition('top', y);
        zoomMoveToPosition('left', x);
    }
    /**
     * Structured reference for zoom move to position.
     *
     * @param {*} position Runtime parameter preserved from the source implementation.
     * @param {*} numericValue Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    function zoomMoveToPosition(position, numericValue) {
        getFabricCanvases().forEach(function (elementValue) {
            elementValue.css(position, numericValue);
        });
    }

    /**
     * Structured reference for zoom move step to position.
     *
     * @param {*} position Runtime parameter preserved from the source implementation.
     * @param {*} operator Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    function zoomMoveStepToPosition(position, operator) {
        getFabricCanvases().forEach(function (elementValue) {
            var current = Number(elementValue.css(position).replace(/[^\d\.\-]/g, ''));
            current = eval(current + operator + 20);

            if (position == "left" || position == "right") current = zoomCalcXpos(current);
            if (position == "top" || position == "bottom") current = zoomCalcYpos(current);

            elementValue.css(position, current);
        });
    }
    //Canvas Properties Ends ================================================================================================================================================================


    //Image Section Starts ================================================================================================================================================================
    /* =========================================================
       FABRIC IMAGE OPTIMIZE + ADD + EDIT (REPLACE) + CROP (MODAL CANVAS)
       ---------------------------------------------------------
       Works with your existing modal HTML:
       - #origPreview (img)
       - #origCropCanvas (canvas overlay)
       - #btnResetCrop
       - #optPreview, #optMaxW, #optMaxH, #optQuality, #optFormat, #optQLabel
       - #btnUseOriginal, #btnUseOptimized
    ========================================================= */

    /* =========================================================
       A) STATE
    ========================================================= */
    var _pendingMode = null;            // "add" | "edit"
    var _pendingImageFile = null;       // File
    var _pendingOriginalDataUrl = null; // string
    var _pendingOptimized = null;       // { dataUrl, blob, w, h, mime, bytes }
    var _pendingDebounceTimer = null;

    var _crop = {
        enabled: true,

        _img: null,   // JS Image
        _origW: 0,
        _origH: 0,

        // selection in SOURCE pixels (original image coords)
        x: 0, y: 0, w: 0, h: 0,
        hasSelection: false,

        // drag in CANVAS CSS pixels
        dragging: false,
        startX: 0, startY: 0,
        endX: 0, endY: 0,

        // contain mapping (image drawn into canvas)
        dispX: 0, dispY: 0,
        dispW: 0, dispH: 0
    };

    /* =========================================================
       B) HELPERS
    ========================================================= */
    function clamp(v, min, max) { return Math.max(min, Math.min(max, v)); }

    /**
     * Structured reference for format bytes.
     *
     * @param {*} bytes Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    function formatBytes(bytes) {
        if (bytes === null || bytes === undefined) return "";
        if (bytes === 0) return "0 B";
        var k = 1024;
        var sizes = ["B", "KB", "MB", "GB"];
        var i = Math.floor(Math.log(bytes) / Math.log(k));
        i = Math.max(0, Math.min(i, sizes.length - 1));
        var val = bytes / Math.pow(k, i);
        return val.toFixed(val >= 10 || i === 0 ? 0 : 1) + " " + sizes[i];
    }

    /**
     * Structured reference for blob to data url.
     *
     * @param {*} blob Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    function blobToDataUrl(blob) {
        return new Promise(function (resolve, reject) {
            var reader = new FileReader();
            reader.onload = function (e) { resolve(e.target.result); };
            reader.onerror = reject;
            reader.readAsDataURL(blob);
        });
    }

    /**
     * Structured reference for load image from data url.
     *
     * @param {*} dataUrl Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    function loadImageFromDataUrl(dataUrl) {
        return new Promise(function (resolve, reject) {
            var img = new Image();
            img.onload = function () { resolve(img); };
            img.onerror = reject;
            img.src = dataUrl;
        });
    }

    /* Canvas buffer must match CSS size (and handle HiDPI) */
    /**
     * Structured reference for ensure canvas pixels match css.
     *
     * @param {*} canvas Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    function ensureCanvasPixelsMatchCSS(canvas) {
        var cssW = Math.max(1, canvas.clientWidth);
        var cssH = Math.max(1, canvas.clientHeight);
        var dpr = window.devicePixelRatio || 1;

        var targetW = Math.round(cssW * dpr);
        var targetH = Math.round(cssH * dpr);

        if (canvas.width !== targetW || canvas.height !== targetH) {
            canvas.width = targetW;
            canvas.height = targetH;

            var ctx = canvas.getContext("2d");
            ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
        }
    }

    /* =========================================================
       C) CROP DRAWING ON YOUR MODAL CANVAS (#origCropCanvas)
    ========================================================= */
    /**
     * Structured reference for draw base to crop canvas.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    function drawBaseToCropCanvas() {
        var canvas = document.getElementById("origCropCanvas");
        if (!canvas || !_crop._img) return;

        ensureCanvasPixelsMatchCSS(canvas);

        var ctx = canvas.getContext("2d");
        var cw = canvas.clientWidth;
        var ch = canvas.clientHeight;

        var iw = _crop._origW;
        var ih = _crop._origH;

        // contain mapping
        var scale = Math.min(cw / iw, ch / ih);
        var dw = Math.round(iw * scale);
        var dh = Math.round(ih * scale);
        var dx = Math.floor((cw - dw) / 2);
        var dy = Math.floor((ch - dh) / 2);

        _crop.dispX = dx;
        _crop.dispY = dy;
        _crop.dispW = dw;
        _crop.dispH = dh;

        ctx.clearRect(0, 0, cw, ch);
        ctx.drawImage(_crop._img, 0, 0, iw, ih, dx, dy, dw, dh);
    }

    /**
     * Structured reference for get selection rect canvas px.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    function getSelectionRectCanvasPx() {
        var sel = null;

        if (_crop.dragging) {
            sel = {
                x1: Math.min(_crop.startX, _crop.endX),
                y1: Math.min(_crop.startY, _crop.endY),
                x2: Math.max(_crop.startX, _crop.endX),
                y2: Math.max(_crop.startY, _crop.endY)
            };
        } else if (_crop.hasSelection) {
            // source -> canvas px
            var x1 = _crop.dispX + (_crop.x / _crop._origW) * _crop.dispW;
            var y1 = _crop.dispY + (_crop.y / _crop._origH) * _crop.dispH;
            var x2 = _crop.dispX + ((_crop.x + _crop.w) / _crop._origW) * _crop.dispW;
            var y2 = _crop.dispY + ((_crop.y + _crop.h) / _crop._origH) * _crop.dispH;
            sel = { x1: x1, y1: y1, x2: x2, y2: y2 };
        }

        if (!sel) return null;

        // clamp inside drawn image rect
        sel.x1 = clamp(sel.x1, _crop.dispX, _crop.dispX + _crop.dispW);
        sel.y1 = clamp(sel.y1, _crop.dispY, _crop.dispY + _crop.dispH);
        sel.x2 = clamp(sel.x2, _crop.dispX, _crop.dispX + _crop.dispW);
        sel.y2 = clamp(sel.y2, _crop.dispY, _crop.dispY + _crop.dispH);

        return sel;
    }

    /**
     * Structured reference for draw crop overlay.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    function drawCropOverlay() {
        var canvas = document.getElementById("origCropCanvas");
        if (!canvas || !_crop._img) return;

        var ctx = canvas.getContext("2d");
        var cw = canvas.clientWidth;
        var ch = canvas.clientHeight;

        drawBaseToCropCanvas();

        var sel = getSelectionRectCanvasPx();
        if (!sel) return;

        var x = sel.x1, y = sel.y1;
        var w = sel.x2 - sel.x1;
        var h = sel.y2 - sel.y1;

        if (w < 1 || h < 1) return;

        ctx.save();
        ctx.fillStyle = "rgba(0,0,0,0.35)";
        ctx.fillRect(0, 0, cw, ch);

        ctx.clearRect(x, y, w, h);

        ctx.strokeStyle = "rgba(255,255,255,0.95)";
        ctx.lineWidth = 2;
        ctx.strokeRect(x + 1, y + 1, w - 2, h - 2);
        ctx.restore();
    }

    /**
     * Structured reference for canvas px to source px.
     *
     * @param {*} cx Runtime parameter preserved from the source implementation.
     * @param {*} cy Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    function canvasPxToSourcePx(cx, cy) {
        var dx = cx - _crop.dispX;
        var dy = cy - _crop.dispY;

        dx = clamp(dx, 0, _crop.dispW);
        dy = clamp(dy, 0, _crop.dispH);

        var sx = (dx / _crop.dispW) * _crop._origW;
        var sy = (dy / _crop.dispH) * _crop._origH;

        return { x: sx, y: sy };
    }

    /**
     * Structured reference for bind crop events once.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    function bindCropEventsOnce() {
        var canvas = document.getElementById("origCropCanvas");
        if (!canvas || canvas.__cropBound) return;
        canvas.__cropBound = true;

        // ensure canvas receives mouse
        canvas.style.pointerEvents = "auto";
        canvas.style.zIndex = "5";

        canvas.addEventListener("mousedown", function (ev) {
            if (!_crop.enabled || !_crop._img) return;

            var rect = canvas.getBoundingClientRect();
            _crop.dragging = true;
            _crop.startX = ev.clientX - rect.left;
            _crop.startY = ev.clientY - rect.top;
            _crop.endX = _crop.startX;
            _crop.endY = _crop.startY;

            drawCropOverlay();
        });

        window.addEventListener("mousemove", function (ev) {
            if (!_crop.dragging) return;

            var rect = canvas.getBoundingClientRect();
            _crop.endX = ev.clientX - rect.left;
            _crop.endY = ev.clientY - rect.top;

            drawCropOverlay();
        });

        window.addEventListener("mouseup", function () {
            if (!_crop.dragging) return;
            _crop.dragging = false;

            var x1 = Math.min(_crop.startX, _crop.endX);
            var y1 = Math.min(_crop.startY, _crop.endY);
            var x2 = Math.max(_crop.startX, _crop.endX);
            var y2 = Math.max(_crop.startY, _crop.endY);

            // tiny selection -> clear crop
            if (Math.abs(x2 - x1) < 5 || Math.abs(y2 - y1) < 5) {
                _crop.hasSelection = false;
                drawCropOverlay();
                rebuildOptimizedPreview().catch(function (e) { console.error(e); });
                return;
            }

            var p1 = canvasPxToSourcePx(x1, y1);
            var p2 = canvasPxToSourcePx(x2, y2);

            _crop.x = Math.floor(p1.x);
            _crop.y = Math.floor(p1.y);
            _crop.w = Math.floor(p2.x - p1.x);
            _crop.h = Math.floor(p2.y - p1.y);
            _crop.hasSelection = true;

            drawCropOverlay();
            rebuildOptimizedPreview().catch(function (e) { console.error(e); });
        });

        $("#btnResetCrop").off("click.__resetCrop").on("click.__resetCrop", function () {
            _crop.hasSelection = false;
            _crop.x = 0; _crop.y = 0; _crop.w = 0; _crop.h = 0;
            drawCropOverlay();
            rebuildOptimizedPreview().catch(function (e) { console.error(e); });
        });
    }

    /* Load original into crop system */
    /**
     * Structured reference for set crop image from data url.
     *
     * This async function preserves the source behavior while making control flow
     * easier to trace in the structured reference copy.
     *
     * @param {*} dataUrl Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    async function setCropImageFromDataUrl(dataUrl) {
        $("#origPreview").attr("src", dataUrl);

        var img = await loadImageFromDataUrl(dataUrl);
        _crop._img = img;
        _crop._origW = img.naturalWidth || img.width;
        _crop._origH = img.naturalHeight || img.height;

        bindCropEventsOnce();

        // draw after modal layout
        setTimeout(function () {
            drawCropOverlay();
        }, 0);
    }

    /* Modal timing: redraw after shown (sizes become non-zero) */
    $("#imageOptimizeModal")
        .off("shown.bs.modal.__crop")
        .on("shown.bs.modal.__crop", function () {
            setTimeout(function () {
                if (_crop._img) drawCropOverlay();
            }, 0);
        });

    window.addEventListener("resize", function () {
        if ($("#imageOptimizeModal").hasClass("show") && _crop._img) {
            drawCropOverlay();
        }
    });

    /* =========================================================
       D) CROPPED OUTPUT HELPERS (THIS IS WHAT YOU ASKED)
       - getCroppedOriginalDataUrl(): crop only (no resize/compress)
    ========================================================= */
    /**
     * Structured reference for get cropped original data url.
     *
     * This async function preserves the source behavior while making control flow
     * easier to trace in the structured reference copy.
     *
     * @param {*} outputMime Runtime parameter preserved from the source implementation.
     * @param {*} outputQuality Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    async function getCroppedOriginalDataUrl(outputMime, outputQuality) {
        if (!_crop._img) throw new Error("Crop image not loaded.");

        outputMime = outputMime || "image/png";
        outputQuality = (outputQuality == null) ? 0.92 : outputQuality;

        var img = _crop._img;
        var ow = _crop._origW;
        var oh = _crop._origH;

        var sx = 0, sy = 0, sw = ow, sh = oh;

        if (_crop.enabled && _crop.hasSelection && _crop.w > 0 && _crop.h > 0) {
            sx = clamp(_crop.x, 0, ow - 1);
            sy = clamp(_crop.y, 0, oh - 1);
            sw = clamp(_crop.w, 1, ow - sx);
            sh = clamp(_crop.h, 1, oh - sy);
        }

        var c = document.createElement("canvas");
        c.width = sw;
        c.height = sh;

        var ctx = c.getContext("2d");
        ctx.imageSmoothingEnabled = true;
        ctx.imageSmoothingQuality = "high";
        ctx.drawImage(img, sx, sy, sw, sh, 0, 0, sw, sh);

        if (outputMime === "image/png") return c.toDataURL(outputMime);
        return c.toDataURL(outputMime, outputQuality);
    }

    /* =========================================================
       E) OPTIMIZER (CROP + RESIZE + COMPRESS) - ONLY ONE
    ========================================================= */
    /**
     * Structured reference for optimize image file.
     *
     * This async function preserves the source behavior while making control flow
     * easier to trace in the structured reference copy.
     *
     * @param {*} file Runtime parameter preserved from the source implementation.
     * @param {*} opts Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    async function optimizeImageFile(file, opts) {
        var maxW = parseInt(opts.maxW || 1600, 10);
        var maxH = parseInt(opts.maxH || 1600, 10);
        var quality = Math.max(0.1, Math.min(0.98, opts.quality || 0.8));
        var mime = opts.mime || "image/webp";

        // file -> dataURL
        var originalDataUrl = await new Promise(function (resolve, reject) {
            var fr = new FileReader();
            fr.onload = function (e) { resolve(e.target.result); };
            fr.onerror = reject;
            fr.readAsDataURL(file);
        });

        // Load original
        var img = await loadImageFromDataUrl(originalDataUrl);
        var ow = img.naturalWidth || img.width;
        var oh = img.naturalHeight || img.height;

        // set crop source image
        _crop._img = img;
        _crop._origW = ow;
        _crop._origH = oh;

        // crop rect
        var srcX = 0, srcY = 0, srcW = ow, srcH = oh;
        if (_crop.enabled && _crop.hasSelection && _crop.w > 0 && _crop.h > 0) {
            srcX = clamp(_crop.x, 0, ow - 1);
            srcY = clamp(_crop.y, 0, oh - 1);
            srcW = clamp(_crop.w, 1, ow - srcX);
            srcH = clamp(_crop.h, 1, oh - srcY);
        }

        // resize from cropped rect
        var ratio = Math.min(maxW / srcW, maxH / srcH, 1);
        var tw = Math.max(1, Math.round(srcW * ratio));
        var th = Math.max(1, Math.round(srcH * ratio));

        var c = document.createElement("canvas");
        c.width = tw;
        c.height = th;

        var ctx = c.getContext("2d");
        ctx.imageSmoothingEnabled = true;
        ctx.imageSmoothingQuality = "high";
        ctx.drawImage(img, srcX, srcY, srcW, srcH, 0, 0, tw, th);

        var blob = await new Promise(function (resolve) {
            if (mime === "image/png") c.toBlob(function (b) { resolve(b); }, mime);
            else c.toBlob(function (b) { resolve(b); }, mime, quality);
        });

        if (!blob) {
            var fallbackUrl = c.toDataURL(mime, quality);
            var res = await fetch(fallbackUrl);
            blob = await res.blob();
        }

        var optimizedDataUrl = await blobToDataUrl(blob);

        return {
            originalDataUrl: originalDataUrl,
            originalMeta: { w: ow, h: oh, bytes: file.size, mime: file.type || "unknown" },
            optimized: { blob: blob, dataUrl: optimizedDataUrl, w: tw, h: th, mime: mime, bytes: blob.size },
            cropMeta: { x: srcX, y: srcY, w: srcW, h: srcH }
        };
    }

    /* =========================================================
       F) MODAL PREVIEW BUILDER (ONLY ONE)
    ========================================================= */
    /**
     * Structured reference for rebuild optimized preview.
     *
     * This async function preserves the source behavior while making control flow
     * easier to trace in the structured reference copy.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    async function rebuildOptimizedPreview() {
        if (!_pendingImageFile) return;

        var maxW = $("#optMaxW").val();
        var maxH = $("#optMaxH").val();
        var q = parseInt($("#optQuality").val(), 10) / 100;
        var mime = $("#optFormat").val();

        $("#optQLabel").text(q.toFixed(2));

        var result = await optimizeImageFile(_pendingImageFile, {
            maxW: maxW,
            maxH: maxH,
            quality: q,
            mime: mime
        });

        _pendingOriginalDataUrl = result.originalDataUrl;
        _pendingOptimized = result.optimized;

        // ORIGINAL: show meta + set up crop canvas from original
        await setCropImageFromDataUrl(result.originalDataUrl);
        $("#origType").text(result.originalMeta.mime);
        $("#origSize").text(formatBytes(result.originalMeta.bytes));
        $("#origDim").text(result.originalMeta.w + " x " + result.originalMeta.h);

        // OPTIMIZED preview comes from optimizer (already includes crop selection)
        $("#optPreview").attr("src", _pendingOptimized.dataUrl);
        $("#optType").text(_pendingOptimized.mime);
        $("#optSize").text(formatBytes(_pendingOptimized.bytes));
        $("#optDim").text(_pendingOptimized.w + " x " + _pendingOptimized.h);

        var saved = result.originalMeta.bytes > 0
            ? ((1 - (_pendingOptimized.bytes / result.originalMeta.bytes)) * 100)
            : 0;
        $("#optSaved").text(saved > 0 ? saved.toFixed(1) + "%" : "0%");
    }

