    /**
     * Remove executable and externally loaded SVG content before Fabric parses it.
     * Visual vector elements, gradients, masks, and local fragment references remain intact.
     *
     * @param {string} svgMarkup Raw SVG file text.
     * @returns {string} Sanitized SVG markup safe for the canvas importer.
     */
    function sanitizeSvgObjectMarkup(svgMarkup) {
        var parser = new DOMParser();
        var documentNode = parser.parseFromString(svgMarkup, "image/svg+xml");
        var root = documentNode.documentElement;

        if (!root || root.nodeName.toLowerCase() !== "svg" || documentNode.querySelector("parsererror")) {
            throw new Error("The selected file is not a valid SVG.");
        }

        documentNode.querySelectorAll("script, foreignObject, iframe, object, embed").forEach(function (node) {
            node.remove();
        });
        documentNode.querySelectorAll("*").forEach(function (node) {
            Array.from(node.attributes || []).forEach(function (attribute) {
                var attributeName = attribute.name.toLowerCase();
                var attributeValue = String(attribute.value || "").trim();
                var isLink = attributeName === "href" || attributeName === "xlink:href";
                var isSafeLink = attributeValue.charAt(0) === "#" || /^data:image\//i.test(attributeValue);

                if (attributeName.indexOf("on") === 0 || (isLink && attributeValue && !isSafeLink)) {
                    node.removeAttribute(attribute.name);
                }
            });
        });

        return new XMLSerializer().serializeToString(root);
    }

    /**
     * Add SVG markup as one editable Fabric group that exactly fills the canvas.
     * Independent X/Y scaling guarantees full coverage for SVGs of any aspect ratio.
     *
     * @param {string} svgMarkup Sanitized SVG markup.
     * @param {string} fileName Original file name used for the layer label.
     * @returns {Promise<boolean>} Resolves after the SVG is added and persisted.
     */
    function addFullCanvasSvgObject(svgMarkup, fileName) {
        return fabric.loadSVGFromString(svgMarkup).then(function (result) {
            if (!result.objects || !result.objects.length) {
                throw new Error("The selected SVG does not contain drawable vector objects.");
            }

            var svgObject = fabric.util.groupSVGElements(result.objects, result.options || {});
            var objectWidth = Number(svgObject.width) || Number(result.options && result.options.width);
            var objectHeight = Number(svgObject.height) || Number(result.options && result.options.height);

            if (!objectWidth || !objectHeight) {
                throw new Error("The selected SVG has no usable dimensions.");
            }

            var objectId = generate_id("svg_");
            svgObject.set({
                id: objectId,
                name: String(fileName || "SVG Object").replace(/\.svg$/i, ""),
                left: 0,
                top: 0,
                originX: "left",
                originY: "top",
                scaleX: canvas.getWidth() / objectWidth,
                scaleY: canvas.getHeight() / objectHeight,
                transparentCorners: true
            });
            svgObject.setCoords();

            canvas.add(svgObject);
            canvas.setActiveObject(svgObject);
            anyobject++;

            if (typeof applyCanvasObjectActionControls === "function") applyCanvasObjectActionControls(svgObject);
            if (typeof pushControl === "function") pushControl(objectId, "SVG");
            if (typeof getselobjprop === "function") getselobjprop();
            if (typeof LoadTimeline === "function") LoadTimeline();
            if (typeof syncBlankSlideActions === "function") syncBlankSlideActions();

            if (generated_slides && generated_slides[slide_index]) {
                generated_slides[slide_index].jsonobj = canvas.toObject(["id"]);
                generated_slides[slide_index].svg = encodeURIComponent(canvas.toSVG());
                generated_slides[slide_index].imgprev = canvas.toDataURL();
            }
            if (typeof updateCanvasState === "function") updateCanvasState();
            canvas.requestRenderAll();
            setTimeout(function () {
                updateSlideThumbnail(selected_slide_id, canvas.toDataURL());
            }, 250);

            return true;
        });
    }

    $('#AddSvgObject').off('change.__svgObject').on('change.__svgObject', function (event) {
        var input = event.currentTarget;
        var file = input.files && input.files[0];
        if (!file) return;

        if (!/\.svg$/i.test(file.name) && file.type !== "image/svg+xml") {
            window.alert("Please select an SVG file.");
            input.value = "";
            return;
        }

        var reader = new FileReader();
        reader.onload = function () {
            try {
                var sanitizedMarkup = sanitizeSvgObjectMarkup(String(reader.result || ""));
                addFullCanvasSvgObject(sanitizedMarkup, file.name).catch(function (error) {
                    console.error("SVG object could not be added", error);
                    window.alert(error.message || "This SVG could not be added. Please try another file.");
                });
            } catch (error) {
                console.error("SVG object could not be read", error);
                window.alert(error.message || "This SVG could not be read. Please try another file.");
            } finally {
                input.value = "";
            }
        };
        reader.onerror = function () {
            input.value = "";
            window.alert("This SVG file could not be read.");
        };
        reader.readAsText(file);
    });

