    /* =========================================================
       I) FABRIC: EDIT IMAGE (unchanged - your original)
    ========================================================= */
    /**
     * Structured reference for get target image object for edit.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    function getTargetImageObjectForEdit() {
        var activeObject = canvas.getActiveObject();
        if (!activeObject) return null;

        if (isshowarray === "1") {
            var items = activeObject._objects;
            if (items && items[selectedarray] && items[selectedarray].type === "image") return items[selectedarray];
            return null;
        }

        if (activeObject.type === "image") return activeObject;

        if (activeObject._objects && activeObject._objects.length) {
            for (var i = 0; i < activeObject._objects.length; i++) {
                if (activeObject._objects[i].type === "image") return activeObject._objects[i];
            }
        }

        return null;
    }

    /* STAMP: 2026-08-31 - Original image download support for the image
       property panel. This deliberately reads the Fabric image source instead
       of rasterizing the canvas, so crop, scale, rotation, filters, and other
       presentation changes do not alter the downloaded asset. */
    function getOriginalImageSource(imageObject) {
        if (!imageObject) return "";

        var originalElement = imageObject._originalElement;
        if (originalElement) {
            var originalSource = originalElement.currentSrc || originalElement.src;
            if (originalSource) return originalSource;
        }

        if (typeof imageObject.getSrc === "function") {
            var fabricSource = imageObject.getSrc();
            if (fabricSource) return fabricSource;
        }

        var element = imageObject._element;
        return element ? (element.currentSrc || element.src || "") : "";
    }

    function getImageDownloadExtension(source, mimeType) {
        var normalizedMime = String(mimeType || "").toLowerCase();
        var mimeExtensions = {
            "image/jpeg": "jpg",
            "image/png": "png",
            "image/gif": "gif",
            "image/webp": "webp",
            "image/bmp": "bmp",
            "image/svg+xml": "svg"
        };
        if (mimeExtensions[normalizedMime]) return mimeExtensions[normalizedMime];

        var dataMimeMatch = String(source || "").match(/^data:(image\/[a-z0-9.+-]+)[;,]/i);
        if (dataMimeMatch && mimeExtensions[dataMimeMatch[1].toLowerCase()]) {
            return mimeExtensions[dataMimeMatch[1].toLowerCase()];
        }

        var cleanSource = String(source || "").split(/[?#]/)[0];
        var sourceExtension = cleanSource.match(/\.([a-z0-9]{2,5})$/i);
        return sourceExtension ? sourceExtension[1].toLowerCase().replace("jpeg", "jpg") : "png";
    }

    function getImageDownloadName(imageObject, source, mimeType) {
        var objectName = String(imageObject && imageObject.name ? imageObject.name : "canvas-image")
            .replace(/[<>:"/\\|?*\x00-\x1F]/g, "-")
            .replace(/[. ]+$/g, "")
            .trim() || "canvas-image";
        var extension = getImageDownloadExtension(source, mimeType);
        var existingExtension = objectName.match(/\.([a-z0-9]{2,5})$/i);
        return existingExtension ? objectName : objectName + "." + extension;
    }

    function triggerOriginalImageDownload(source, imageObject) {
        return fetch(source).then(function (response) {
            if (!response.ok && !String(source).startsWith("data:")) {
                throw new Error("Image download returned " + response.status + ".");
            }
            return response.blob();
        }).then(function (blob) {
            var objectUrl = URL.createObjectURL(blob);
            var downloadLink = document.createElement("a");
            downloadLink.href = objectUrl;
            downloadLink.download = getImageDownloadName(imageObject, source, blob.type);
            downloadLink.style.display = "none";
            document.body.appendChild(downloadLink);
            downloadLink.click();
            downloadLink.remove();
            window.setTimeout(function () { URL.revokeObjectURL(objectUrl); }, 1000);
            return true;
        });
    }

    $(document).off("click.__cgDownloadOriginalImage", "#btndownloadoriginalimage")
        .on("click.__cgDownloadOriginalImage", "#btndownloadoriginalimage", function (event) {
            event.preventDefault();
            var button = this;
            var imageObject = getTargetImageObjectForEdit();
            var source = getOriginalImageSource(imageObject);
            if (!imageObject || !source) {
                alert("Select an image object before downloading.");
                return;
            }

            button.disabled = true;
            triggerOriginalImageDownload(source, imageObject).catch(function (error) {
                console.error("Unable to download the original image.", error);
                alert("The original image could not be downloaded. Check that the image source is still available.");
            }).finally(function () {
                button.disabled = false;
            });
        });

    /* STAMP: 2026-08-26 - Native selection-based image crop bridge shared by
       the image inspector and Quick Action bar. The temporary crop rectangle
       is excluded from export; applying it persists standard Fabric crop
       coordinates so the result remains editable through JSON save/load. */
    window.CGImageCropEditor = (function () {
        var session = null;

        function clamp(value, minimum, maximum) {
            return Math.min(maximum, Math.max(minimum, Number(value) || 0));
        }

        function getImage() {
            return session ? session.image : getTargetImageObjectForEdit();
        }

        function setSelectionToImage() {
            if (!session) return null;
            var image = session.image;
            var selection = session.selection;
            var center = image.getCenterPoint();
            selection.set({
                left: center.x,
                top: center.y,
                width: image.width,
                height: image.height,
                scaleX: image.scaleX,
                scaleY: image.scaleY,
                angle: image.angle || 0,
                skewX: image.skewX || 0,
                skewY: image.skewY || 0
            });
            selection.setCoords();
            canvas.requestRenderAll();
            return getSelectionState();
        }

        function getSelectionState() {
            if (!session) return null;
            var image = session.image;
            var selection = session.selection;
            var inverseImageTransform = fabric.util.invertTransform(image.calcTransformMatrix());
            var localPoints = selection.getCoords().map(function (point) {
                return fabric.util.transformPoint(point, inverseImageTransform);
            });
            var halfWidth = image.width / 2;
            var halfHeight = image.height / 2;
            var minimumWidth = Math.max(1, image.width * 0.02);
            var minimumHeight = Math.max(1, image.height * 0.02);
            var rawLeft = Math.min.apply(null, localPoints.map(function (point) { return point.x; }));
            var rawRight = Math.max.apply(null, localPoints.map(function (point) { return point.x; }));
            var rawTop = Math.min.apply(null, localPoints.map(function (point) { return point.y; }));
            var rawBottom = Math.max.apply(null, localPoints.map(function (point) { return point.y; }));
            var localLeft = clamp(rawLeft, -halfWidth, halfWidth - minimumWidth);
            var localRight = clamp(rawRight, localLeft + minimumWidth, halfWidth);
            var localTop = clamp(rawTop, -halfHeight, halfHeight - minimumHeight);
            var localBottom = clamp(rawBottom, localTop + minimumHeight, halfHeight);
            return {
                localLeft: localLeft,
                localRight: localRight,
                localTop: localTop,
                localBottom: localBottom,
                cropWidth: localRight - localLeft,
                cropHeight: localBottom - localTop
            };
        }

        function finishSession(reselectImage) {
            if (!session) return null;
            var completedSession = session;
            var image = completedSession.image;
            session = null;
            canvas.remove(completedSession.selection);
            image.set({ selectable: completedSession.selectable, evented: completedSession.evented });
            if (reselectImage !== false) canvas.setActiveObject(image);
            canvas.requestRenderAll();
            return image;
        }

        function start() {
            if (session) return getSelectionState();
            var image = getTargetImageObjectForEdit();
            if (!image || !fabric.Rect) return null;
            var center = image.getCenterPoint();
            var selection = new fabric.Rect({
                left: center.x,
                top: center.y,
                originX: "center",
                originY: "center",
                width: image.width,
                height: image.height,
                scaleX: image.scaleX,
                scaleY: image.scaleY,
                angle: image.angle || 0,
                skewX: image.skewX || 0,
                skewY: image.skewY || 0,
                fill: "rgba(56, 167, 255, 0.12)",
                stroke: "#ffffff",
                strokeWidth: 2,
                strokeDashArray: [8, 5],
                strokeUniform: true,
                cornerColor: "#ffffff",
                cornerStrokeColor: "#1677ff",
                borderColor: "#38a7ff",
                transparentCorners: false,
                cornerSize: 12,
                lockRotation: true,
                excludeFromExport: true,
                isCropSelection: true,
                name: "Crop selection"
            });
            if (typeof selection.setControlsVisibility === "function") selection.setControlsVisibility({ mtr: false });
            session = {
                image: image,
                selection: selection,
                selectable: image.selectable,
                evented: image.evented
            };
            image.set({ selectable: false, evented: false });
            canvas.add(selection);
            canvas.setActiveObject(selection);
            canvas.requestRenderAll();
            return getSelectionState();
        }

        function cancel(reselectImage) {
            return finishSession(reselectImage !== false);
        }

        function apply() {
            if (!session) return null;
            var image = session.image;
            var state = getSelectionState();
            var localCenter = new fabric.Point(
                (state.localLeft + state.localRight) / 2,
                (state.localTop + state.localBottom) / 2
            );
            var sceneCenter = fabric.util.transformPoint(localCenter, image.calcTransformMatrix());
            image.set({
                cropX: (Number(image.cropX) || 0) + state.localLeft + image.width / 2,
                cropY: (Number(image.cropY) || 0) + state.localTop + image.height / 2,
                width: state.cropWidth,
                height: state.cropHeight
            });
            image.setPositionByOrigin(sceneCenter, "center", "center");
            image.dirty = true;
            image.setCoords();
            $("#lblimageMode").html(Math.round(state.cropWidth) + " X " + Math.round(state.cropHeight));
            finishSession(true);
            canvas.fire("object:modified", { target: image });
            return image;
        }

        return {
            start: start,
            getSelectionState: getSelectionState,
            resetSelection: setSelectionToImage,
            apply: apply,
            cancel: cancel,
            isActive: function () { return !!session; }
        };
    })();

    $(document).off("click.__cgImageCrop", "#btncropimagepopup").on("click.__cgImageCrop", "#btncropimagepopup", function (event) {
        event.preventDefault();
        window.dispatchEvent(new window.CustomEvent("cg:open-image-crop"));
    });

    /**
     * Structured reference for force fabric refresh for image.
     *
     * @param {*} imgObj Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    function forceFabricRefreshForImage(imgObj) {
        imgObj.dirty = true;
        if (typeof imgObj._setWidthHeight === "function") imgObj._setWidthHeight();
        if (typeof imgObj.setCoords === "function") imgObj.setCoords();
        if (typeof canvas.requestRenderAll === "function") canvas.requestRenderAll();
        else canvas.renderAll();
    }

    /**
     * Structured reference for replace selected image in place.
     *
     * @param {*} imgLink Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    function replaceSelectedImageInPlace(imgLink) {
        return new Promise(function (resolve) {
            var targetImgObj = getTargetImageObjectForEdit();
            if (!targetImgObj) return resolve(false);

            var id = targetImgObj.id;
            var name = targetImgObj.name;
            var clipPath = targetImgObj.clipPath;

            var oldLeft = targetImgObj.left;
            var oldTop = targetImgObj.top;
            var oldAngle = targetImgObj.angle || 0;
            var oldFlipY = targetImgObj.flipY;

            var oldScaledW = targetImgObj.getScaledWidth();
            var oldScaledH = targetImgObj.getScaledHeight();

            var left = parseInt(oldLeft, 10) < 0 ? 0 : oldLeft;
            var top = (parseInt(oldTop, 10) < 0 || parseInt(oldTop, 10) >= 443) ? 0 : oldTop;

            if (oldFlipY) { left = 0; top = 0; }

            fabric.Image.fromURL(imgLink, { crossOrigin: "anonymous" }).then(function (probeImg) {
                var ImageMode = (oldScaledW > oldScaledH) ? "L" : "P";
                var ImageModerep = (probeImg.width > probeImg.height) ? "L" : "P";

                /**
                 * Structured reference for apply after swap.
                 * @returns {*} Value and side effects preserved from the source implementation.
                 */
                function applyAfterSwap() {
                    targetImgObj.set({
                        id: id,
                        name: name,
                        left: left,
                        top: top,
                        angle: oldAngle,
                        clipPath: clipPath,
                        transparentCorners: false
                    });

                    if (Resizeoption === "2" && ImageMode === ImageModerep) {
                        targetImgObj.scaleX = oldScaledW / targetImgObj.width;
                        targetImgObj.scaleY = oldScaledH / targetImgObj.height;
                    } else {
                        var widthFactor = oldScaledW / targetImgObj.width;
                        var heightFactor = oldScaledH / targetImgObj.height;
                        var minFactor = Math.min(widthFactor, heightFactor);
                        targetImgObj.scale(minFactor);
                    }

                    forceFabricRefreshForImage(targetImgObj);

                    if (isshowarray === "1") {
                        var activeObject = canvas.getActiveObject();
                        if (activeObject) {
                            activeObject.set({ width: parseInt(activeObject.width, 10) + 1 });
                            if (typeof canvas.requestRenderAll === "function") canvas.requestRenderAll();
                            else canvas.renderAll();

                            setTimeout(function () {
                                activeObject.set({ width: parseInt(activeObject.width, 10) });
                                if (typeof canvas.requestRenderAll === "function") canvas.requestRenderAll();
                                else canvas.renderAll();
                            }, 200);
                        }
                    }

                    setTimeout(function () {
                        updateSlideThumbnail(selected_slide_id, canvas.toDataURL());
                    }, 500);

                    resolve(true);
                }

                if (typeof targetImgObj.setSrc === "function") {
                    targetImgObj.setSrc(imgLink, { crossOrigin: "anonymous" }).then(function () {
                        targetImgObj.width = targetImgObj._element
                            ? (targetImgObj._element.naturalWidth || targetImgObj._element.width)
                            : targetImgObj.width;
                        targetImgObj.height = targetImgObj._element
                            ? (targetImgObj._element.naturalHeight || targetImgObj._element.height)
                            : targetImgObj.height;

                        applyAfterSwap();
                    });
                    return;
                }

                var el = targetImgObj._element;
                if (!el) return resolve(false);

                el.onload = function () {
                    targetImgObj._element = el;
                    targetImgObj.width = el.naturalWidth || el.width;
                    targetImgObj.height = el.naturalHeight || el.height;
                    applyAfterSwap();
                };
                el.onerror = function () { resolve(false); };
                el.src = imgLink;

            }, { crossOrigin: "anonymous" });
        });
    }

