    /**
     * Structured reference for open optimize modal.
     *
     * This async function preserves the source behavior while making control flow
     * easier to trace in the structured reference copy.
     *
     * @param {*} mode Runtime parameter preserved from the source implementation.
     * @param {*} file Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    async function openOptimizeModal(mode, file) {
        _pendingMode = mode;
        _pendingImageFile = file;

        // show modal first so canvas has non-zero size
        $("#imageOptimizeModal").modal("show");

        // then build preview
        await rebuildOptimizedPreview();
    }

    /* =========================================================
       K) ADD IMAGE input
    ========================================================= */
    $("#AddImage").off("change.__addopt").on("change.__addopt", async function (e) {
        try {
            var file = e.target.files && e.target.files[0];
            if (!file) return;

            if (!file.type || file.type.indexOf("image/") !== 0) {
                alert("Please select an image file.");
                $("#AddImage").val(null);
                return;
            }

            await openOptimizeModal("add", file);
        } catch (err) {
            console.error(err);
            alert("Failed to optimize image.");
        } finally {
            $("#AddImage").val(null);
        }
    });

    /* =========================================================
       L) EDIT IMAGE input
    ========================================================= */
    $("#editimage").off("change.__editopt").on("change.__editopt", async function (e) {
        try {
            var file = e.target.files && e.target.files[0];
            if (!file) return;

            var target = getTargetImageObjectForEdit();
            if (!target) {
                alert("Select an image on canvas first.");
                $("#editimage").val(null);
                return;
            }

            if (!file.type || file.type.indexOf("image/") !== 0) {
                alert("Please select an image file.");
                $("#editimage").val(null);
                return;
            }

            await openOptimizeModal("edit", file);
        } catch (err) {
            console.error(err);
            alert("Failed to optimize image.");
        } finally {
            $("#editimage").val(null);
        }
    });

