    /* =========================================================================
       SECTION: ADD LIST (NUMBERED / BULLET / SQUARE) VIA #addnumlist
       =========================================================================
       - Reads range from #numlistrangefrom and #numlistrangeto
       - Uses:
           hdnnumbackcolor, hsnnumstrokecolor, hdnlisttextcolor
           #addgradnum checkbox for gradient fill
           #bultype:
               "0" => numbered circle
               "1" => bullet circle
               else => square bullet
           #addtextnumlist => add line text boxes
       - Adds Fabric objects:
           - fabric.Circle / fabric.Rect
           - fabric.IText (for numbers)
           - fabric.Textbox (line text)
           - fabric.Group for shape+number (or shape only)
       - Updates canvas render, thumbnails, and UI
       - Clears UI values at end
       ========================================================================= */

    /* STAMP: Compact list modal cleanup
       Keep the existing list generation flow intact while closing the modal and
       restoring the controls to their default state for the next use.
    */
    function resetNumberListModalState() {
        $("#numlistrangefrom").val("1");
        $("#numlistrangeto").val("3");
        resetNumberListColors();
        $("#addgradnum").prop("checked", false);
        $("#addtextnumlist").prop("checked", false);
        $("#bultype").val("0");
        $("#divtext").hide();
        $("#numlistsuccess").hide();

        var modalEl = document.getElementById("modalList");
        if (modalEl && typeof bootstrap !== "undefined" && bootstrap.Modal) {
            bootstrap.Modal.getOrCreateInstance(modalEl).hide();
        }
    }

    /* STAMP: Selection-aligned list markers (2026-08-17)
       When List Builder is opened for an active multi-selection, create one
       marker beside each existing object instead of generating a free-standing
       range. The original range workflow remains the fallback. */
    function addListMarkersToSelectedObjects(backColor, strokeColor, fontColor) {
        var activeSelection = canvas.getActiveObject();
        if (!activeSelection || activeSelection.type !== "activeSelection") {
            return false;
        }

        var selectedObjects = canvas.getActiveObjects().slice();
        if (!selectedObjects.length) {
            return false;
        }

        /* Fabric stores child coordinates relative to an ActiveSelection.
           Release it before measuring so every marker uses the object's true
           canvas position rather than being clamped against the left edge. */
        canvas.discardActiveObject();
        selectedObjects.forEach(function (object) {
            object.setCoords();
        });

        var targets = selectedObjects.map(function (object) {
            return {
                object: object,
                bounds: object.getBoundingRect(true, true)
            };
        }).sort(function (a, b) {
            return a.bounds.top - b.bounds.top || a.bounds.left - b.bounds.left;
        });
        var markerType = $("#bultype").val();
        var startNumber = parseInt($("#numlistrangefrom").val(), 10);
        var markerGroups = [];

        if (isNaN(startNumber)) {
            startNumber = 1;
        }

        targets.forEach(function (target, index) {
            var markerShape;
            var markerObjects = [];
            var markerRadius = markerType === "0" ? 15 : 5;
            var markerCenterX = Math.max(markerRadius + 3, target.bounds.left - markerRadius - 8);
            var markerCenterY = target.bounds.top + (target.bounds.height / 2);

            if (markerType === "2") {
                markerShape = new fabric.Rect({
                    width: 10,
                    height: 10,
                    fill: backColor,
                    stroke: strokeColor,
                    strokeWidth: 3,
                    originX: "center",
                    originY: "center"
                });
            } else {
                markerShape = new fabric.Circle({
                    radius: markerRadius,
                    fill: backColor,
                    stroke: strokeColor,
                    strokeWidth: 3,
                    originX: "center",
                    originY: "center"
                });
            }

            if (markerType === "0" && $("#addgradnum").is(":checked")) {
                markerShape.setGradient("fill", {
                    x1: markerShape.width,
                    y1: 0,
                    x2: 0,
                    y2: markerShape.height,
                    colorStops: { 0: backColor, 1: backColor }
                });
            }

            markerObjects.push(markerShape);
            if (markerType === "0") {
                markerObjects.push(new fabric.IText(String(startNumber + index), {
                    fontSize: 20,
                    originX: "center",
                    originY: "center",
                    fontFamily: "Arial",
                    fill: fontColor
                }));
            }

            var groupId = generate_id("g_");
            var markerGroup = new fabric.Group(markerObjects, {
                id: groupId,
                left: markerCenterX,
                top: markerCenterY,
                originX: "center",
                originY: "center",
                alignmentGuideRole: "list-badge"
            });

            markerGroup.set("name", "List_" + random(4));
            markerGroup.setControlsVisibility({
                mt: false, mb: false, ml: false, mr: false,
                bl: false, br: false, tl: false, tr: false, mtr: false
            });
            pushControl(groupId, "Group");
            static_groups.push(groupId);
            anyobject++;
            canvas.add(markerGroup);
            markerGroups.push(markerGroup);
        });

        canvas.setActiveObject(new fabric.ActiveSelection(selectedObjects.concat(markerGroups), { canvas: canvas }));
        canvas.requestRenderAll();
        updateCanvasState();
        setTimeout(function () {
            updateSlideThumbnail(selected_slide_id, canvas.toDataURL());
        }, 500);

        return true;
    }

    /**
     * STAMP: 2026-08-18 - Merge a text-only ActiveSelection into one editable
     * textbox, optionally prefixing each source line with a list marker.
     */
    window.combineSelectedTextObjects = function (options) {
        var activeSelection = canvas.getActiveObject();
        var selectedRoots = activeSelection && String(activeSelection.type || "").toLowerCase() === "activeselection" ? canvas.getActiveObjects().slice() : [];
        var selectedObjects = [];
        function collectTextObjects(item, parent) {
            if (!item) return;
            if (item.type === "text" || item.type === "textbox" || item.type === "i-text" || typeof item.text === "string") {
                selectedObjects.push({ object: item, parent: parent });
                return;
            }
            (item._objects || []).forEach(function (child) { collectTextObjects(child, item); });
        }
        selectedRoots.forEach(function (item) { collectTextObjects(item, null); });
        if (!selectedObjects.length) return false;

        canvas.discardActiveObject();
        var orderedItems = selectedObjects.map(function (entry) {
            var object = entry.object;
            object.setCoords();
            return { object: object, parent: entry.parent, bounds: object.getBoundingRect(true, true) };
        }).sort(function (a, b) {
            return a.bounds.top - b.bounds.top || a.bounds.left - b.bounds.left;
        });
        var firstObject = orderedItems[0].object;
        var minLeft = Math.min.apply(null, orderedItems.map(function (item) { return item.bounds.left; }));
        var minTop = Math.min.apply(null, orderedItems.map(function (item) { return item.bounds.top; }));
        var maxRight = Math.max.apply(null, orderedItems.map(function (item) { return item.bounds.left + item.bounds.width; }));
        var markerStyle = options && options.markerStyle ? options.markerStyle : "numbered";
        var markerMap = {
            round: "•", square: "▪", dash: "–", arrow: "›", check: "✓", diamond: "◆",
            "hollow-round": "○", "hollow-square": "□", triangle: "▶", chevron: "❯",
            "double-arrow": "⇒", star: "★"
        };
        var sourceLines = [];
        orderedItems.forEach(function (item) {
            String(item.object.text || "").split(/\r?\n/).forEach(function (line) {
                if (line.trim()) sourceLines.push({ object: item.object, text: line.trim() });
            });
        });
        var markerScale = Math.min(2, Math.max(0.5, Number(options && options.markerScale) || 1));
        var markerLengths = [];
        var lines = sourceLines.map(function (item, index) {
            var marker = "";
            if (options && options.asList) {
                if (markerStyle === "numbered") marker = (index + 1) + ".";
                else if (markerStyle === "alpha") marker = String.fromCharCode(65 + (index % 26)) + ".";
                else marker = markerMap[markerStyle] || "•";
            }
            markerLengths.push(marker.length);
            return (marker ? marker + " " : "") + item.text;
        });

        selectedObjects.forEach(function (entry) {
            if (entry.parent && typeof entry.parent.removeWithUpdate === "function") entry.parent.removeWithUpdate(entry.object);
            else canvas.remove(entry.object);
        });
        var removedIds = selectedObjects.map(function (entry) { return entry.object.id; });
        slide_controls = (slide_controls || []).filter(function (control) { return removedIds.indexOf(control.id) < 0; });

        var combinedId = generate_id("textbox_");
        var combinedFontSize = Math.max(8, (firstObject.fontSize || 20) * (firstObject.scaleY || 1));
        var markerStyles = {};
        if (options && options.asList && markerScale !== 1) {
            markerLengths.forEach(function (markerLength, lineIndex) {
                if (!markerLength) return;
                markerStyles[lineIndex] = {};
                for (var charIndex = 0; charIndex < markerLength; charIndex++) {
                    markerStyles[lineIndex][charIndex] = { fontSize: combinedFontSize * markerScale };
                }
            });
        }
        var combinedText = new fabric.Textbox(lines.join("\n"), {
            id: combinedId,
            left: minLeft,
            top: minTop,
            width: Math.max(120, maxRight - minLeft),
            originX: "left",
            originY: "top",
            fontFamily: firstObject.fontFamily || "Arial",
            fontSize: combinedFontSize,
            fontWeight: firstObject.fontWeight || "normal",
            fontStyle: firstObject.fontStyle || "normal",
            underline: !!firstObject.underline,
            textAlign: firstObject.textAlign || "left",
            lineHeight: firstObject.lineHeight || 1.16,
            charSpacing: firstObject.charSpacing || 0,
            fill: firstObject.fill || "#000000",
            stroke: firstObject.stroke || null,
            strokeWidth: firstObject.strokeWidth || 0,
            styles: markerStyles,
            listMarkerScale: markerScale,
            name: options && options.asList ? "Combined_List" : "Combined_Text"
        });
        pushControl(combinedId, "Textbox");
        anyobject++;
        canvas.add(combinedText);
        canvas.setActiveObject(combinedText);
        combinedText.setCoords();
        canvas.requestRenderAll();
        canvas.fire("object:modified", { target: combinedText });
        updateCanvasState();
        setTimeout(function () { updateSlideThumbnail(selected_slide_id, canvas.toDataURL()); }, 300);
        return true;
    };

