    /* STAMP 2026-08-20: grouped font select with committed changes only. */
    var fontSelect = document.getElementById("font-family");
    Object.keys(fontFamily_groups).forEach(function (groupName) {
        var optionGroup = document.createElement("optgroup");
        optionGroup.label = groupName;
        fontFamily_groups[groupName].forEach(function (font) {
            var option = document.createElement("option");
            option.value = font;
            option.textContent = font;
            option.style.fontFamily = font;
            optionGroup.appendChild(option);
        });
        fontSelect.appendChild(optionGroup);
    });

    function loadCanvasFont(font, done) {
        if (window.CGFontRuntime) {
            window.CGFontRuntime.load([font], done);
            return;
        }
        var isSystemFont = fontFamily_groups["Preferred"].indexOf(font) >= 0
            || fontFamily_groups["System & Classic"].indexOf(font) >= 0
            || font === "Segoe Print" || font === "Comic Sans MS";
        if (isSystemFont || typeof WebFont === "undefined") {
            done();
            return;
        }

        WebFont.load({
            google: { families: [font + ":400,600,700"] },
            active: done,
            inactive: done
        });
    }

    // STAMP: 2026-09-09 - Quick Action hover previews may load a web font without committing canvas history.
    window.CGLoadCanvasFont = loadCanvasFont;

    function applyFontFamily(target, font) {
        if (!target) {
            return;
        }
        if (target.type === "group" || target.type === "activeSelection") {
            (target._objects || []).forEach(function (item) {
                applyFontFamily(item, font);
            });
            return;
        }
        if (target.type !== "textbox" && target.type !== "i-text" && target.type !== "text") {
            return;
        }
        if (target.isEditing && target.selectionStart !== target.selectionEnd) {
            target.setSelectionStyles({ fontFamily: font }, target.selectionStart, target.selectionEnd);
        } else {
            target.set({ fontFamily: font });
            /* STAMP: 2026-08-25 - Rich pasted text can carry a fontFamily on
               every character. Update only that style across the full range
               so it cannot override the Properties or quick-toolbar choice. */
            if (typeof target.setSelectionStyles === "function" && typeof target.text === "string") {
                target.setSelectionStyles({ fontFamily: font }, 0, target.text.length);
            }
        }
        target.dirty = true;
        target.setCoords();
    }

    function syncFontSelection(font) {
        var selectedFont = font || "Arial";
        if (fontFamily_list.indexOf(selectedFont) < 0) {
            var existingGroup = fontSelect.querySelector('optgroup[data-cg-existing-fonts="true"]');
            if (!existingGroup) {
                existingGroup = document.createElement("optgroup");
                existingGroup.label = "Existing document fonts";
                existingGroup.setAttribute("data-cg-existing-fonts", "true");
                fontSelect.appendChild(existingGroup);
            }
            var existingOption = document.createElement("option");
            existingOption.value = selectedFont;
            existingOption.textContent = selectedFont;
            existingOption.style.fontFamily = selectedFont;
            existingGroup.appendChild(existingOption);
            fontFamily_list.push(selectedFont);
        }
        $("#font-family").val(selectedFont).css("font-family", selectedFont);
        $("#selectedfont").text(selectedFont).css("font-family", selectedFont);
    }

    syncFontSelection("Arial");
    window.CGApplyTextFontFamily = function (target, selectedFont, done) {
        loadCanvasFont(selectedFont, function () {
            applyFontFamily(target, selectedFont);
            syncFontSelection(selectedFont);
            canvas.requestRenderAll();
            updateCanvasState();
            if (typeof done === "function") done();
        });
    };
    $("#font-family").on("change", function () {
        var selectedFont = this.value;
        var activeObject = getActivePropertyObject();
        window.CGApplyTextFontFamily(activeObject, selectedFont);
    });

    /**
     * STAMP: 2026-09-11 - Normalize legacy normal/bold values and numeric CSS
     * weights into the supported Fabric authoring scale.
     *
     * @param {string|number} value Stored Fabric fontWeight value.
     * @returns {number} A weight from 100 through 900.
     */
    function normalizeTextFontWeight(value) {
        var normalized = String(value || "").toLowerCase();
        if (normalized === "bold") return 700;
        if (normalized === "normal") return 400;
        var numericWeight = Number(value);
        if (!Number.isFinite(numericWeight)) return 400;
        return Math.max(100, Math.min(900, Math.round(numericWeight / 100) * 100));
    }

    /** Apply a font weight without bypassing character selection or group rules. */
    function applyTextFontWeight(target, requestedWeight) {
        if (!target) return;
        var weight = String(normalizeTextFontWeight(requestedWeight));
        var targetType = String(target.type || "").toLowerCase();
        if (targetType === "group" || targetType === "activeselection") {
            (target._objects || []).forEach(function (item) {
                applyTextFontWeight(item, weight);
            });
            return;
        }
        if (targetType !== "textbox" && targetType !== "i-text" && targetType !== "text") return;

        if (target.isEditing && target.selectionStart !== target.selectionEnd
            && typeof target.setSelectionStyles === "function") {
            target.setSelectionStyles({ fontWeight: weight }, target.selectionStart, target.selectionEnd);
        } else {
            target.set({ fontWeight: weight });
            if (typeof target.setSelectionStyles === "function" && typeof target.text === "string") {
                target.setSelectionStyles({ fontWeight: weight }, 0, target.text.length);
            }
        }
        target.dirty = true;
        target.setCoords();
    }

    window.CGNormalizeTextFontWeight = normalizeTextFontWeight;
    window.CGApplyTextFontWeight = function (target, requestedWeight) {
        applyTextFontWeight(target, requestedWeight);
        $("#fontweight").val(String(normalizeTextFontWeight(requestedWeight)));
        canvas.requestRenderAll();
        updateCanvasState();
    };

    $("#fontweight").on("change", function () {
        window.CGApplyTextFontWeight(getActivePropertyObject(), this.value);
    });

    /* STAMP 2026-08-20: shared in-place reset for every object property bar. */
    var propertyResetSnapshot = null;
    var resettablePropertyNames = [
        "name", "text", "styles", "fontFamily", "fontSize", "fontWeight", "fontStyle", "underline",
        "textAlign", "lineHeight", "charSpacing", "fill", "stroke", "strokeWidth", "backgroundColor",
        "textBackgroundColor", "opacity", "shadow", "rx", "ry", "radius", "scaleX", "scaleY",
        "skewX", "skewY", "flipX", "flipY", "cropX", "cropY", "typingEffect", "typingSpeed"
    ];

    function collectResetEntries(target, entries) {
        if (!target) {
            return;
        }
        entries.push({ target: target, original: target.clone() });
        (target._objects || []).forEach(function (child) {
            collectResetEntries(child, entries);
        });
    }

    function capturePropertyResetSnapshot(target, force) {
        if (!force && propertyResetSnapshot && propertyResetSnapshot.target === target) {
            return;
        }
        var entries = [];
        collectResetEntries(target, entries);
        propertyResetSnapshot = { target: target, entries: entries };
    }

    window.CGPropertyReset = {
        capture: function (target) {
            capturePropertyResetSnapshot(target, true);
        },
        reset: resetActiveObjectProperties
    };

    function copyResettableProperties(target, original) {
        resettablePropertyNames.forEach(function (propertyName) {
            if (propertyName in original) {
                target.set(propertyName, original[propertyName]);
            }
        });
        target.dirty = true;
        target.setCoords();
    }

    function clearTextHighlightStyles(target) {
        if (!target) {
            return;
        }
        (target._objects || []).forEach(clearTextHighlightStyles);
        if (target.type !== "textbox" && target.type !== "i-text" && target.type !== "text") {
            return;
        }

        Object.keys(target.styles || {}).forEach(function (lineIndex) {
            Object.keys(target.styles[lineIndex] || {}).forEach(function (characterIndex) {
                var characterStyle = target.styles[lineIndex][characterIndex];
                if (!characterStyle) {
                    return;
                }
                delete characterStyle.textBackgroundColor;
                delete characterStyle.deltaY;
                if (!Object.keys(characterStyle).length) {
                    delete target.styles[lineIndex][characterIndex];
                }
            });
            if (!Object.keys(target.styles[lineIndex] || {}).length) {
                delete target.styles[lineIndex];
            }
        });
        target.set({ textBackgroundColor: "" });
        target.dirty = true;
        target.setCoords();
    }

    async function resetActiveObjectProperties() {
        var activeObject = getActivePropertyObject();
        if (!activeObject) {
            return;
        }
        if (!propertyResetSnapshot || propertyResetSnapshot.target !== activeObject) {
            capturePropertyResetSnapshot(activeObject);
            clearTextHighlightStyles(activeObject);
            removePreset3dDepth(activeObject);
            toggleHandwrittenStyle(activeObject, true);
            setTypingEffect(activeObject, false);
            $("#HandwrittenTextEffect, #Text3DEffect, #Shape3DEffect, #TypingTextEffect, #TextHighlightEffect").removeClass("is-active");
            refreshAppliedTextEffects(activeObject);
            canvas.requestRenderAll();
            updateCanvasState();
            return;
        }

        var originals = await Promise.all(propertyResetSnapshot.entries.map(function (entry) {
            return entry.original;
        }));
        propertyResetSnapshot.entries.forEach(function (entry, index) {
            copyResettableProperties(entry.target, originals[index]);
        });
        clearTextHighlightStyles(activeObject);
        $("#HandwrittenTextEffect, #Text3DEffect, #Shape3DEffect, #TypingTextEffect, #TextHighlightEffect").removeClass("is-active");
        refreshAppliedTextEffects(activeObject);

        canvas.setActiveObject(activeObject);
        canvas.requestRenderAll();
        getselobjprop();
        updateCanvasState();
    }

    /* STAMP: 2026-08-21 - Interactions share the selected object's property reset. */
    $(".objproperties").not("#ObjectAutomationSettings").each(function () {
        if ($(this).children(".cg-property-reset").length) {
            return;
        }
        $(this).prepend(
            '<div class="cg-property-reset">' +
            '<span>Properties</span>' +
            '<button type="button" class="btn btn-light btn-sm cg-reset-properties" title="Restore original properties" aria-label="Restore original properties">' +
            '<i class="fa fa-undo" aria-hidden="true"></i><span>Reset</span>' +
            '</button></div>'
        );
    });

    $(document).on("click", ".cg-reset-properties", function (event) {
        event.preventDefault();
        event.stopPropagation();
        resetActiveObjectProperties();
    });

    canvas.on("selection:created", function () {
        capturePropertyResetSnapshot(canvas.getActiveObject(), true);
        refreshAppliedTextEffects(canvas.getActiveObject());
    });
    canvas.on("selection:updated", function () {
        capturePropertyResetSnapshot(canvas.getActiveObject(), false);
        refreshAppliedTextEffects(canvas.getActiveObject());
    });
    canvas.on("selection:cleared", function () {
        propertyResetSnapshot = null;
        refreshAppliedTextEffects(null);
    });


    /* =========================================================================
       SECTION: FONT SIZE SLIDER + INPUT
       ========================================================================= */

    var slidertitleop = document.getElementById("fontsize");
    var outputtitleop = document.getElementById("fontsizelabel");
    var fontSizeCommitTimer = null;

    /* STAMP: 2026-09-12 - Apply font size from the compact popover directly to
       the live Fabric text target. This supports selected characters, grouped
       text and ActiveSelection while debouncing expensive slide persistence. */
    function clampCanvasFontSize(value) {
        var numericValue = parseFloat(value);
        return Number.isFinite(numericValue) ? Math.min(200, Math.max(1, numericValue)) : null;
    }

    function resolveCanvasFontSizeTarget() {
        var activeObject = canvas.getActiveObject();
        if (!activeObject) return null;
        if (parseInt(grpfont, 10) >= 0 && activeObject._objects) {
            return activeObject._objects[parseInt(grpfont, 10)] || activeObject;
        }
        if (isshowarray == "1" && activeObject._objects) {
            return activeObject._objects[selectedarray] || activeObject;
        }
        return activeObject;
    }

    /* STAMP: 2026-09-14 - Preserve an authored multiline Textbox width and its
       top-left canvas anchor when font metrics change. A visually single-line
       Textbox still grows horizontally so headings and labels do not wrap. */
    function getTextboxLayout(object) {
        if (!object || String(object.type || "").toLowerCase() !== "textbox") return null;
        var renderedLines = Array.isArray(object._textLines) ? object._textLines : [];
        return {
            anchor: typeof object.getPointByOrigin === "function"
                ? object.getPointByOrigin("left", "top")
                : null,
            width: Number(object.width) || 2,
            isMultiline: renderedLines.length > 1 || /[\r\n]/.test(String(object.text || ""))
        };
    }

    function fitTextboxToContentWidth(object, preservedLayout) {
        if (!object || String(object.type || "").toLowerCase() !== "textbox") return;
        var layout = preservedLayout || getTextboxLayout(object);
        var anchor = layout && layout.anchor;
        if (layout && layout.isMultiline) {
            object.set("width", layout.width);
            if (typeof object.initDimensions === "function") object.initDimensions();
            if (anchor && typeof object.setPositionByOrigin === "function") {
                object.setPositionByOrigin(anchor, "left", "top");
            }
            return;
        }
        /* Measure against a temporary unconstrained width so ordinary spaces
           remain on one line; explicit newline characters are still honoured. */
        object.set("width", 100000);
        if (typeof object.initDimensions === "function") object.initDimensions();
        var measuredWidth = typeof object.calcTextWidth === "function" ? object.calcTextWidth() : object.width;
        var contentWidth = Math.max(2, Number(object.dynamicMinWidth) || 0, Number(measuredWidth) || 0);
        object.set("width", Math.ceil(contentWidth * 100) / 100 + 1);
        if (typeof object.initDimensions === "function") object.initDimensions();
        if (anchor && typeof object.setPositionByOrigin === "function") {
            object.setPositionByOrigin(anchor, "left", "top");
        }
    }

    window.CGFitTextboxToContentWidth = fitTextboxToContentWidth;

    /* STAMP: 2026-09-13 - A saved Fabric text object can contain character-level
       fontSize values which override its base fontSize (headings and imported
       rich text commonly do this). When sizing the whole object, remove only
       those stale size overrides so every character inherits the requested
       value while all other authored character styling remains intact. */
    function clearCanvasCharacterFontSizes(object) {
        if (!object || !object.styles || typeof object.styles !== "object") return;
        Object.keys(object.styles).forEach(function (lineIndex) {
            var lineStyles = object.styles[lineIndex];
            if (!lineStyles || typeof lineStyles !== "object") return;
            Object.keys(lineStyles).forEach(function (characterIndex) {
                var characterStyle = lineStyles[characterIndex];
                if (!characterStyle || typeof characterStyle !== "object") return;
                delete characterStyle.fontSize;
                if (!Object.keys(characterStyle).length) delete lineStyles[characterIndex];
            });
            if (!Object.keys(lineStyles).length) delete object.styles[lineIndex];
        });
    }

    function setCanvasObjectFontSize(object, size) {
        if (!object) return false;
        var objectType = String(object.type || "").toLowerCase();
        if ((objectType === "group" || objectType === "activeselection") && object._objects) {
            return object._objects.reduce(function (changed, child) {
                return setCanvasObjectFontSize(child, size) || changed;
            }, false);
        }
        if (objectType !== "i-text" && objectType !== "textbox" && objectType !== "text") return false;
        var textboxLayout = getTextboxLayout(object);
        if (object.isEditing && object.selectionStart !== object.selectionEnd && typeof object.setSelectionStyles === "function") {
            object.setSelectionStyles({ fontSize: size }, object.selectionStart, object.selectionEnd);
        } else {
            clearCanvasCharacterFontSizes(object);
            object.set("fontSize", size);
        }
        fitTextboxToContentWidth(object, textboxLayout);
        object.dirty = true;
        object.setCoords();
        return true;
    }

    function commitCanvasFontSize() {
        window.clearTimeout(fontSizeCommitTimer);
        fontSizeCommitTimer = null;
        updateCanvasState();
    }

    function applyCanvasFontSize(value, commitImmediately) {
        var size = clampCanvasFontSize(value);
        if (size === null) return false;
        var target = resolveCanvasFontSizeTarget();
        if (containsLockedCanvasObject(canvas.getActiveObject()) || containsLockedCanvasObject(target)) return false;
        $("#fontsize").val(size);
        $("#fontsizelabel").val(size);
        if (!setCanvasObjectFontSize(target, size)) return false;
        canvas.requestRenderAll();
        window.clearTimeout(fontSizeCommitTimer);
        if (commitImmediately) commitCanvasFontSize();
        else fontSizeCommitTimer = window.setTimeout(commitCanvasFontSize, 140);
        return true;
    }

    window.CGApplyCanvasFontSize = applyCanvasFontSize;

    slidertitleop.oninput = function () {
        applyCanvasFontSize(this.value, false);
    };

    $(outputtitleop).off("input.cgFontSize change.cgFontSize")
        .on("input.cgFontSize", function () {
            applyCanvasFontSize(this.value, false);
        })
        .on("change.cgFontSize", function () {
            var fallbackSize = resolveCanvasFontSizeTarget();
            var size = clampCanvasFontSize(this.value)
                || clampCanvasFontSize(fallbackSize && fallbackSize.fontSize)
                || 30;
            applyCanvasFontSize(size, true);
        });


