    /* =========================================================================
       UPDATE TEXT ICON (Selection Highlighting for Text Actions)
       -------------------------------------------------------------------------
       PURPOSE
       - Controls the UI highlighting of text action icons/buttons.
       - Example use-case:
           update_text_icon(activeObject, 'textAlign', 'left', 'div_textAlignment_left')
         will add "div-font-style-selected" to #div_textAlignment_left if
         activeObject.textAlign == 'left'
       - IMPORTANT:
         - Your function is kept EXACTLY as you provided (same name, same logic).
       ========================================================================= */
    /**
     * Refresh text-style control visuals for a specific active text property.
     *
     * @param {*} activeObject Runtime parameter preserved from the source implementation.
     * @param {*} propertyName Runtime parameter preserved from the source implementation.
     * @param {*} propertyValue Runtime parameter preserved from the source implementation.
     * @param {*} id Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    update_text_icon = function (activeObject, propertyName, propertyValue, id) {

        //////console.log(activeObject + '-' + propertyName + '-' + propertyValue + '-' + id);

        // Special handling:
        // If we are updating alignment, first clear selection from all alignment buttons
        if (propertyName == 'textAlign') {
            $('.textAlignment').removeClass("div-font-style-selected");
        }

        // If activeObject currently has the given property value,
        // mark the UI element as selected; otherwise remove selected class.
        if (activeObject.get(propertyName) == propertyValue) {
            $('#' + id).addClass("div-font-style-selected");
        } else {
            $('#' + id).removeClass("div-font-style-selected");
        }

    };
    //Text Area Ends ======================================================================================================================================================================


