    /** STAMP: 2026-08-18 - Add editable native Fabric Polygon shapes. */
    function createRegularPolygonPoints(sides, outerRadius, innerRadius) {
        var points = [];
        var pointCount = innerRadius ? sides * 2 : sides;
        for (var pointIndex = 0; pointIndex < pointCount; pointIndex++) {
            var radius = innerRadius && pointIndex % 2 ? innerRadius : outerRadius;
            var angle = (-Math.PI / 2) + ((Math.PI * 2 * pointIndex) / pointCount);
            points.push({ x: Math.cos(angle) * radius, y: Math.sin(angle) * radius });
        }
        return points;
    }

    function addNativePolygon(sides, shapeName, innerRadius) {
        var safeSides = Math.max(3, Math.min(12, parseInt(sides, 10) || 5));
        var id = generate_id('p_');
        var shape = new fabric.Polygon(createRegularPolygonPoints(safeSides, 72, innerRadius), {
            id: id,
            left: Math.max(20, (canvas.getWidth() - 144) / 2),
            top: Math.max(20, (canvas.getHeight() - 144) / 2),
            fill: '#000',
            stroke: '#000',
            strokeWidth: 1,
            strokeUniform: true,
            transparentCorners: false,
            selectable: true,
            evented: true,
            polygonSides: safeSides
        });
        shape.set("name", shapeName + "_" + random(4));
        anyobject++;
        canvas.add(shape);
        shape.setCoords();
        canvas.setActiveObject(shape);
        getselobjprop();
        canvas.requestRenderAll();
        updateCanvasState();
        updateSlideThumbnail(selected_slide_id, canvas.toDataURL());
        pushControl(id, shapeName);
    }

    $('#pentagon').on('click', function () { addNativePolygon(5, 'Pentagon'); });
