    /* =========================================================================
       11) BORDER RADIUS (Rect corner rounding: rx / ry)
       -------------------------------------------------------------------------
       Elements:
       - slider: #objbrx
       - textbox: #objbrxdiv
       Logic:
       - On slider input:
           - sync textbox
           - apply rx/ry to:
               a) selectedarray rect(s) if isshowarray == "1"
                  (loops through all items and applies only to rect types)
               b) all objects in active selection group if objtp == "objsel"
               c) active object
       Notes:
       - rx/ry are divided by scaleX/scaleY to keep consistent corner radius
         even if object is scaled.
       ========================================================================= */
    var slidertitleop = document.getElementById("objbrx");
    var outputtitleop = document.getElementById("objbrxdiv");

    outputtitleop.innerHTML = slidertitleop.value;

    slidertitleop.oninput = function () {

        var stroke = this.value;
        $("#objbrxdiv").val(this.value);

        if (isshowarray == "1") {

            var activeObject = canvas.getActiveObject();
            var items = activeObject._objects;

            for (var i = 0; i < items.length; i++) {
                if (items[i].type == "rect") {
                    items[i].set('rx', parseInt(stroke) / items[i].scaleX);
                    items[i].set('ry', parseInt(stroke) / items[i].scaleY);
                }
            }

            canvas.renderAll();

        } else {

            if (objtp == "objsel") {

                var items = canvas.getActiveObject()._objects;

                for (var i = 0; i < items.length; i++) {
                    items[i].set('rx', parseInt(stroke) / items[i].scaleX);
                    items[i].set('ry', parseInt(stroke) / items[i].scaleY);
                }

            } else {

                var activeObject = canvas.getActiveObject();
                activeObject.set('rx', parseInt(stroke) / activeObject.scaleX);
                activeObject.set('ry', parseInt(stroke) / activeObject.scaleY);

            }

        }

        canvas.renderAll();
    };


