    /* =========================================================================
       1) ADD GRADIENT (UI + initialize gradient editor)
       -------------------------------------------------------------------------
       #addgrad click:
       - Switch UI from "Add Gradient" to "Remove Gradient"
       - Show gradient options row and expand the options panel
       - If selected object(s) don't already have a gradient fill, initialize
         the gradient color picker UI (via updateObjectGradientColorPicker)
       - When gradient is enabled:
           - #fn_add_gradient is hidden
           - #fn_remove_gradient is shown
       Notes:
       - Supports two modes:
           a) isshowarray == "1": editing an object inside a group (_objects)
           b) else: editing the active object directly
       ========================================================================= */
    $('#addgrad').on('click', function () {

        // UI: toggle buttons and show options
        $(this).hide();
        $('#removegrad').show();
        $("#trgradient_options").show();
        $("#gradient_options").collapse("show");

        // Add Gradient
        if (isshowarray == "1") {

            var activeObject = canvas.getActiveObject();
            var items = activeObject._objects;

            for (var i = 0; i < items.length; i++) {

                // Only apply gradient if fill is not already a gradient object
                if (items[i].fill.type == undefined) {

                    // Apply only on supported shape types
                    if (items[i].type == "rect" || items[i].type == "circle" || items[i].type == "triangle" || items[i].type == "line") {

                        var fillColor = activeObject.fill;

                        // gp.addHandler(1, fillColor, 0);
                        // gp.addHandler(99, fillColor, 0);

                        updateObjectGradientColorPicker();

                        $("#fn_add_gradient").hide();
                        $("#fn_remove_gradient").show();
                    }
                }
            }

        }
        else {

            var activeObject = canvas.getActiveObject();

            // Only apply gradient if fill is not already a gradient object
            if (activeObject.fill.type == undefined) {

                var fillColor = activeObject.fill;

                // gp.addHandler(1, fillColor, 0);
                // gp.addHandler(99, fillColor, 0);

                updateObjectGradientColorPicker();

                $("#fn_add_gradient").hide();
                $("#fn_remove_gradient").show();
            }
        }

    });


    /* =========================================================================
       2) REMOVE GRADIENT (UI + remove all gradient points + reset fill)
       -------------------------------------------------------------------------
       #removegrad click:
       - Switch UI back to "Add Gradient"
       - Hide gradient options row
       - Reset hex input to #000 and reset background UI for objbackcolor
       - removeAllGradiantPoints(): triggers click on all handler close buttons
       - Sets active object's fill to hexColorInput (#000)
       - Re-renders + collapses options
       ========================================================================= */
    $('#removegrad').on('click', function () {

        // UI: toggle buttons and hide options
        $(this).hide();
        $('#addgrad').show();
        $("#trgradient_options").hide();

        // Reset UI values for object backcolor
        $("#hexColorInput").val("#000");
        $("#objbackcolor").css("background", "#2c2b2b");

        // Remove Gradient
        removeAllGradiantPoints();

        var activeObject = canvas.getActiveObject();
        activeObject.set({
            fill: $("#hexColorInput").val()
        });

        canvas.renderAll();

        // UI: show add, hide remove, collapse the gradient options panel
        $("#fn_add_gradient").show();
        $("#fn_remove_gradient").hide();
        $("#gradient_options").collapse("hide");

    });


