    /* =========================================================================
       8) COLOR PICKER APPLY (Fill/Stroke + Hover UI updates)
       -------------------------------------------------------------------------
       #colorPickerPopup span click:
       - Sets #hexColorInput = clicked color (this.title)
       - If hover flag == 1:
           - Updates hover preview blocks:
               #divobkbackcolorhover / #divobkstrokecolorhover
             (Does NOT apply to Fabric objects in this branch)
       - Else (normal):
           - If background selected:
               apply fill to:
                 a) selectedarray item
                 b) all items in group selection (including nested group shapes)
                 c) active object
               update #objbackcolor background UI preview
           - If stroke selected:
               apply stroke similarly
               update #objstrokecolor preview
               enable/disable #objstrokewidth when stroke is empty
       - Ends with canvas.renderAll()
       ========================================================================= */
    $("#colorPickerPopup").on('click', '.fr-select-color', function () {

        // Store selected color into hex input
        $("#hexColorInput").val(this.title);

        /* ==========================
           HOVER PREVIEW MODE (UI ONLY)
           ========================== */
        if ($("#hdnobjbackstrokehover").val() == "1") {

            // Hover background preview
            if ($('#rdbobjbck').prop('checked') || colorMode == "objback") {
                if (this.title == null || this.title == "") {
                    $("#divobkbackcolorhover").css("background", "url(images/Transparent.png)");
                    $("#divobkbackcolorhover").css("background-size", "100px 100px");
                }
                else {
                    $("#divobkbackcolorhover").removeAttr("style");
                    $("#divobkbackcolorhover").css("background-color", this.title);
                }
            }

            // Hover stroke preview
            if ($('#rdbobjstroke').prop('checked') || colorMode == "objstroke") {
                if (this.title == null || this.title == "") {
                    $("#divobkstrokecolorhover").css("background", "url(images/Transparent.png)");
                    $("#divobkstrokecolorhover").css("background-size", "100px 100px");
                }
                else {
                    $("#divobkstrokecolorhover").removeAttr("style");
                    $("#divobkstrokecolorhover").css("background-color", this.title);
                }
            }

        }
        else {

            /* ==========================
               NORMAL APPLY MODE (CANVAS APPLY)
               ========================== */

            /* --------------------------
               APPLY BACKGROUND (fill)
               -------------------------- */
            if ($('#rdbobjbck').prop('checked') || colorMode == "objback") {

                if (isshowarray == "1") {

                    var activeObject = canvas.getActiveObject();
                    var items = activeObject._objects;
                    items[selectedarray].set({ fill: this.title });
                    canvas.renderAll();

                } else {

                    if (objtp == "objsel") {

                        var items = canvas.getActiveObject()._objects;

                        for (var i = 0; i < items.length; i++) {

                            // If the selected item is itself a group, apply to inner shapes
                            if (items[i].type == "group") {
                                var grpitems = items[i]._objects;

                                for (var j = 0; j < grpitems.length; j++) {
                                    if (grpitems[j].type == "rect" || grpitems[j].type == "circle" || grpitems[j].type == "triangle" || grpitems[j].type == "line") {
                                        grpitems[j].set({ fill: this.title });
                                    }
                                }

                            } else {
                                // Direct apply
                                items[i].set({ fill: this.title });
                            }
                        }

                    } else {

                        var activeObject = canvas.getActiveObject();
                        activeObject.set({ fill: this.title });

                    }
                }

                // Update UI preview for background color
                if (this.title == null || this.title == "") {
                    $("#objbackcolor").css("background", "url(images/Transparent.png)");
                    $("#objbackcolor").css("background-size", "100px 100px");
                }
                else {
                    $("#objbackcolor").css("background", this.title);
                }
            }


            /* --------------------------
               APPLY STROKE (stroke)
               -------------------------- */
            if ($('#rdbobjstroke').prop('checked') || colorMode == "objstroke") {

                if (isshowarray == "1") {

                    var activeObject = canvas.getActiveObject();
                    var items = activeObject._objects;
                    items[selectedarray].set({ stroke: this.title });
                    canvas.renderAll();

                } else {

                    if (objtp == "objsel") {

                        var items = canvas.getActiveObject()._objects;

                        for (var i = 0; i < items.length; i++) {

                            if (items[i].type == "group") {
                                var grpitems = items[i]._objects;

                                for (var j = 0; j < grpitems.length; j++) {
                                    if (grpitems[j].type == "rect" || grpitems[j].type == "circle" || grpitems[j].type == "triangle" || grpitems[j].type == "line") {
                                        grpitems[j].set({ stroke: this.title });
                                    }
                                }

                            } else {
                                items[i].set({ stroke: this.title });
                            }
                        }

                    } else {

                        var activeObject = canvas.getActiveObject();
                        activeObject.set({ stroke: this.title });

                    }
                }

                // Update UI preview for stroke color + enable/disable stroke width
                if (this.title == null || this.title == "") {
                    $("#objstrokecolor").css("background", "url(images/Transparent.png)");
                    $("#objstrokecolor").css("background-size", "100px 100px");
                    $("#objstrokewidth").attr('disabled', 'disabled');
                }
                else {
                    $("#objstrokecolor").css("background", this.title);
                    $("#objstrokewidth").removeAttr('disabled');
                }
            }

            syncNativeShapeColorInputs(getActivePropertyObject());
            canvas.renderAll();
        }

    });

    /* =========================================================================
   SHADOW COLOR APPLY + HEX INPUT APPLY + UI TOGGLES (Gradient/Stroke/Borders)
   -------------------------------------------------------------------------
   IMPORTANT (as you requested)
   - I did NOT remove any actions/events/functions.
   - Same selectors, same event types, same logic paths.
   - Only structured + fully explained with clear headers and comments.
   ========================================================================= */


    /* =========================================================================
       1) FILL OBJECT SHADOW (Color Picker -> span click)
       -------------------------------------------------------------------------
       #colorPickerPopup span click:
       - This handler is specifically for shadow when colorMode == "objshadow"
       - Gets correct active object:
           - If grpshp >= 0 => we are editing a shape inside a group, so pick
             canvas.getActiveObject()._objects[grpshp]
           - Else => canvas.getActiveObject()
       - Builds shadow string from UI sliders:
           - #shdhrangedemo (horizontal offset)
           - #shdvrangedemo (vertical offset)
           - #shdrrangedemo (blur radius)
           - + selected color this.title
       - Applies shadow:
           activeObject.setShadow("Hpx Vpx Rpx COLOR")
       - Updates UI preview blocks and inputs:
           - #divobkshadowcolor
           - #clsp1 / #clsp6
       - Re-sets active object and refreshes selected-object properties:
           canvas.setActiveObject(activeObject)
           getselobjprop()
       ========================================================================= */
    $("#colorPickerPopup").on('click', '.fr-select-color', function () {

        // Shadow mode only
        if (colorMode == "objshadow") {

            // Update hex input box with picked color
            $("#hexColorInput").val(this.title);

            // Resolve which object to apply the shadow to
            var activeObject;
            if (parseInt(grpshp) >= 0) {
                activeObject = canvas.getActiveObject();
                var items = activeObject._objects;
                activeObject = items[grpshp];
            } else {
                activeObject = canvas.getActiveObject();
            }

            // $("#addshadow").show();
            //IsShadow

            // Read current shadow UI values
            var shadowcolor = $("#divobkshadowcolor").css("background-color"); // (not used later, kept as-is)
            var HLenght = $("#shdhrangedemo").val();
            var VLenght = $("#shdvrangedemo").val();
            var RLenght = $("#shdrrangedemo").val();

            // Apply shadow in Fabric.js
            activeObject.setShadow("" + HLenght + "px " + VLenght + "px " + RLenght + "px " + this.title + "");

            // Update UI preview for shadow color block
            if (this.title == null || this.title == "") {
                $("#divobkshadowcolor").css("background", "background: rgb(0, 0, 0)");
            }
            else {
                $("#divobkshadowcolor").css("background", this.title);
            }

            // Update color swatch inputs (your existing behavior)
            $("#clsp1").val(this.title);
            $("#clsp1").css("background", this.title);
            $("#clsp1").css("color", this.title);

            $("#clsp6").val("#000");
            $("#clsp6").css("background", "#2c2b2b");
            $("#clsp6").css("color", "#000");

            // Re-activate object (so selection UI stays consistent)
            canvas.setActiveObject(activeObject);

            // Refresh your property panel / selected object props
            getselobjprop();
        }
    });


    /* =========================================================================
       2) HEX COLOR INPUT (Manual typing) -> change
       -------------------------------------------------------------------------
       #hexColorInput change:
       - Reads typed hex color (or empty string)
       - Uses switch(colorMode) to decide what to update
       - Updates both:
           - UI preview blocks
           - Fabric canvas object properties
       - Calls canvas.renderAll() / updateCanvasState() where relevant
       NOTES:
       - This is your "typed color" equivalent of clicking a palette square
       ========================================================================= */
    $("#hexColorInput").on('change', function (e) {

        const color = $(this).val().trim();
        if (!color && color !== "") return;

        if (color && !isValidHexColor(color)) {
            $(this).addClass("is-invalid");
            return;
        }

        $(this).removeClass("is-invalid");

        // normalize the value input
        $("#hexColorInput").val(color);

        // current active object (may be null if nothing is selected)
        const activeObject = getActivePropertyObject();

        // helper: update background or transparent pattern for a selector
        const updateBackground = (selector) => {
            if (!color) {
                $(selector).css({
                    "background": "url(images/Transparent.png)",
                    "background-size": "100px 100px"
                });
            } else {
                $(selector).removeAttr("style").css("background-color", color);
            }
        };

        switch (colorMode) {

            /* ==========================
               CANVAS BACKGROUND COLOR
               ========================== */
            case "CanvasBack":
                $("#canvasbackdiv").css("background", color || "#fff");
                setCanvasBackgroundColor(canvas, color || "#fff");
                canvas.renderAll();
                updateCanvasState();
                break;

            /* ==========================
               BULLET LIST COLOR
               ========================== */
            case "bulletcolor":
                $("#bulcolor").css({ background: color, color: color });
                $("#hdnbulbackcolor").val(color);
                break;

            /* ==========================
               NUMBER LIST COLORS
               ========================== */
            case "numback":
                setNumberListColorPreview("numback", color);
                hdnnumbackcolor = color;
                break;

            case "numstroke":
                setNumberListColorPreview("numstroke", color);
                hsnnumstrokecolor = color;
                break;

            case "numlistcolor":
                setNumberListColorPreview("numlistcolor", color);
                hdnlisttextcolor = color;
                break;

            /* ==========================
               TEXT COLOR / TEXT STROKE (Font)
               ========================== */
            case "objtextback":
            case "objtextstroke": {

                const isStroke = colorMode === "objtextstroke";
                const bgSelector = isStroke ? "#divFontStroke" : "#divFontColor";
                const hoverSelector = "#divFontColorhover";

                // Hover preview mode: update only hover swatch
                if (hdntextbackstrokehover == "1") {
                    updateBackground(hoverSelector);
                }
                else if (activeObject) {

                    // Your existing group font logic (kept)
                    const items = (parseInt(grpfont) >= 0 ? canvas.getActiveObject()._objects[grpfont] : activeObject);

                    // helper to apply style to array or single item (kept)
                    const applyStyle = (target, style) => {
                        if (Array.isArray(target)) {
                            target.forEach(item => item.set(style));
                        } else {
                            target.set(style);
                        }
                    };

                    // NOT editing text: apply fill/stroke to object(s)
                    if (!activeObject.isEditing) {

                        if (isshowarray == "1") {
                            canvas.getActiveObject()._objects[selectedarray].set(isStroke ? { stroke: color } : { fill: color });
                        } else {
                            if (objtp == "objsel") {
                                applyStyle(canvas.getActiveObject()._objects, isStroke ? { stroke: color } : { fill: color });
                            } else {
                                activeObject.set(isStroke ? { stroke: color } : { fill: color });
                            }
                        }

                    }
                    // Editing text: apply selection styles
                    else {

                        if (isshowarray == "1") {
                            canvas.getActiveObject()._objects[selectedarray].set(isStroke ? { stroke: color } : { fill: color });
                        } else {
                            if (objtp == "objsel") {
                                canvas.getActiveObject()._objects.forEach(item => {
                                    item.setSelectionStyles(isStroke ? { stroke: color } : { fill: color });
                                });
                            } else {
                                activeObject.setSelectionStyles(isStroke ? { stroke: color } : { fill: color });
                            }
                        }

                    }

                    // update UI swatch block + redraw
                    updateBackground(bgSelector);
                    canvas.renderAll();
                    updateCanvasState();
                }

                break;
            }

            case "objtexthighlight": {
                if (activeObject) {
                    var isCharacterHighlight = hasEditingTextRange(activeObject);
                    applyTextHighlightToTarget(activeObject, color);
                    if (isCharacterHighlight) {
                        removePreset3dDepth(activeObject);
                    }
                    updateBackground("#divTextHighlight");
                    canvas.renderAll();
                    updateCanvasState();
                }
                break;
            }

            /* ==========================
               OBJECT FILL / OBJECT STROKE (Shapes)
               ========================== */
            case "objback":
            case "objstroke": {

                const isStroke = colorMode === "objstroke";
                const hover = $("#hdnobjbackstrokehover").val() === "1";

                // In hover mode, you only update UI swatches
                const rdbChecked = isStroke ? $('#rdbobjstroke').prop('checked') : $('#rdbobjbck').prop('checked');

                const updateSelector = isStroke ? "#divobkstrokecolorhover" : "#divobkbackcolorhover";
                const objSelector = isStroke ? "#objstrokecolor" : "#objbackcolor";

                if (hover) {

                    if (rdbChecked || colorMode === "objback" || colorMode === "objstroke") {
                        updateBackground(updateSelector);
                    }

                } else if (activeObject) {

                    const style = isStroke ? { stroke: color } : { fill: color };

                    if (isshowarray == "1") {
                        canvas.getActiveObject()._objects[selectedarray].set(style);
                    } else {
                        if (objtp == "objsel") {
                            canvas.getActiveObject()._objects.forEach(item => item.set(style));
                        } else {
                            activeObject.set(style);
                        }
                    }

                    // Update UI swatch block
                    updateBackground(objSelector);

                    // Enable/disable stroke width slider if stroke is empty
                    if (isStroke) {
                        if (!color) {
                            $("#objstrokewidth").attr("disabled", true);
                        } else {
                            $("#objstrokewidth").removeAttr("disabled");
                        }
                    }

                    canvas.renderAll();
                }

                break;
            }

            /* ==========================
               OBJECT SHADOW (typed color)
               ========================== */
            case "objshadow":

                if (activeObject) {

                    const shadowString = `${$("#shdhrangedemo").val()}px ${$("#shdvrangedemo").val()}px ${$("#shdrrangedemo").val()}px ${color}`;
                    activeObject.setShadow(shadowString);

                    $("#divobkshadowcolor").css("background", color || "rgb(0, 0, 0)");

                    $("#clsp1").val(color).css({ background: color, color: color });
                    $("#clsp6").val("#000").css({ background: "#2c2b2b", color: "#000" });

                    canvas.setActiveObject(activeObject);
                    getselobjprop();
                }

                break;
        }

    });


