    /**
     * Structured reference for paste.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    async function Paste() {
        if (!_clipboard) return;
        // clone again, so you can do multiple copies.
        var clonedObj = await _clipboard.clone();
        var pastedObjectIdMap = {};

            canvas.discardActiveObject();
            if (String(clonedObj.type).toLowerCase() === 'activeselection') {
                /* STAMP: 2026-09-01 - Detach cloned selection children using
                   their world transforms before adding them to the active slide. */
                clonedObj.canvas = canvas;
                var clonedChildren = clonedObj.getObjects().slice();
                var clonedTransforms = clonedChildren.map(function (obj) {
                    return obj.calcTransformMatrix();
                });
                clonedChildren.forEach(function (obj, childIndex) {
                    fabric.util.applyTransformToObject(obj, clonedTransforms[childIndex]);
                    obj.group = null;

                    var objectType = obj.get('type');
                    var previousObjectId = obj.id;
                    switch (objectType) {
                        case 'rect':
                            obj.id = generate_id('r_');
                            break;
                        case 'circle':
                            obj.id = generate_id('c_');
                            break;
                        case 'triangle':
                            obj.id = generate_id('t_');
                            break;
                        case 'line':
                            obj.id = generate_id('l_');
                            break;
                        case 'i-text':
                            obj.id = generate_id('tx_');
                            break;
                        case 'textbox':
                            obj.id = generate_id('textbox_');
                            break;
                        case 'image':
                            obj.id = generate_id('i_');
                            break;
                        case 'group':
                            obj.id = generate_id('g_');
                            break;
                    }
                    if (!obj.id || obj.id === previousObjectId) {
                        obj.id = generate_id(getObjectIdPrefix(objectType));
                    }
                    if (previousObjectId) pastedObjectIdMap[previousObjectId] = obj.id;
                    assignFreshFabricObjectIds(obj, pastedObjectIdMap, false);
                    if (slideact == "Same") {
                        obj.set('top', obj.top + 20);
                        obj.set('left', obj.left + 20);
                    } else {
                        obj.set('top', obj.top);
                        obj.set('left', obj.left);
                    }
                    obj.strokeUniform = true;
                    registerPastedObjectStructure(obj);
                    anyobject++;

                    canvas.add(obj);
                    canvas.renderAll();
                    updateCanvasState();

                });
                var pastedSelection = new fabric.ActiveSelection(clonedChildren, { canvas: canvas });
                canvas.setActiveObject(pastedSelection);
                pastedSelection.setCoords();
                canvas.requestRenderAll();
                updateCanvasState();
            } else {
                var objectType = clonedObj.get('type');
                var previousObjectId = clonedObj.id;
                switch (objectType) {
                    case 'rect':
                        clonedObj.id = generate_id('r_');
                        clonedObj.set("name", "Rect_" + random(4));
                        break;
                    case 'circle':
                        clonedObj.id = generate_id('c_');
                        clonedObj.set("name", "Circle_" + random(4));
                        break;
                    case 'triangle':
                        clonedObj.id = generate_id('t_');
                        clonedObj.set("name", "Triangle_" + random(4));
                        break;
                    case 'line':
                        clonedObj.id = generate_id('l_');
                        clonedObj.set("name", "Line_" + random(4));
                        break;
                    case 'i-text':
                        clonedObj.id = generate_id('tx_');
                        clonedObj.set("name", "Text_" + random(4));
                        break;
                    case 'textbox':
                        clonedObj.id = generate_id('textbox_');
                        clonedObj.set("name", "Text_" + random(4));
                        break;
                    case 'image':
                        clonedObj.id = generate_id('i_');
                        clonedObj.set("name", "Image_" + random(4));
                        break;
                    case 'group':
                        clonedObj.id = generate_id('g_');
                        clonedObj.set("name", "Group_" + random(4));
                        break;
                }
                if (!clonedObj.id || clonedObj.id === previousObjectId) {
                    clonedObj.id = generate_id(getObjectIdPrefix(objectType));
                }
                if (previousObjectId) pastedObjectIdMap[previousObjectId] = clonedObj.id;
                assignFreshFabricObjectIds(clonedObj, pastedObjectIdMap, false);
                if (slideact == "Same") {
                    clonedObj.set('top', clonedObj.top + clonedObj.height + 20);
                    clonedObj.set('left', clonedObj.left);
                } else {
                    clonedObj.set('top', clonedObj.top);
                    clonedObj.set('left', clonedObj.left);
                }
                clonedObj.strokeUniform = true;
                registerPastedObjectStructure(clonedObj);
                anyobject++;

                canvas.add(clonedObj);
                canvas.setActiveObject(clonedObj);
                canvas.renderAll();
                updateCanvasState();
                canvas.setActiveObject(clonedObj);
            }

        if (clipboardObjectAutomation) {
            applyObjectAutomation(
                generated_slides[slide_index],
                clipboardObjectAutomation.payload,
                pastedObjectIdMap,
                false,
                true
            );
            updateCanvasState();
            LoadTimeline();
        }

        getselobjprop();
    }

