    function performDeleteSelectedObjects() {
        canvas.isDrawingMode = false;
        var activeObjects = canvas.getActiveObject();
        if (!activeObjects) {
            safeHideModal("deleteObjectModal");
            return;
        }
        if (activeObjects._objects && activeObjects.type !== "group") {

            var objects = canvas.getActiveObject();
            objects._objects.forEach(function (object, key) {
                for (i = 0; i < ids.length; i++) {
                    if (object.id === ids[i]) {
                        ids.splice(i, 1);
                        popControl(object.id);
                    }
                }
                canvas.remove(object);
            });




            canvas.discardActiveObject();
            canvas.renderAll();
            updateCanvasState();
        } else {
            ids = jQuery.grep(ids, function (value) {
                return value !== canvas.getActiveObject().id;
            });
            popControl(canvas.getActiveObject().id);
            canvas.remove(canvas.getActiveObject());





        }
        LoadTimeline();
        canvas.requestRenderAll();
        $("#addshadow").show();
        $("#addshadow").html("Add");
        $(".addclickactn").show();
        $('.addclickactn').attr('onclick', 'addClickAction()').html('Add');
        $(".addloadactn").show();
        $('.addloadactn').attr('onclick', 'addLoadAction()').html('Add');
        hideDeletePrompt();
        safeHideModal("deleteObjectModal");
    }

    /* STAMP: 2026-08-29 - This preference applies only to object deletion.
       Slide/action confirmations and the underlying cleanup flow are unchanged. */
    var SKIP_OBJECT_DELETE_CONFIRMATION_KEY = "content-generator-skip-object-delete-confirmation-v1";

    function shouldSkipObjectDeleteConfirmation() {
        try {
            return window.localStorage.getItem(SKIP_OBJECT_DELETE_CONFIRMATION_KEY) === "true";
        } catch (error) {
            return false;
        }
    }

    $("#skipObjectDeleteConfirmation").prop("checked", shouldSkipObjectDeleteConfirmation()).on("change", function () {
        try {
            if (this.checked) {
                window.localStorage.setItem(SKIP_OBJECT_DELETE_CONFIRMATION_KEY, "true");
            } else {
                window.localStorage.removeItem(SKIP_OBJECT_DELETE_CONFIRMATION_KEY);
            }
        } catch (error) {
            console.warn("Object delete confirmation preference could not be saved", error);
        }
    });

    requestDeleteSelectedObjects = function () {
        var activeObject = canvas.getActiveObject();
        var activeGroup = canvas.getActiveObjects();
        if (!activeObject && (!activeGroup || activeGroup.length === 0)) {
            return false;
        }

        if (shouldSkipObjectDeleteConfirmation()) {
            performDeleteSelectedObjects();
            return false;
        }

        safeShowModal("deleteObjectModal", "Are you sure you want to delete the selected object?");
        return false;
    };

