    //Delete Key Press =====================================================
    $(document).on("keydown", function (e) {
        var ekeyCode = e.keyCode;
        var keyboardTarget = e.target;
        var isEditableTarget = keyboardTarget && (
            /^(INPUT|TEXTAREA|SELECT)$/.test(keyboardTarget.tagName)
            || keyboardTarget.isContentEditable
        );
        var activeTextObject = canvas.getActiveObject();
        var isEditingCanvasText = activeTextObject
            && (activeTextObject.type === "textbox" || activeTextObject.type === "i-text")
            && activeTextObject.isEditing;
        if (ekeyCode == 16) {
            $("#shifton").val("1");
        }
        if (ekeyCode == 17) {
            $("#ctrlon").val("1");
            ctrl = 1;
        }
        if (ekeyCode == 46) {
            canvas.isDrawingMode = false;
            var activeObject = canvas.getActiveObject();
            var activeGroup = canvas.getActiveObjects();
            if (!activeObject || !activeGroup || activeGroup.length === 0) {
                return;
            }
            var objectlenght;
            var type = activeObject.type;
            if (type == "textbox" || type == "i-text") {
                if (!activeObject.isEditing) {
                    objectlenght = 0;
                }
                else {
                    objectlenght = 1;
                }
            }
            else {
                objectlenght = 0;
            }
            if (activeGroup.length > 0 && objectlenght == 0) {
                if (hdnincanvas == '1') {
                    requestDeleteSelectedObjects();
                }
            }
        }
        if (ekeyCode == 37) {
            if (hdnincanvas == "1") {
                moveSelected(Direction.LEFT);
            }
        }
        if (ekeyCode == 38) {
            if (hdnincanvas == "1") {
                event.view.event.preventDefault();
                moveSelected(Direction.UP);
            } else {
                if ($("#shifton").val() == "1") {
                    checkFocus("BigPlus");
                } else {
                    checkFocus("Plus");
                }
            }
        }
        if (ekeyCode == 39) {
            if (hdnincanvas == "1") {
                moveSelected(Direction.RIGHT);
            }
        }
        if (ekeyCode == 40) {
            if (hdnincanvas == "1") {
                event.view.event.preventDefault();
                moveSelected(Direction.DOWN);
            } else {
                if ($("#shifton").val() == "1") {
                    checkFocus("BigMinus");
                } else {
                    checkFocus("Minus");
                }
            }
        }
        var historyModifier = ctrl == 1 || e.ctrlKey || e.metaKey;
        if (ekeyCode == 89 && historyModifier) {
            e.preventDefault();
            $('#redo').click();
        }
        if (ekeyCode == 90 && historyModifier) {
            e.preventDefault();
            if (e.shiftKey) $('#redo').click();
            else $('#undo').click();
        }
        if (ekeyCode == 190) {
        }
        if (ekeyCode == 27 && hdnincanvas == "1" && !isEditableTarget && !isEditingCanvasText) {
            e.preventDefault();
            ResetCanvasObjects();
        }
        var clipboardModifier = e.ctrlKey || e.metaKey;
        /* STAMP: 2026-09-10 - Canvas-scoped Select All mirrors the visible
         * multiselect action without hijacking form fields or text editing. */
        if (clipboardModifier && ekeyCode == 65 && hdnincanvas == "1" && !isEditableTarget && !isEditingCanvasText) {
            e.preventDefault();
            selectAllCanvasObjects();
        }
        if (clipboardModifier && e.which == cKey && hdnincanvas == "1" && !isEditableTarget && !isEditingCanvasText) {
            e.preventDefault();
            CopyActiveObject();
        }
        if (clipboardModifier && e.which == vKey && !isEditableTarget && !isEditingCanvasText) {
            var activeObject = canvas.getActiveObject();

            if (activeObject == null && hdnincanvas == "1") {
                e.preventDefault();
                Paste();
            }
            else if (!activeObject.isEditing && hdnincanvas == "1") {
                e.preventDefault();
                Paste();
            }
        }
    });

    $(document).on("keyup", function (e) {
        var ekeyCode = e.keyCode;
        if (ekeyCode == 16) {
            $("#shifton").val("0");
        }

        if (ekeyCode == 17) {
            $("#ctrlon").val("0");
            ctrl = 0;
        }

        var keyboardTarget = e.target;
        var activeTextObject = canvas.getActiveObject();
        var isEditingCanvasText = activeTextObject
            && (activeTextObject.type === "textbox" || activeTextObject.type === "i-text")
            && activeTextObject.isEditing;
        var isEditableTarget = keyboardTarget && (
            /^(INPUT|TEXTAREA|SELECT)$/.test(keyboardTarget.tagName)
            || keyboardTarget.isContentEditable
        );
        if (ekeyCode == 27 && hdnincanvas == "1" && !isEditableTarget && !isEditingCanvasText) {
            ResetCanvasObjects();
        }
    });

    // STAMP: 2026-08-18 - Awaited, slide-scoped Fabric 7 history navigation.
    function moveCanvasHistory(direction) {
        var history = getSlideHistory(selected_slide_id);
        // Capture changes made by older property controls only at the live tip.
        // Never capture during redo traversal because that would discard its branch.
        if (direction < 0 && history && history.currentStateIndex === history.canvasState.length - 1) {
            updateCanvasState();
            history = getSlideHistory(selected_slide_id);
        }
        var targetIndex = history ? history.currentStateIndex + direction : -1;
        if (ruConfig.isRestoring || !history || targetIndex < 0 || targetIndex >= history.canvasState.length) {
            refreshUndoRedoButtons(selected_slide_id);
            return Promise.resolve(false);
        }
        var historySlideId = selected_slide_id;
        ruConfig.undoFinishedStatus = 0;
        ruConfig.redoFinishedStatus = 0;
        ruConfig.undoStatus = direction < 0;
        ruConfig.redoStatus = direction > 0;
        ruConfig.isRestoring = true;
        refreshUndoRedoButtons(historySlideId);

        return loadCanvasStateSnapshot(history.canvasState[targetIndex]).then(function (restored) {
            if (!restored || selected_slide_id !== historySlideId) return false;
            // Fabric normalizes defaults while enlivening; retain that equivalent form
            // so the next redo is not mistaken for a new user mutation.
            history.canvasState[targetIndex] = getCanvasStateSnapshot();
            history.currentStateIndex = targetIndex;
            persistActiveSlideState();
            updateSlideThumbnail(historySlideId, canvas.toDataURL());
            return true;
        }).finally(function () {
            ruConfig.undoStatus = false;
            ruConfig.redoStatus = false;
            ruConfig.undoFinishedStatus = 1;
            ruConfig.redoFinishedStatus = 1;
            refreshUndoRedoButtons(selected_slide_id);
        });
    }

    $('#undo').off('click.cgHistory').on('click.cgHistory', function (event) {
        event.preventDefault();
        moveCanvasHistory(-1);
    });

    $('#redo').off('click.cgHistory').on('click.cgHistory', function (event) {
        event.preventDefault();
        moveCanvasHistory(1);
    });

