    /**
     * STAMP: 2026-08-20 - Persist the opt-in timer on the active slide only.
     * Invalid values fall back to three seconds to prevent zero-delay loops.
     */
    function persistCurrentSlideAutoNavigate() {
        if (!Array.isArray(generated_slides) || !generated_slides[slide_index]) return;
        var slide = generated_slides[slide_index];
        var hasAudio = typeof slide.SlideAudio === "string" && slide.SlideAudio.trim();
        var hasVideo = typeof slide.SlideVideo === "string" && slide.SlideVideo.trim();
        var hasMedia = !!(hasAudio || hasVideo);
        var seconds = Math.round(Number($("#slideautonavigateseconds").val()));
        if (!Number.isFinite(seconds) || seconds < 1) seconds = 3;
        seconds = Math.min(seconds, 3600);
        $("#slideautonavigateseconds").val(seconds);
        generated_slides[slide_index].AutoNavigate = $("#slideautonavigate").is(":checked") ? 1 : 0;
        generated_slides[slide_index].AutoNavigateSeconds = seconds;
        generated_slides[slide_index].AutoNavigateOnMediaEnd = hasMedia && $("#slideautonavigateonmediaend").is(":checked") ? 1 : 0;
    }

