    function loadArticulationVoices() {
        if (!window.speechSynthesis) return;
        var selected = $("#articulationvoice").val() || "";
        var voices = window.speechSynthesis.getVoices();
        var options = '<option value="">Automatic</option>';
        voices.forEach(function (voice) {
            options += '<option value="' + $("<div>").text(voice.voiceURI).html() + '">' + $("<div>").text(voice.name + " (" + voice.lang + ")").html() + '</option>';
        });
        $("#articulationvoice").html(options).val(selected);
    }

    function findArticulationVoice(style, voiceURI) {
        var voices = window.speechSynthesis ? window.speechSynthesis.getVoices() : [];
        var exact = voices.find(function (voice) { return voice.voiceURI === voiceURI; });
        if (exact) return exact;
        var patterns = style === "male"
            ? /david|mark|daniel|george|james|male/i
            : style === "female"
                ? /zira|samantha|victoria|karen|susan|female/i
                : /zira|samantha|david|mark/i;
        return voices.find(function (voice) { return patterns.test(voice.name); }) || voices[0] || null;
    }

    $("#previewarticulationvoice").on("click", function () {
        if ($("#articulationprovider").val() === "elevenlabs") {
            var elevenSettings = getArticulationVoiceSettings();
            var elevenSample = ($("#articulationscript").val() || "").trim() || "This is an ElevenLabs narration preview.";
            if (!elevenSettings.elevenLabsVoiceId) {
                alert("Enter an ElevenLabs voice ID before previewing.");
                return;
            }
            var generator = window.parent && window.parent.generateElevenLabsSpeech;
            if (typeof generator !== "function") {
                alert("ElevenLabs narration service is unavailable.");
                return;
            }
            generator({ text: elevenSample, voiceId: elevenSettings.elevenLabsVoiceId, modelId: elevenSettings.elevenLabsModel, stability: elevenSettings.elevenLabsStability, similarityBoost: elevenSettings.elevenLabsSimilarity, speed: elevenSettings.rate })
                .then(function (audioUrl) { var audio = new Audio(audioUrl); audio.play(); })
                .catch(function (error) { alert(error.message || "Unable to preview ElevenLabs voice."); });
            return;
        }
        if (!window.speechSynthesis || !window.SpeechSynthesisUtterance) {
            alert("Voice preview is not supported by this browser.");
            return;
        }
        var settings = getArticulationVoiceSettings();
        var sample = ($("#articulationscript").val() || "").trim() || "This is a preview of your selected narration voice.";
        var utterance = new window.SpeechSynthesisUtterance(sample);
        utterance.pitch = settings.voiceStyle === "robot" ? 0.65 : settings.pitch;
        utterance.rate = settings.voiceStyle === "robot" ? Math.min(1.35, settings.rate * 0.88) : settings.rate;
        utterance.voice = findArticulationVoice(settings.voiceStyle, settings.voiceURI);
        window.speechSynthesis.cancel();
        window.speechSynthesis.resume();
        window.speechSynthesis.speak(utterance);
    });

