    //Distrubute Items Horizontally ====================================================================
    $('#objdisthorgrp').on('click', function () {
        var activeObject = canvas.getActiveObject();
        activeObject.setOriginToCenter && activeObject.setOriginToCenter();
        var items = canvas.getActiveObject()._objects;

        items = getSortedItems(items, 'Left');

        var defBound = items[0].getBoundingRect();
        var minLeft = defBound.left;
        var maxLeft = defBound.left;
        for (var i = 0; i < items.length; i++) {
            var bound = items[i].getBoundingRect();
            if (bound.left < minLeft) {
                minLeft = bound.left;
            }
            if (bound.left > maxLeft) {
                maxLeft = bound.left;
            }
        }

        var diffLeft = ((maxLeft - minLeft) / (items.length - 1));
        for (var i = 0; i < items.length; i++) {
            var bound = items[i].getBoundingRect();
            if (i == 0) {
                items[i].set({
                    left: minLeft + items[i].left - bound.left
                });
                items[i].setCoords();
            } else if (i == items.length - 1) {
                items[i].set({
                    left: maxLeft + items[i].left - bound.left
                });
                items[i].setCoords();
            } else {
                items[i].setOriginToCenter && items[i].setOriginToCenter();
                items[i].set({
                    //left: minLeft + (diffLeft * i) + items[i].left - bound.left
                    left: minLeft + (diffLeft * i) + (items[0].getBoundingRect().width / 2)
                });
                items[i].setCoords();
                items[i].setCenterToOrigin && items[i].setCenterToOrigin();
            }
        }
        canvas.renderAll();
        updateCanvasState();
        activeObject.setCenterToOrigin && activeObject.setCenterToOrigin();

    });

