    //Function to Sort Items ======================================================
    /**
     * Return grouped items sorted by the requested positional axis.
     *
     * @param {*} items Runtime parameter preserved from the source implementation.
     * @param {*} position Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    getSortedItems = function (items, position) {
        for (var i = items.length - 1; i >= 0; i--) {
            for (var j = i; j >= 0; j--) {
                var bound_i = items[i].getBoundingRect();
                var bound_j = items[j].getBoundingRect();
                if (position == 'Left') {
                    if (bound_i.left < bound_j.left) {
                        var temp = items[i];
                        items[i] = items[j];
                        items[j] = temp;
                    };
                }
                else if (position == 'Top') {
                    if (bound_i.top < bound_j.top) {
                        var temp = items[i];
                        items[i] = items[j];
                        items[j] = temp;
                    };
                }
            };
        };
        return items;
    }

