    //UnGroup Objects =============================================
    $("#ungroup").on('click', function () {
        //if (!canvas.getActiveObject()) {
        //    return;
        //}
        //if (canvas.getActiveObject().type !== 'group') {
        //    return;
        //}
        //canvas.getActiveObject().toActiveSelection();
        //canvas.requestRenderAll();

        if ($(obj).hasClass("disabled-li") === true) {
            return;
        }
        var activeObject = canvas.getActiveObject();
        if (activeObject.type === "group") {
            if (static_groups.includes(activeObject.id)) {
                return;
            }
            /* STAMP: 2026-08-31 - Capture every child's complete canvas-space
               transform before detaching it so ungroup never changes placement. */
            var childWorldTransforms = activeObject._objects.map(function (item) {
                return item.calcTransformMatrix();
            });
            var items = activeObject.removeAll();
            items.forEach(function (item, itemIndex) {
                fabric.util.applyTransformToObject(item, childWorldTransforms[itemIndex]);
                item.setCoords();
            });
            canvas.remove(activeObject);
            for (var i = 0; i < items.length; i++) {
                var objectType = items[i].type;
                anyobject++;

                canvas.add(items[i]);
                canvas.item(canvas.size() - 1).hasControls = true;
                var temp_id = items[i].id;
                pushControl(temp_id, objectType);
            }
            canvas.renderAll();
            updateCanvasState();
            popControl(activeObject.id);
        }
    });

    //Un Group Objects =============================================
    /**
     * Structured reference for ungroup.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    function ungroup() {
        var fabGroupeSelectionne = canvas.getActiveObject();
        var i = 0;
        var lItems = fabGroupeSelectionne._objects;

        //I keep the coordinates of my group (my objects are at the top anf left of the group)
        iGaucheGroupe = fabGroupeSelectionne.left;
        iHautGroupe = fabGroupeSelectionne.top;

        //I delete the group
        canvas.remove(fabGroupeSelectionne);
        while (i < fabGroupeSelectionne.size()) {

            //I create separatly the objects of the group
            lItems[i].set({ left: iGaucheGroupe, top: iHautGroupe, selectable: true });
            anyobject++;

            canvas.add(lItems[i]);
            i++;
        }
        canvas.renderAll();
        updateCanvasState();
    }

    //Group Objects =============================================
    /**
     * Structured reference for group.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    async function group() {
        var sourceObjects = [canvas.item(canvas.size() - 2), canvas.item(canvas.size() - 1)];
        var clonedObjects = await Promise.all(sourceObjects.map(function (object) { return object.clone(); }));
        var fabReGroup = new fabric.Group(clonedObjects);
        fabReGroup.set({ left: iGaucheGroupe, top: iHautGroupe });
        canvas.remove(sourceObjects[0], sourceObjects[1]);
        anyobject++;

        canvas.add(fabReGroup);
    }

