    /**
     * Structured reference for move selected.
     *
     * @param {*} direction Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    function moveSelected(direction) {
        var activeObject = canvas.getActiveObject();
        var activeGroup = canvas.getActiveObjects();

        if (activeObject) {
            switch (direction) {
                case Direction.LEFT:
                    if (activeObject.lockMovementX == true && activeObject.lockMovementY == true && activeObject.lockScalingX == true && activeObject.lockScalingY == true && activeObject.lockRotation == true) {
                        return false;
                    }
                    else {
                        if ($("#shifton").val() == "1") {
                            activeObject.left = activeObject.left - BIGSTEP;
                        }
                        else {
                            if (IsGroupObject == 0) {
                                activeObject.left = activeObject.left - STEP;
                            } else {
                                var activeObject = canvas.getActiveObject();
                                var items = activeObject._objects;
                                items[selectedarray].set({
                                    left: (items[selectedarray].left - STEP),
                                    originX: 'left'
                                });
                            }
                        }
                    }
                    break;
                case Direction.UP:
                    if (activeObject.lockMovementX == true && activeObject.lockMovementY == true && activeObject.lockScalingX == true && activeObject.lockScalingY == true && activeObject.lockRotation == true) {
                        return false;
                    }
                    else {
                        if ($("#shifton").val() == "1") {
                            activeObject.top = activeObject.top - BIGSTEP;
                        }
                        else {
                            if (IsGroupObject == 0) {
                                activeObject.top = activeObject.top - STEP;
                            } else {
                                var activeObject = canvas.getActiveObject();
                                var items = activeObject._objects;
                                items[selectedarray].set({
                                    top: (items[selectedarray].top - STEP),
                                    originX: 'left'
                                });

                            }
                        }
                    }
                    break;
                case Direction.RIGHT:
                    if (activeObject.lockMovementX == true && activeObject.lockMovementY == true && activeObject.lockScalingX == true && activeObject.lockScalingY == true && activeObject.lockRotation == true) {
                        return false;
                    }
                    else {
                        if ($("#shifton").val() == "1") {
                            activeObject.left = activeObject.left + BIGSTEP;
                        }
                        else {
                            if (IsGroupObject == 0) {
                                activeObject.left = activeObject.left + STEP;
                            } else {
                                var activeObject = canvas.getActiveObject();
                                var items = activeObject._objects;
                                items[selectedarray].set({
                                    left: (items[selectedarray].left + STEP),
                                    originX: 'left'
                                });

                            }
                        }
                    }
                    break;
                case Direction.DOWN:
                    if (activeObject.lockMovementX == true && activeObject.lockMovementY == true && activeObject.lockScalingX == true && activeObject.lockScalingY == true && activeObject.lockRotation == true) {
                        return false;
                    }
                    else {
                        if ($("#shifton").val() == "1") {
                            activeObject.top = activeObject.top + BIGSTEP;
                        }
                        else {
                            if (IsGroupObject == 0) {
                                activeObject.top = activeObject.top + STEP;
                            } else {
                                var activeObject = canvas.getActiveObject();
                                var items = activeObject._objects;
                                items[selectedarray].set({
                                    top: (items[selectedarray].top + STEP),
                                    originX: 'left'
                                });

                            }
                        }
                    }
                    break;
            }
            activeObject.setCoords();
            canvas.renderAll();
            updateCanvasState();
        } else if (activeGroup.length > 0) {
            switch (direction) {
                case Direction.LEFT:
                    if (activeGroup.lockMovementX == true && activeGroup.lockMovementY == true && activeGroup.lockScalingX == true && activeGroup.lockScalingY == true && activeGroup.lockRotation == true) {
                        return false;
                    }
                    else {
                        if ($("#shifton").val() == "1") {
                            activeGroup.left = activeGroup.left - BIGSTEP;
                        }
                        else {
                            activeGroup.left = activeGroup.left - STEP;
                        }
                    }
                    break;
                case Direction.UP:
                    if (activeGroup.lockMovementX == true && activeGroup.lockMovementY == true && activeGroup.lockScalingX == true && activeGroup.lockScalingY == true && activeGroup.lockRotation == true) {
                        return false;
                    }
                    else {
                        if ($("#shifton").val() == "1") {
                            activeGroup.top = activeGroup.top - BIGSTEP;
                        }
                        else {
                            activeGroup.top = activeGroup.top - STEP;
                        }
                    }
                    break;
                case Direction.RIGHT:
                    if (activeGroup.lockMovementX == true && activeGroup.lockMovementY == true && activeGroup.lockScalingX == true && activeGroup.lockScalingY == true && activeGroup.lockRotation == true) {
                        return false;
                    }
                    else {
                        if ($("#shifton").val() == "1") {
                            activeGroup.left = activeGroup.left + BIGSTEP;
                        }
                        else {
                            activeGroup.left = activeGroup.left + STEP;
                        }
                    }
                    break;
                case Direction.DOWN:
                    if (activeGroup.lockMovementX == true && activeGroup.lockMovementY == true && activeGroup.lockScalingX == true && activeGroup.lockScalingY == true && activeGroup.lockRotation == true) {
                        return false;
                    }
                    else {
                        if ($("#shifton").val() == "1") {
                            activeGroup.top = activeGroup.top + BIGSTEP;
                        }
                        else {
                            activeGroup.top = activeGroup.top + STEP;
                        }
                    }
                    break;
            }
            activeGroup.setCoords();
            canvas.renderAll();
            updateCanvasState();
        } else {

            switch (direction) {
                case Direction.LEFT:
                    var units;
                    if ($("#shifton").val() == "1") {
                        units = 30;
                    }
                    else {
                        units = 10;
                    }
                    var delta = new fabric.Point(-units, 0);
                    canvas.relativePan(delta);
                    break;
                case Direction.UP:
                    var units;
                    if ($("#shifton").val() == "1") {
                        units = 30;
                    }
                    else {
                        units = 10;
                    }
                    var delta = new fabric.Point(0, -units);
                    canvas.relativePan(delta);
                    break;
                case Direction.RIGHT:
                    var units;
                    if ($("#shifton").val() == "1") {
                        units = 30;
                    }
                    else {
                        units = 10;
                    }
                    var delta = new fabric.Point(units, 0);
                    canvas.relativePan(delta);
                    break;
                case Direction.DOWN:
                    var units;
                    if ($("#shifton").val() == "1") {
                        units = 30;
                    }
                    else {
                        units = 10;
                    }
                    var delta = new fabric.Point(0, units);
                    canvas.relativePan(delta);
                    break;
            }
        }
    }

    /**
     * STAMP: 2026-09-01 - Fabric 7 compatible ActiveSelection grouping.
     * The removed legacy toGroup_custom extension is replaced while preserving
     * every child's world transform and the existing group metadata workflow.
     */
    function convertActiveSelectionToGroup(groupId) {
        var selection = canvas.getActiveObject();
        if (!selection || String(selection.type).toLowerCase() !== "activeselection") return null;
        var objects = selection.getObjects().slice();
        if (objects.length < 2) return null;
        var transforms = objects.map(function (object) {
            return object.calcTransformMatrix();
        });

        canvas.discardActiveObject();
        objects.forEach(function (object, index) {
            fabric.util.applyTransformToObject(object, transforms[index]);
            canvas.remove(object);
        });
        var groupedObject = new fabric.Group(objects, {
            id: groupId,
            name: "Group_" + random(4)
        });
        groupedObject.strokeUniform = true;
        canvas.add(groupedObject);
        canvas.setActiveObject(groupedObject);
        groupedObject.setCoords();
        return groupedObject;
    }

