    //Ungroup area ======================================
    $("#ungroupobjects").on('click', function () {
        $("#groupobjects").show(); $("#SharePropAll").show();
        $("#ungroupobjects").hide();
        $(".tdatc").show();
        $("#chkaligncanvas").attr('checked', false);
        $("#chkaligncanvas").parent().removeClass("checked");
        //if (!canvas.getActiveObject()) {
        //    return;
        //}
        //if (canvas.getActiveObject().type !== 'group') {
        //    return;
        //}

        //canvas.getActiveObject().toActiveSelection();
        //canvas.requestRenderAll();

        var activeObject = canvas.getActiveObject();
        if (activeObject.type === "group") {
            if (static_groups.includes(activeObject.id)) {
                return;
            }

            /* STAMP: 2026-08-31 - Preserve the precise world transform of each
               grouped child across removal, including scale, rotation and flip. */
            var childWorldTransforms = activeObject._objects.map(function (item) {
                return item.calcTransformMatrix();
            });
            var items = activeObject.removeAll();
            items.forEach(function (item, itemIndex) {
                fabric.util.applyTransformToObject(item, childWorldTransforms[itemIndex]);
                item.setCoords();
            });
            canvas.remove(activeObject);
            for (var i = 0; i < items.length; i++) {
                var objectType = items[i].type;
                switch (objectType) {
                    case 'rect':
                        items[i].id = generate_id('r_');
                        break;
                    case 'circle':
                        items[i].id = generate_id('c_');
                        break;
                    case 'triangle':
                        items[i].id = generate_id('t_');
                        break;
                    case 'line':
                        items[i].id = generate_id('l_');
                        break;
                    case 'i-text':
                        items[i].id = generate_id('tx_');
                        break;
                    case 'textbox':
                        items[i].id = generate_id('textbox_');
                        break;
                    case 'image':
                        items[i].id = generate_id('i_');
                        break;
                    case 'group':
                        items[i].id = generate_id('g_');
                        break;
                }
                anyobject++;

                canvas.add(items[i]);
                canvas.item(canvas.size() - 1).hasControls = true;
                pushControl(items[i].id, objectType);
            }
            canvas.renderAll();
            updateCanvasState();

            getselobjprop();
            popControl(activeObject.id);
        }
    });

