    /**
     * Structured reference for build iframe from input.
     *
     * @param {*} input Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    function buildIframeFromInput(input) {
        var text = (input || "").trim();

        // Case 1: user pasted full iframe
        if (text.toLowerCase().includes("<iframe")) return text;

        // Case 2: YouTube / Vimeo URLs → convert to embed iframe
        var url;
        try { url = new URL(text); } catch { return ""; }

        var host = url.hostname.replace("www.", "");
        var embed = "";

        if (host.includes("youtube.com")) {
            var v = url.searchParams.get("v");
            if (v) embed = "https://www.youtube.com/embed/" + v;
        }

        if (host.includes("youtu.be")) {
            var id = url.pathname.replace("/", "");
            embed = "https://www.youtube.com/embed/" + id;
        }

        if (host.includes("vimeo.com")) {
            var id = url.pathname.replace("/", "");
            embed = "https://player.vimeo.com/video/" + id;
        }

        if (!embed) return "";

        return `<iframe src="${embed}" allowfullscreen></iframe>`;
    }

    (function () {
        var txt = document.getElementById("txtsldvideoembedlink");
        var preview = document.getElementById("sld-video-preview");
        var previewInner = document.getElementById("sld-video-preview-inner");



        // --- SHOW PREVIEW ---
        /**
         * Structured reference for show preview.
         *
         * @param {*} html Runtime parameter preserved from the source implementation.
         * @param {*} original Runtime parameter preserved from the source implementation.
         * @returns {*} Value and side effects preserved from the source implementation.
         */
        function showPreview(html, original) {
            previewInner.innerHTML = html;
            preview.classList.remove("d-none");
            txt.classList.add("d-none");
            txt.value = original;
        }
        // --- MAGIC: SHOW PREVIEW WHEN USER PASTES ---
        txt.addEventListener("paste", function (e) {
            setTimeout(function () {
                var value = txt.value.trim();
                if (!value) return;

                var iframe = buildIframeFromInput(value);
                if (iframe) showPreview(iframe, value);

                // TODO: Hook: ADD VIDEO TO FABRIC CANVAS
                // addVideoToCanvas(iframe);

            }, 50); // allow paste to finish
        });
    })();

    /* Modern slide video embed helpers stamped 2026-04-23:
       normalize supported URLs and iframe snippets into one preview/apply path
       so the dropdown stays simple without changing the saved slide result. */
    function buildIframeFromInput(input) {
        var text = (input || "").trim();
        if (!text) return "";

        var iframeAttributes = [
            'loading="lazy"',
            'referrerpolicy="strict-origin-when-cross-origin"',
            'allow="autoplay; encrypted-media; fullscreen; picture-in-picture"',
            'allowfullscreen'
        ];

        function normalizeIframeElement(iframe) {
            if (!iframe) return "";

            var src = (iframe.getAttribute("src") || "").trim();
            if (!src) return "";

            iframe.setAttribute("src", src);
            iframe.setAttribute("loading", "lazy");
            iframe.setAttribute("referrerpolicy", "strict-origin-when-cross-origin");
            iframe.setAttribute("allow", "autoplay; encrypted-media; fullscreen; picture-in-picture");
            iframe.setAttribute("allowfullscreen", "");

            if (!iframe.getAttribute("title")) {
                iframe.setAttribute("title", "Embedded video");
            }

            return iframe.outerHTML;
        }

        if (text.toLowerCase().includes("<iframe")) {
            var wrapper = document.createElement("div");
            wrapper.innerHTML = text;
            return normalizeIframeElement(wrapper.querySelector("iframe"));
        }

        var url;
        try {
            url = new URL(text);
        } catch {
            return "";
        }

        var host = url.hostname.replace("www.", "").toLowerCase();
        var embed = "";

        if (host.includes("youtube.com")) {
            var youtubeId = url.searchParams.get("v");

            if (!youtubeId && url.pathname.includes("/embed/")) {
                youtubeId = url.pathname.split("/embed/")[1];
            }

            if (!youtubeId && url.pathname.includes("/shorts/")) {
                youtubeId = url.pathname.split("/shorts/")[1];
            }

            if (youtubeId) {
                youtubeId = youtubeId.split(/[?&/]/)[0];
                embed = "https://www.youtube.com/embed/" + youtubeId;
            }
        }

        if (host.includes("youtu.be")) {
            var shortYoutubeId = url.pathname.replace(/^\/+/, "").split("/")[0];
            if (shortYoutubeId) {
                embed = "https://www.youtube.com/embed/" + shortYoutubeId;
            }
        }

        if (host.includes("vimeo.com")) {
            var pathSegments = url.pathname.split("/").filter(Boolean);
            var vimeoId = pathSegments.length ? pathSegments[pathSegments.length - 1] : "";
            if (vimeoId) {
                embed = "https://player.vimeo.com/video/" + vimeoId;
            }
        }

        if (!embed) return "";

        return '<iframe src="' + embed + '" title="Embedded video" ' + iframeAttributes.join(" ") + "></iframe>";
    }

    function detectVideoProviderFromSrc(src) {
        var normalizedSrc = (src || "").toLowerCase();

        if (normalizedSrc.indexOf("youtube.com") !== -1 || normalizedSrc.indexOf("youtu.be") !== -1) {
            return "YouTube";
        }

        if (normalizedSrc.indexOf("vimeo.com") !== -1) {
            return "Vimeo";
        }

        return "Video";
    }

    function getVideoEmbedDetails(input) {
        var iframeHtml = buildIframeFromInput(input);
        if (!iframeHtml) return null;

        var wrapper = document.createElement("div");
        wrapper.innerHTML = iframeHtml;

        var iframe = wrapper.querySelector("iframe");
        if (!iframe) return null;

        var src = (iframe.getAttribute("src") || "").trim();
        if (!src) return null;

        return {
            iframeHtml: iframe.outerHTML,
            provider: detectVideoProviderFromSrc(src),
            src: src
        };
    }

