    /**
     * STAMP: 2026-08-31 - Browser-local slide audio optimizer.
     * Decodes the chosen file, mixes it to mono, resamples it, and writes a
     * standards-compliant PCM WAV. The original upload contract is unchanged.
     */
    function getSlideAudioQualityProfile(value) {
        var profiles = {
            high: { sampleRate: 32000, bitDepth: 16, label: "High" },
            balanced: { sampleRate: 22050, bitDepth: 16, label: "Balanced" },
            compact: { sampleRate: 16000, bitDepth: 8, label: "Compact" }
        };
        return profiles[value] || profiles.balanced;
    }

    function getAudioFileExtension(mimeType) {
        var normalized = String(mimeType || "").toLowerCase();
        if (normalized.indexOf("wav") >= 0) return "wav";
        if (normalized.indexOf("ogg") >= 0) return "ogg";
        if (normalized.indexOf("webm") >= 0) return "webm";
        if (normalized.indexOf("mp4") >= 0 || normalized.indexOf("m4a") >= 0) return "m4a";
        return "mp3";
    }

    function writeWaveString(view, offset, value) {
        for (var i = 0; i < value.length; i++) view.setUint8(offset + i, value.charCodeAt(i));
    }

    function encodeAudioBufferAsWave(audioBuffer, profile) {
        var outputLength = Math.max(1, Math.ceil(audioBuffer.duration * profile.sampleRate));
        var bytesPerSample = profile.bitDepth === 8 ? 1 : 2;
        var buffer = new ArrayBuffer(44 + outputLength * bytesPerSample);
        var view = new DataView(buffer);
        var sourceRate = audioBuffer.sampleRate;
        var channels = [];
        var channelIndex;

        for (channelIndex = 0; channelIndex < audioBuffer.numberOfChannels; channelIndex++) {
            channels.push(audioBuffer.getChannelData(channelIndex));
        }

        writeWaveString(view, 0, "RIFF");
        view.setUint32(4, 36 + outputLength * bytesPerSample, true);
        writeWaveString(view, 8, "WAVE");
        writeWaveString(view, 12, "fmt ");
        view.setUint32(16, 16, true);
        view.setUint16(20, 1, true);
        view.setUint16(22, 1, true);
        view.setUint32(24, profile.sampleRate, true);
        view.setUint32(28, profile.sampleRate * bytesPerSample, true);
        view.setUint16(32, bytesPerSample, true);
        view.setUint16(34, profile.bitDepth, true);
        writeWaveString(view, 36, "data");
        view.setUint32(40, outputLength * bytesPerSample, true);

        for (var outputIndex = 0; outputIndex < outputLength; outputIndex++) {
            var sourcePosition = outputIndex * sourceRate / profile.sampleRate;
            var sourceIndex = Math.min(audioBuffer.length - 1, Math.floor(sourcePosition));
            var nextSourceIndex = Math.min(audioBuffer.length - 1, sourceIndex + 1);
            var fraction = sourcePosition - sourceIndex;
            var sample = 0;

            for (channelIndex = 0; channelIndex < channels.length; channelIndex++) {
                sample += channels[channelIndex][sourceIndex]
                    + (channels[channelIndex][nextSourceIndex] - channels[channelIndex][sourceIndex]) * fraction;
            }

            sample = Math.max(-1, Math.min(1, sample / channels.length));
            if (profile.bitDepth === 8) {
                view.setUint8(44 + outputIndex, Math.round((sample + 1) * 127.5));
            } else {
                view.setInt16(44 + outputIndex * 2, sample < 0 ? sample * 32768 : sample * 32767, true);
            }
        }

        return new Blob([buffer], { type: "audio/wav" });
    }

    function setSlideAudioOptimizerState(message, isBusy) {
        $("#slideAudioOptimizerState").text(message);
        $("#slideAudioQuality, #useOriginalSlideAudio").prop("disabled", !!isBusy);
        $("#useOptimizedSlideAudio").prop("disabled", !!isBusy || !pendingSlideAudioOptimization || !pendingSlideAudioOptimization.optimized);
    }

    async function prepareSlideAudioOptimization(file) {
        var token = ++slideAudioOptimizationToken;
        var profile = getSlideAudioQualityProfile($("#slideAudioQuality").val());
        var AudioContextClass = window.AudioContext || window.webkitAudioContext;

        pendingSlideAudioOptimization = { file: file, original: null, optimized: null };
        $("#slideAudioOptimizer").prop("hidden", false);
        $("#slideAudioOriginalSize").text(formatBytes(file.size));
        $("#slideAudioOptimizedSize, #slideAudioSizeDifference").text("-");
        $("#slideMediaSaveBtn").prop("hidden", true);
        $("#useOriginalSlideAudio, #useOptimizedSlideAudio").removeClass("active").attr("aria-pressed", "false");
        setSlideAudioOptimizerState("Optimizing...", true);

        try {
            if (!AudioContextClass) throw new Error("Audio optimization is not supported by this browser.");
            var originalDataUrlPromise = audioToBase64(file);
            var context = new AudioContextClass();
            var sourceBytes = await file.arrayBuffer();
            var decodedAudio = await context.decodeAudioData(sourceBytes.slice(0));
            var optimizedBlob = encodeAudioBufferAsWave(decodedAudio, profile);
            var originalDataUrl = await originalDataUrlPromise;
            if (typeof context.close === "function") context.close();
            if (token !== slideAudioOptimizationToken) return;

            var difference = file.size - optimizedBlob.size;
            var isSmaller = difference > 0;
            var optimizedDataUrl = isSmaller ? await blobToDataUrl(optimizedBlob) : null;
            if (token !== slideAudioOptimizationToken) return;
            var differenceLabel = isSmaller ? formatBytes(difference) + " smaller" : "No reduction";
            pendingSlideAudioOptimization = {
                file: file,
                original: { base64: originalDataUrl, mime: file.type || "audio/mpeg", size: file.size },
                // Never expose an "optimized" choice that increases file size.
                optimized: isSmaller
                    ? { base64: optimizedDataUrl, mime: "audio/wav", size: optimizedBlob.size, profile: profile }
                    : null
            };
            $("#slideAudioOptimizedSize").text(isSmaller ? formatBytes(optimizedBlob.size) : "Not smaller");
            $("#slideAudioSizeDifference").text(differenceLabel);
            if (isSmaller) {
                $("#slideAudioOptimizerNote").text(
                    profile.label + " quality: mono, " + (profile.sampleRate / 1000).toFixed(profile.sampleRate % 1000 ? 2 : 0)
                    + " kHz, " + profile.bitDepth + "-bit. Choose either version below."
                );
                setSlideAudioOptimizerState("Reduced", false);
            } else {
                $("#slideAudioOptimizerNote").text(
                    "This file is already smaller than the processed version at " + profile.label
                    + " quality. Use the original or try a lower quality; a larger file will never be offered."
                );
                setSlideAudioOptimizerState("Original is smaller", false);
            }
        } catch (error) {
            console.error("Audio optimization failed", error);
            if (token !== slideAudioOptimizationToken) return;
            var originalDataUrl = await audioToBase64(file);
            pendingSlideAudioOptimization = {
                file: file,
                original: { base64: originalDataUrl, mime: file.type || "audio/mpeg", size: file.size },
                optimized: null
            };
            $("#slideAudioOptimizerNote").text("Optimization is unavailable for this audio. You can still use the original file.");
            setSlideAudioOptimizerState("Original available", false);
        }
    }

