    document.getElementById('uploadvid').addEventListener("change", function (e) {
        videoToBase64(this.files[0]).then(result => Videobase64(result));
        e.preventDefault();
    });

    /**
     * Structured reference for videobase64.
     *
     * @param {*} result Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    function Videobase64(result) {
        $("#vidlink").val(result);
        $("#vidlink").hide();

        $("#divprevvid").show();

        // If base64, direct; else treat as stored file path
        if (result.includes("base64")) {
            $("#prevvideo").html('<source src="' + result + '" type="video/mp4"></source>');
        } else {
            $("#prevvideo").html('<source src="../../CanvasJS/Pages/' + result + '" type="video/mp4"></source>');
        }

        // UI toggles
        $('.addclickactn').show();
        $('#divupvid').hide();
        $("#uploadvid").val("");
        showLoadingWrapper(false);

        // Hide unrelated document upload section
        $("#divupdoc").hide();

        // Business hooks
        addClickAction();
        LoadTimeline();
    }


