    /* Modern slide-video event binding stamped 2026-04-23:
       replace the older duplicated paste/save handlers with one normalized flow
       while preserving the same slide model and canvas update behavior. */
    function renderSlideVideoPreview(rawValue, options) {
        var val = (rawValue || "").trim();
        var previewTitle = document.getElementById("sld-video-preview-title");
        var providerBadge = document.getElementById("sld-video-provider-badge");
        var settings = options || {};
        var isSavedVideo = typeof settings.isSavedVideo === "boolean"
            ? settings.isSavedVideo
            : currentSlideHasEmbeddedVideo();

        if (!val) {
            $("#sld-video-preview-inner").empty();
            $("#txtsldvideoembedlink").val("").removeData("normalizedIframe");

            if (previewTitle) {
                previewTitle.textContent = "Embed Preview";
            }

            if (providerBadge) {
                providerBadge.textContent = "Video";
            }

            setSlideVideoStatus("Ready for a YouTube/Vimeo link or iframe embed.", "");
            syncSlideVideoActionState("input", false);
            return;
        }

        var details = getVideoEmbedDetails(val);

        if (!details) {
            $("#sld-video-preview-inner").empty();
            $("#txtsldvideoembedlink").removeData("normalizedIframe");

            if (previewTitle) {
                previewTitle.textContent = "Embed Preview";
            }

            if (providerBadge) {
                providerBadge.textContent = "Video";
            }

            setSlideVideoStatus("Paste a valid YouTube/Vimeo link or iframe embed to continue.", "error");
            syncSlideVideoActionState("input", false);

            if (settings.showInvalidModal) {
                showInvalidIframeModal();
            }

            return;
        }

        $("#txtsldvideoembedlink").val(val).data("normalizedIframe", details.iframeHtml);
        $("#sld-video-preview-inner").html(details.iframeHtml);

        if (previewTitle) {
            previewTitle.textContent = details.provider + " Preview";
        }

        if (providerBadge) {
            providerBadge.textContent = details.provider;
        }

        if (isSavedVideo) {
            setSlideVideoStatus(details.provider + " video is added. Use Replace or Remove.", "ready");
            syncSlideVideoActionState("preview-saved", true);
            return;
        }

        setSlideVideoStatus(details.provider + " preview is ready. Use Add to save it.", "ready");
        syncSlideVideoActionState("preview-pending", false);
    }

