    /**
     * Initialize the slide HTML Summernote editor once so the modal offers the
     * same visual/code workflow expected from a full HTML editor.
     */
    function ensureHtmlContentEditorInitialized() {
        var $editor = $("#txtHtmlContent");
        if (!$editor.length || $editor.data("cgHtmlEditorReady")) {
            return $editor;
        }

        var editorHeight = Math.max(480, window.innerHeight - 250);

        $editor.summernote({
            placeholder: "Paste HTML markup here...",
            height: editorHeight,
            dialogsInBody: true,
            toolbar: [
                ["style", ["style"]],
                ["font", ["bold", "italic", "underline", "clear"]],
                ["para", ["ul", "ol", "paragraph"]],
                ["insert", ["link", "table", "hr"]],
                ["view", ["codeview"]]
            ],
            callbacks: {
                onChange: function (contents) {
                    if ($("#html-preview-panel").hasClass("active")) {
                        renderHtmlContentPreview(contents);
                    }
                }
            }
        });

        $editor.data("cgHtmlEditorReady", true);
        return $editor;
    }

    /**
     * Read the current HTML editor payload regardless of whether Summernote has
     * already been initialized for this modal session.
     * @returns {string} Current HTML editor contents.
     */
    function getHtmlContentEditorValue() {
        var $editor = $("#txtHtmlContent");
        if ($editor.data("cgHtmlEditorReady")) {
            return $editor.summernote("code");
        }

        return $editor.val() || "";
    }

    /**
     * Set the HTML editor payload while keeping both the Summernote instance and
     * the underlying textarea synchronized.
     * @param {string} htmlValue - HTML content to inject into the editor.
     */
    function setHtmlContentEditorValue(htmlValue) {
        var normalizedHtml = typeof htmlValue === "string" ? htmlValue : "";
        var $editor = ensureHtmlContentEditorInitialized();

        if ($editor.data("cgHtmlEditorReady")) {
            $editor.summernote("code", normalizedHtml);
        } else {
            $editor.val(normalizedHtml);
        }
    }

    /**
     * Render the HTML preview inside a sandboxed iframe so pasted markup can be
     * inspected safely before it is committed to slide JSON.
     * @param {string} rawHtml - Raw HTML content entered by the user.
     */
    function renderHtmlContentPreview(rawHtml) {
        var previewFrame = document.getElementById("htmlContentPreviewFrame");
        var previewStatus = document.getElementById("htmlPreviewStatus");
        var htmlValue = typeof rawHtml === "string" ? rawHtml : "";

        if (!previewFrame || !previewStatus) {
            return;
        }

        if (!htmlValue.trim()) {
            previewFrame.srcdoc = "<!doctype html><html><body style='margin:0;padding:24px;font-family:Segoe UI,Arial,sans-serif;color:#64748b;background:#f8fafc;'>Add HTML in Code View to preview it here.</body></html>";
            previewStatus.textContent = "Add HTML in Code View to preview it here.";
            return;
        }

        previewFrame.srcdoc = htmlValue;
        previewStatus.textContent = "Sandboxed preview of the current HTML content.";
    }

