    /** * Save Audio For Slide */
    // ==============================
    // 1) JS: generate GUID filename +  to .NET Core endpoint
    // ==============================   

    /**
     * Structured reference for upload slide audio to react.
     *
     * @param {*} payload Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    function uploadSlideAudioToReact(payload) {
        const requestId = crypto.randomUUID();

        window.parent.postMessage(
            {
                type: "UPLOAD_SLIDE_AUDIO",
                requestId,
                payload
            },
            window.location.origin
        );

        return new Promise((resolve, reject) => {
            /**
             * Structured reference for handler.
             *
             * @param {*} event Runtime parameter preserved from the source implementation.
             * @returns {*} Value and side effects preserved from the source implementation.
             */
            function handler(event) {
                if (event.origin !== window.location.origin) return;

                const msg = event.data;
                if (!msg || msg.requestId !== requestId) return;

                if (msg.type === "UPLOAD_SLIDE_AUDIO_SUCCESS") {
                    window.removeEventListener("message", handler);
                    resolve(msg.payload); // { url: '...' }
                }

                if (msg.type === "UPLOAD_SLIDE_AUDIO_ERROR") {
                    window.removeEventListener("message", handler);
                    reject(new Error(msg.error || "Upload failed"));
                }
            }
            window.addEventListener("message", handler);
        });
    }

    // Hook your Save button
    $("#saveaudio").on("click", async function (e) {
        e.preventDefault();
        e.stopPropagation();

        if (!slideAudioBase64) {
            alert("No audio to save");
            return;
        }

        // Open blocking loader modal
        $("#audioSavingModal").modal("show");

        var filename = generated_slides[slide_index].id;
        var extension = getAudioFileExtension(slideAudioMime);
        var fileName = filename + "." + extension;

        try {
            const result = await uploadSlideAudioToReact({
                fileName: fileName,
                mimeType: slideAudioMime,
                base64: slideAudioBase64
            });

            // Normalize slashes
            var audurl = result.replace(/\\/g, "/");
            generated_slides[slide_index].SlideAudio = audurl;
            refreshSlideMediaIndicators(generated_slides[slide_index].id);
            $("#getaud").attr("src", audurl);
            // Close loader modal
            $("#audioSavingModal").modal("hide");
            $("#audioStatusText").text("Audio saved");
            $("#divpaofl").show();
            $("#saveaudio").hide();
        } catch (err) {
            console.error(err);
            alert("Failed to save audio");
        } finally {
            // Close loader modal
            $("#audioSavingModal").modal("hide");
        }
    });


