    /* =============================================================================
       12) TIMELINE HELPER: Get previous audio end value
    ============================================================================= */

    /**
     * Take the end time of first previous Audio Ended By Double Click
     * - Reads start time from previous row
     * - Reads duration from previous row audio element
     * - Writes computed end-time into current label
     * - Updates load delay UI + triggers updateLoadActionWDLL
     */
    /**
     * Resolve the previous audio end value used for effect timing calculations.
     *
     * @param {*} sid Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    GetPrevAudEndValue = function (sid) {

        // previous object's start time (text)
        var audst = $("#" + sid).closest('div .divobjlst')
            .prev('div .divobjlst')
            .find(".UpdateEffstart")
            .text();

        // previous audio element id
        var audid = $("#" + sid).closest('div .divobjlst')
            .prev('div .divobjlst')
            .find("audio")
            .attr("id");

        // duration from audio element
        var audend = document.getElementById(audid).duration;

        // total = start + duration + 1 second buffer
        var TotalTime = parseFloat(audst) + parseInt(audend) + 1;

        // write to current label 
        $("#" + sid).html(TotalTime);

        // update load delay inputs based on active object id
        var selected_obj_id = canvas.getActiveObject().id;

        $('#load_delay').val($('#lbleffs_' + selected_obj_id + '').html());
        $("#load_delay_span").val($('#lbleffs_' + selected_obj_id + '').html());

        // derive objId from label name attribute
        var objId = $("#" + sid).attr("name").replace("lbleffs_", "");

        // show update button + set onclick
        $("#addloadactn").show();
        $('#addloadactn')
            .attr('onclick', 'updateLoadAction("' + selected_obj_id.id + '")')
            .html('Update');

        // your hook to persist/load timeline settings
        updateLoadActionWDLL(objId);
    };

    //Custom Select option list to get on hover effet ================================================================================
    /**
     * Rebuild the slide or control dropdown list from the latest editor state.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    updateDropdownList = function () {
        $('.scrollableList').remove();
        $('.makeMeList').each(function (index, element) {
            var CurrContrlID = $(this).attr("id");
            if ($(this).hasClass('hidden')) {
                $('.effectFromWrapper').hide();
            }
            $(this).parent()
                .after()
                .append("<div class='scrollableList'><div class='selectedOption'></div><ul></ul></div>");
            $(element).each(function (idx, elm) {
                $('option', elm).each(function (id, el) {
                    var fnMouseOver = ($(element).data('hover') == "1" && el.value) ? 'highlightObject(\'' + el.value + '\')' : '';
                    if (activeslide != el.value) {
                        if (el.text == "Slide 0") {
                            el.text = "Slide 1";
                        }
                        if (CurrContrlID == "sel_control") {
                            if (el.value.includes("textbox_") || el.value.includes("g_")) {
                                var id = el.value;
                                var obj = canvas.getObjectById(id);
                                if (obj != undefined) {
                                    $('.scrollableList ul:last').append('<li  id="li_' + el.value + '" data-value="' + el.value + '" onmouseover="' + fnMouseOver + '"><a id="a_' + el.value + '" style="color:#000 !important" onclick="Selamin(this.id)">' + el.text + '</a></li>');

                                }
                            }
                        } else {
                            $('.scrollableList ul:last').append('<li  id="li_' + el.value + '" data-value="' + el.value + '" onmouseover="' + fnMouseOver + '"><a id="a_' + el.value + '" style="color:#000 !important" onclick="Selamin(this.id)">' + el.text + '</a></li>');
                        }
                    }
                });
                $('.scrollableList ul').hide();

                $('.makeMeUl').children('div.selectedOption').text("Select");
            });
            $('.scrollableList:last').children('div.selectedOption').text("Select");
        });
        $('.selectedOption').on('click', function (e) {
            e.stopPropagation();
            $(this).next('ul').slideToggle(200);
            $('.selectedOption').not(this).next('ul').hide();
        });
        $('.scrollableList ul li').on('click', function (e) {
            e.stopPropagation();
            var selectedLI = $(this).text();
            var selectedLiId = $(this).data('value');
            $(this).parent().prev('.selectedOption').text(selectedLI);
            $("#ldactnprop").show();
            $(this).parent('ul').hide();
            $(this).closest('.scrollableList').prev('.makeMeList').val(selectedLiId);
            if (selectedLiId === 'slidein' || selectedLiId === 'slideout' || selectedLiId === 'chngtxt') {
                $('.effectFromWrapper').show();
                $(".effectFromWrapper").show();
            } else if ($(this).closest('.form-group').hasClass('effectFromWrapper')) {
                $('.effectFromWrapper').show();
            } else {
                $('.effectFromWrapper').hide();
                $(".effectFromWrapper").hide();
            }
        });
        $('.scrollableList').show();
        $('.makeMeList').hide();
        if ($(".selectedOption").html() == "Select") {
            $("#ldactnprop").hide();
            $('#addloadactn').hide();
        } else {
            $("#ldactnprop").show();
            $('#addloadactn').show();
        }
    };

