    //Add Sildes==================================================================================================================    
    /**
     * Create a new slide record, initialize its data, and update slide navigation UI.
     *
     * @param {*} canAdd Runtime parameter preserved from the source implementation.
     * @param {*} fromUndo Runtime parameter preserved from the source implementation.
     * @param {*} slideObj Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    addSlide = function (canAdd, fromUndo, slideObj) {
        clearSelectionForSlideNavigation();
        canvasmode = "add";
        SlideToadd = 0;
        $(".sldactn").hide();
        if (SlideToadd == 0) {
            var old_slide_id = selected_slide_id;
            //First save data for old slide.
            if (selected_slide_id !== "" && !fromUndo) {
                /* STAMP: 2026-08-21 - Capture the outgoing slide before the
                   canvas is cleared. Otherwise its original blank history
                   snapshot wins when the user returns from the new slide. */
                updateCanvasState();
                $('.slideThumbnail').removeClass('selected');
                generated_slides[slide_index].svg = encodeURIComponent(canvas.toSVG());
                generated_slides[slide_index].imgprev = canvas.toDataURL();
                generated_slides[slide_index].groups = slide_groups;
                generated_slides[slide_index].actions = slide_actions;
                generated_slides[slide_index].loadActions = slide_load_actions;
                generated_slides[slide_index].controls = slide_controls;
                generated_slides[slide_index].animationOnControls = animationOnControls;
                generated_slides[slide_index].action_list = clickActionList;
                generated_slides[slide_index].load_action_list = loadActionList;
                generated_slides[slide_index].jsonobj = canvas.toObject(['id']);
                generated_slides[slide_index].UniqueName = UniquepgeName;
                updateSlideThumbnail(selected_slide_id, canvas.toDataURL());
                //Save SVG for Slide
                generated_slides[slide_index].svg = encodeURIComponent(canvas.toSVG());
                generated_slides[slide_index].imgprev = canvas.toDataURL();
                /* Clearing for the new slide emits object:removed events. Do
                   not let those events append a blank snapshot to the slide
                   we just saved. This guard is synchronous and is released
                   immediately so normal undo/redo recording continues. */
                ruConfig.isRestoring = true;
                try {
                    canvas.clear();
                } finally {
                    ruConfig.isRestoring = false;
                }
            }
            slide_index = generated_slides.length;

            if (fromUndo) {
                selected_slide_id = slideObj.id;
                var slide_name = slideObj.name;
                generated_slides[slide_index] = slideObj;
            } else {
                all_controls = [];
                slide_controls = [];
                slide_actions = [];
                slide_load_actions = [];
                slide_groups = [];
                animationOnControls = [];
                //Generate data for new slide.
                selected_slide_id = generate_id("s_");
                slides_order++;
                slide_index = generated_slides.length;
                slide_counter++;
                var slide_name = "Slide " + slide_counter;
                clickActionList = '<h4 class="text-center">Actions</h4>';
                loadActionList = '<h4 class="text-center">Animations</h4>';
                $('.loadActionList').html(loadActionList);
                $('.clickActionList').html(clickActionList);
                var slide_svg = canvas.toSVG();
                var slide = {
                    order: slides_order,
                    id: selected_slide_id,
                    name: slide_name,
                    svg: slide_svg,
                    groups: "",
                    actions: "",
                    loadActions: "",
                    controls: slide_controls,
                    animationOnControls: "",
                    action_list: clickActionList,
                    load_action_list: loadActionList,
                    jsonobj: "",
                    UniquepgeName: UniqueID,
                    HTMlcontent: "",
                    ShowPaginate: 0,
                    ShowNavigate: getFlag(ShowNavigate, 1),
                    SlideTransition: "none",
                    UseTransitionOnBack: 0,
                    AutoNavigate: 0,
                    AutoNavigateSeconds: 3,
                    AutoNavigateOnMediaEnd: 0,
                    ArticulateContent: 0,
                    ArticulationScript: "",
                    ArticulationVoiceStyle: "female",
                    ArticulationVoiceURI: "",
                    ArticulationPitch: 1,
                    ArticulationRate: 1,
                    ArticulationProvider: "standard",
                    ElevenLabsVoiceId: "",
                    ElevenLabsModel: "eleven_multilingual_v2",
                    ElevenLabsStability: 0.5,
                    ElevenLabsSimilarity: 0.75,
                    AnimationSequence: [],
                };
                generated_slides[slide_index] = slide;
            }
            //Slide Data =============================================================        
            if (slide_index == '0') {

                var thumbnailStr = '<div class="' + selected_slide_id + ' sld nosort">';
                if ($("#ContentPlaceHolder1_hdntemptype").val() == "Animated Templates") {
                    $("#addslide").html("<div class='slideThumbnail  addSlide'>Slide Area</div>");
                    $(".generatedSlides").css("margin-left", "0px");
                    $("#divclanimupdown").hide();
                    $("#tdactions").hide();
                }
                thumbnailStr += buildSlideActionMenuHtml(selected_slide_id);
                thumbnailStr += '<div id=' + selected_slide_id + ' class="slideThumbnail  selected" onclick="changeSlide(\'' + selected_slide_id + '\', false, false, false)"></div>';
                thumbnailStr += '<div class="slideorder" id="sldord_' + slide_index + '"><p class="clsnav" id="psld_' + selected_slide_id + '" contenteditable="true" onkeyup="ChangeSLDOrderKU(this.id,' + slide_index + ')">Slide ' + (slide_index + 1) + '</p></div>';
                thumbnailStr += '</div>';
                $('.generatedSlides').append(thumbnailStr);
            } else {
                var thumbnailStr = '<div class="' + selected_slide_id + ' sld nosort">';
                thumbnailStr += buildSlideActionMenuHtml(selected_slide_id);
                thumbnailStr += '<div id=' + selected_slide_id + ' class="slideThumbnail  selected" onclick="changeSlide(\'' + selected_slide_id + '\', false, false, false)"></div>';
                thumbnailStr += '<div class="slideorder" id="sldord_' + slide_index + '"><p class="clsnav" id="psld_' + selected_slide_id + '" contenteditable="true" onkeyup="ChangeSLDOrderKU(this.id,' + slide_index + ')">Slide ' + (slide_index + 1) + '</p></div>';
                $('.generatedSlides').append(thumbnailStr);
                $("#divpaginationstatus").show();
            }
            updateSlideThumbnail(selected_slide_id, canvas.toDataURL());

            if (canvasmode == "add") {

                $('#sel_slide').append('<option value="' + selected_slide_id + '">' + slide_name + '</option>');

            }
            $('.sld').removeClass('highlight');
            $('.' + selected_slide_id).addClass('highlight');
            $('#sel_control').html('');
            activeslide = selected_slide_id;
            updateDropdownList();
            seedSlideHistory(selected_slide_id, getCanvasStateSnapshot());
            refreshUndoRedoButtons(selected_slide_id);
            $("#disableanimation").prop("checked", false).trigger("change");
            CurrentSlideNo = slide_index;
            SlideToadd++;
        }
        if (canAdd == 1) {
            total_slides++;
        }
        SetSlideValues();
    };

    //Clone Slide==============================================================================================================
    /**
     * Duplicate an existing slide including its serialized canvas content and metadata.
     *
     * @param {*} slide_id Runtime parameter preserved from the source implementation.
     * @param {*} e Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    duplicateSlide = function (slide_id, e) {
        /* STAMP: 2026-09-05 - Build clones without clearing/loading the live
           canvas or changing the active slide index. Normal navigation saves
           the source and performs the only asynchronous canvas load. */
        if (e) { e.preventDefault(); e.stopPropagation(); }
        if (ruConfig.isRestoring || !generated_slides.some(function (slide) { return slide.id === slide_id; })) return;
        /* STAMP: 2026-09-05 - Finish text editing and dissolve transient
           multi-selection before serialization, matching normal navigation.
           This preserves slide coordinates instead of selection-local ones. */
        clearSelectionForSlideNavigation();
        //Save SVG for Slide
        $(".sldactn").hide();
        generated_slides[slide_index].svg = encodeURIComponent(canvas.toSVG());
        generated_slides[slide_index].imgprev = canvas.toDataURL();
        generated_slides[slide_index].jsonobj = canvas.toObject(['id']);
        generated_slides[slide_index].UniquepgeName = UniqueID;
        generated_slides[slide_index].ShowPaginate = ShowPaginate;
        generated_slides[slide_index].ShowNavigate = ShowNavigate;
        generated_slides[slide_index].DisableAnimation = settings_DisableAnimation;
        generated_slides[slide_index].AllowZoom = AllowZoom;
        generated_slides[slide_index].HoverBackColor = HoverBackColor;
        generated_slides[slide_index].HoverBackStrokeColor = HoverBackStrokeColor
        generated_slides[slide_index].HoverBackStrokeWidth = HoverBackStrokeWidth
        generated_slides[slide_index].HoverTextColor = HoverTextColor
        generated_slides[slide_index].HoverTransparency = HoverTransparency;
        generated_slides[slide_index].ActiveBackColor = ActiveBackColor;
        generated_slides[slide_index].ActiveBackStrokeColor = ActiveBackStrokeColor
        generated_slides[slide_index].ActiveBackStrokeWidth = ActiveBackStrokeWidth
        generated_slides[slide_index].ActiveTextColor = ActiveTextColor;
        generated_slides[slide_index].ActiveTransparency = ActiveTransparency;
        generated_slides[slide_index].InActiveTransparency = InActiveTransparency;
        generated_slides[slide_index].ButtonTitlt = ButtonTitlt;
        generated_slides[slide_index].groups = slide_groups;
        generated_slides[slide_index].actions = slide_actions;
        generated_slides[slide_index].loadActions = slide_load_actions;
        generated_slides[slide_index].controls = slide_controls;
        generated_slides[slide_index].animationOnControls = animationOnControls;
        generated_slides[slide_index].action_list = clickActionList;
        generated_slides[slide_index].load_action_list = loadActionList;
        var duplicate_slide_index = generated_slides.findIndex(x => x.id === slide_id);
        var sourceSlide = generated_slides[duplicate_slide_index];
        var canvas_json = sourceSlide.jsonobj;
        var cloneControls = [];
        var cloneGroups = [];
        var cloneObjectIdMap = {};
        function pushCloneControl(id, type) {
            cloneControls.push({ id: id, ctrl_name: type.charAt(0).toUpperCase() + type.slice(1) });
        }
        var canvas_json_clone = JSON.parse(JSON.stringify(canvas_json));
        function remapSerializedCloneObject(obj) {
            if (!obj) return;
            var previousId = obj.id;
            obj.id = generate_id(getObjectIdPrefix(obj.type));
            if (previousId) cloneObjectIdMap[previousId] = obj.id;
            var children = Array.isArray(obj.objects) ? obj.objects : [];
            children.forEach(remapSerializedCloneObject);
            if (String(obj.type).toLowerCase() === "group") {
                cloneGroups.push({
                    groupId: obj.id,
                    ObjectArray: children.map(function (child) { return child.id; })
                });
            }
            pushCloneControl(obj.id, obj.type || "object");
        }
        (canvas_json_clone.objects || []).forEach(remapSerializedCloneObject);
        var temp_slide_id = generate_id("s_");
        slides_order++;
        var cloneIndex = generated_slides.length;
        var slide_name = "Slide " + (cloneIndex + 1);
        var cloneActionList = remapTransferText(sourceSlide.action_list || '<h4 class="text-center">Effects</h4>', cloneObjectIdMap);
        var cloneLoadActionList = remapTransferText(sourceSlide.load_action_list || '<h4 class="text-center">Actions</h4>', cloneObjectIdMap);
        var slide = {
            order: slides_order,
            id: temp_slide_id,
            name: slide_name,
            svg: "",
            groups: cloneGroups,
            actions: [],
            loadActions: [],
            controls: cloneControls,
            animationOnControls: [],
            action_list: cloneActionList,
            load_action_list: cloneLoadActionList,
            jsonobj: canvas_json_clone,
            HTMlcontent: "",
            ShowPaginate: getFlag(generated_slides[duplicate_slide_index].ShowPaginate, 0),
            ShowNavigate: getFlag(generated_slides[duplicate_slide_index].ShowNavigate, 1),
            SlideTransition: normalizeSlideTransition(generated_slides[duplicate_slide_index].SlideTransition),
            UseTransitionOnBack: getFlag(generated_slides[duplicate_slide_index].UseTransitionOnBack, 0),
            AutoNavigate: getFlag(generated_slides[duplicate_slide_index].AutoNavigate, 0),
            AutoNavigateSeconds: Math.max(1, Math.min(3600, Math.round(Number(generated_slides[duplicate_slide_index].AutoNavigateSeconds) || 3))),
            AutoNavigateOnMediaEnd: getFlag(generated_slides[duplicate_slide_index].AutoNavigateOnMediaEnd, 0),
            ArticulateContent: getFlag(generated_slides[duplicate_slide_index].ArticulateContent, 0),
            ArticulationScript: generated_slides[duplicate_slide_index].ArticulationScript || "",
            ArticulationVoiceStyle: generated_slides[duplicate_slide_index].ArticulationVoiceStyle || "female",
            ArticulationVoiceURI: generated_slides[duplicate_slide_index].ArticulationVoiceURI || "",
            ArticulationPitch: Number(generated_slides[duplicate_slide_index].ArticulationPitch) || 1,
            ArticulationRate: Number(generated_slides[duplicate_slide_index].ArticulationRate) || 1,
            ArticulationProvider: generated_slides[duplicate_slide_index].ArticulationProvider || "standard",
            ElevenLabsVoiceId: generated_slides[duplicate_slide_index].ElevenLabsVoiceId || "",
            ElevenLabsModel: generated_slides[duplicate_slide_index].ElevenLabsModel || "eleven_multilingual_v2",
            ElevenLabsStability: Number(generated_slides[duplicate_slide_index].ElevenLabsStability) || 0.5,
            ElevenLabsSimilarity: Number(generated_slides[duplicate_slide_index].ElevenLabsSimilarity) || 0.75,
            AnimationSequence: []
        };
        applyObjectAutomation(
            slide,
            captureObjectAutomation(sourceSlide, Object.keys(cloneObjectIdMap), true),
            cloneObjectIdMap,
            false,
            false
        );
        generated_slides[cloneIndex] = slide;
        seedSlideHistory(temp_slide_id, canvas_json_clone);
        var thumbnailStr = '<div class="' + temp_slide_id + ' sld nosort">';
        thumbnailStr += buildSlideActionMenuHtml(temp_slide_id);
        thumbnailStr += '<div id=' + temp_slide_id + ' class="slideThumbnail " onclick="changeSlide(\'' + temp_slide_id + '\', false, false, false)"></div>';
        thumbnailStr += '<div class="slideorder" id="sldord_' + cloneIndex + '"><p class="clsnav" id="psld_' + temp_slide_id + '" contenteditable="true" onkeyup="ChangeSLDOrderKU(this.id,' + cloneIndex + ')">Slide ' + (cloneIndex + 1) + '</p></div><p class="clsname" id="p_' + temp_slide_id + '" contenteditable="true" onkeyup="ChangeSDV(this.id)">' + slide_name + '</p></div>';

        $('.generatedSlides').append(thumbnailStr);
        changeSlide(temp_slide_id, false, false, false);

        $('#sel_slide').append('<option value="' + temp_slide_id + '">' + slide_name + '</option>');
        activeslide = temp_slide_id;
        updateDropdownList();
        $("#divpaginationstatus").show();
        CurrentSlideNo = slide_index;

        total_slides++;
        SetSlideValues();
    };

    // Push Control to JS and Dropdown ================================================================================
    /**
     * Add a control definition to the current slide control collection.
     *
     * @param {*} id Runtime parameter preserved from the source implementation.
     * @param {*} ctrl_name Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    pushControl = function (id, ctrl_name) {
        ctrl_name = ctrl_name.substr(0, 1).toUpperCase() + ctrl_name.substr(1);
        var temp_obj = {
            id: id,
            ctrl_name: ctrl_name
        };
        slide_controls.push(temp_obj); // to manage controls directly without iterating Slides loop
        all_controls.push(temp_obj);

        generated_slides[slide_index].controls = slide_controls; //keeping Slides updated with all loops

        var tmp_option = '<option value="' + id + '">' + ctrl_name + '</option>';
        $('#sel_control').append(tmp_option);

        updateDropdownList();
    };

    //Pop Control to JS and Dropdown ================================================================================
    /**
     * Remove a control definition from the current slide control collection.
     *
     * @param {*} tid Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    popControl = function (tid) {
        if (slide_controls != "") {
            slide_controls = slide_controls.filter(obj => obj.id !== tid);
            generated_slides[slide_index].controls = slide_controls;
        }
        if (slide_groups != "") {
            slide_groups = slide_groups.filter(obj => obj.groupId !== tid);
            generated_slides[slide_index].groups = slide_groups;
        }
        if (slide_load_actions != "") {
            slide_load_actions = slide_load_actions.filter(obj => obj.actionOn !== tid);
            generated_slides[slide_index].loadActions = slide_load_actions;
        }
        if (slide_actions != "") {
            slide_actions = slide_actions.filter(obj => obj.actionFrom !== tid || obj.actionTo !== tid);
            generated_slides[slide_index].actions = slide_actions;
        }
        if (animationOnControls != "") {
            animationOnControls = animationOnControls.filter(obj => obj.id !== tid);
            generated_slides[slide_index].animationOnControls = animationOnControls;
        }

        $('#sel_control option[value="' + tid + '"]').remove();
        //Delete Object from Object List
        $('#div_' + tid).remove();
        updateDropdownList();
        deleteActionFromListByObjId(tid);
    };

