    //Reset Load animation
    /**
     * Reset the load animation form and timeline selection state.
     *
     * @param {*} slide_load_actions Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    resetLoadAnimation = function (slide_load_actions) {
        var objId = canvas.getActiveObject().get('id');
        $.each(slide_load_actions, function (key, val) {
            if (val.actionOn === objId && val.loadAnimType === $('#sel_load_efftype').val()) {
                $(loadAnimTypeClass + '#sel_load_effect').val(val.effect);
                $(loadAnimTypeClass + '#sel_load_effect').next('.scrollableList').find('ul li[data-value="' + val.effect + '"]').click();
                $('#load_delay').val(val.delay);
                $("#load_delay_span").html(val.delay);
                $(loadAnimTypeClass + '#sel_load_effect').closest('.panel-body').find('button').attr('onclick', 'updateLoadAction("' + val.id + '")').html('Update Load Action');
                return false;
            } else {
                $(loadAnimTypeClass + '#sel_load_effect').val('fadein');
                $(loadAnimTypeClass + '#sel_load_effect').next('.scrollableList').find('ul li[data-value="fadein"]').click();
                $('#load_delay').val(0);
                $("#load_delay_span").html(0);
                $(loadAnimTypeClass + '#sel_load_effect').closest('.panel-body').find('button').attr('onclick', 'addLoadAction()').html('Add Load Action');
            }
        });

    };

    //Chnage Effect Type from Entry to exit and Visa Versa
    $('#sel_load_efftype').on('change', function () {
        if (this.value === 'entryLoadAnim') {
            loadAnimTypeClass = '.entryLoadAnim';
            $('#diventry').show();
            $('#divexit').hide();
            $('#divaudio').hide();
        } if (this.value === 'exitLoadAnim') {
            loadAnimTypeClass = '.exitLoadAnim';
            $('#diventry').hide();
            $('#divexit').show();
            $('#divaudio').hide();
        }

        if (this.value === 'audioAnim') {
            loadAnimTypeClass = '.auoioanim';
            $('#diventry').hide();
            $('#divexit').hide();
            $('#divaudio').show();
        }
        updateDropdownList();
        resetLoadAnimation(slide_load_actions);
    });

