                var action_on_obj_id, effect, params, coords, url, Audio_on_obj_id, Heading, Descr, DescrAud;
                var event = 'click';
                if (clickAction === 'Hyperlink') {
                    effect = clickAction;
                    clickAction = 'Hyperlink';
                    action_on_obj_id = $('#Hyperlink').val();
                    url = action_on_obj_id;
                    params = null;
                    coords = null;
                }
                else if (clickAction === 'toc') {
                    effect = clickAction;
                    clickAction = 'TOC';
                    params = null;
                    coords = null;
                }
