    //Update Animation from Animation Property Bar=============================================================================
    /**
     * Load a selected object animation into the editing form.
     *
     * @param {*} anim_id Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    editselobjanim = function (anim_id) {
        var Effect = $("#eff-" + anim_id.replace("dl-", "").replace("dur-", "") + "").html();
        var Delay = $("#dl-" + anim_id.replace("dl-", "").replace("dur-", "") + "").val();
        var Duration = $("#dur-" + anim_id.replace("dl-", "").replace("dur-", "") + "").val();
        $('#load_delay').val(Delay);
        $('#dur_delay').val(Duration);
        $('#addloadactn').click();
    };

    //UPDATE OBJECT PARAMETERS ================================================================================
    /**
     * Sync animation parameter inputs with the currently selected object.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    updateParamsOfObjectToAnimate = function () {
        var obj = canvas.getActiveObject();
        if (obj == null) return;
        var obj_id = obj.id;
        if (animationOnControls.some(anim => anim.id === obj_id)) {
            var click_actions = generated_slides[slide_index].actions;
            var load_actions = generated_slides[slide_index].loadActions;
            var clickIndex, loadIndex;
            if (click_actions) {
                clickIndex = click_actions.findIndex(x => x.actionTo === obj_id);
            }
            if (load_actions) {
                loadIndex = load_actions.findIndex(x => x.actionOn === obj_id);
            }
            if (clickIndex >= 0 || loadIndex >= 0) {
                var cp = obj.getCenterPoint();
                var elemTag = obj.get('type');
                var width, height;
                if (elemTag === 'circle') {
                    width = obj.getRadiusX();
                    height = obj.getRadiusY();
                } else {
                    width = obj.getScaledWidth();
                    height = obj.getScaledHeight();
                }
                var coords = {
                    left: obj.left,
                    right: obj.left + width,
                    top: obj.top,
                    bottom: obj.top + width
                };
                if (clickIndex >= 0) {
                    generated_slides[slide_index].actions[clickIndex].params.cp = cp;
                    generated_slides[slide_index].actions[clickIndex].params.width = width;
                    generated_slides[slide_index].actions[clickIndex].params.height = height;
                    generated_slides[slide_index].actions[clickIndex].params.coords = coords;
                    generated_slides[slide_index].actions[clickIndex].coords = coords;
                }
                if (loadIndex >= 0) {
                    generated_slides[slide_index].loadActions[loadIndex].params.cp = cp;
                    generated_slides[slide_index].loadActions[loadIndex].params.width = width;
                    generated_slides[slide_index].loadActions[loadIndex].params.height = height;
                    generated_slides[slide_index].loadActions[loadIndex].params.coords = coords;
                }
            }
        }
    };

    //Group Align ======================================================================================
    /**
     * Align child objects inside the active group using the requested direction.
     *
     * @param {*} direction Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    groupAlign = function (direction) {
        var group = canvas.getActiveObject();
        if (group.type === 'activeSelection') {
            var groupWidth = group.getBoundingRect(true).width, groupHeight = group.getBoundingRect(true).height, scaleFactor = group.scaleX;
            group.forEachObject(function (obj) {
                var itemWidth = obj.getBoundingRect().width * scaleFactor;
                var itemHeight = obj.getBoundingRect().height * scaleFactor;
                switch (direction) {
                    case 'left':
                        if ($("#chkaligncanvas").is(':checked')) {
                            obj.set({
                                left: -(groupWidth / 2),
                                originX: 'left'
                            });
                            var activeObj = canvas.getActiveObject();
                            if (activeObj) {
                                activeObj.set({
                                    left: 0
                                });
                                activeObj.setCoords();
                                canvas.renderAll();
                            } else {
                                alert('Please select a item');
                                return false;
                            }
                        } else {
                            obj.set({
                                left: -(groupWidth / 2),
                                originX: 'left'
                            });
                        }
                        break;
                    case 'center':
                        if ($("#chkaligncanvas").is(':checked')) {
                            obj.set({
                                left: (0 - itemWidth / 2),
                                originX: 'left'
                            });
                            var activeObj = canvas.getActiveObject();
                            if (activeObj) {
                                activeObj.set({
                                    left: (canvas.width / 2) - ((activeObj.width * activeObj.scaleX) / 2)
                                });
                                activeObj.setCoords();
                                canvas.renderAll();
                            } else {
                                alert('Please select a item');
                                return false;
                            }
                        } else {
                            obj.set({
                                left: (0 - itemWidth / 2),
                                originX: 'left'
                            });
                        }
                        break;
                    case 'right':
                        if ($("#chkaligncanvas").is(':checked')) {
                            obj.set({
                                left: (groupWidth / 2 - itemWidth / 2),
                                originX: 'center'
                            });
                            var activeObj = canvas.getActiveObject();
                            if (activeObj) {
                                activeObj.set({
                                    left: canvas.width - (activeObj.width * activeObj.scaleX)
                                });
                                activeObj.setCoords();
                                canvas.renderAll();
                            } else {
                                alert('Please select a item');
                                return false;
                            }
                        } else {
                            obj.set({
                                left: (groupWidth / 2 - itemWidth / 2),
                                originX: 'center'
                            });
                        }
                        break;
                    case 'top':
                        if ($("#chkaligncanvas").is(':checked')) {
                            obj.set({
                                top: -(groupHeight / 2),
                                originX: 'left'
                            });
                            var activeObj = canvas.getActiveObject();
                            if (activeObj) {
                                activeObj.set({
                                    top: 0
                                });
                                activeObj.setCoords();
                                canvas.renderAll();
                            } else {
                                alert('Please select a item');
                                return false;
                            }
                        } else {
                            obj.set({
                                top: -(groupHeight / 2),
                                originX: 'left'
                            });
                        }
                        break;
                    case 'middle':
                        if ($("#chkaligncanvas").is(':checked')) {
                            obj.set({
                                top: (0 - itemHeight / 2),
                                originX: 'left'
                            });
                            var activeObj = canvas.getActiveObject();
                            if (activeObj) {
                                activeObj.set({
                                    top: (canvas.height / 2) - ((activeObj.height * activeObj.scaleY) / 2)
                                });
                                activeObj.setCoords();
                                canvas.renderAll();
                            } else {
                                alert('Please select a item');
                                return false;
                            }
                        } else {
                            obj.set({
                                top: (0 - itemHeight / 2),
                                originX: 'left'
                            });
                        }
                        break;
                    case 'bottom':
                        if ($("#chkaligncanvas").is(':checked')) {
                            obj.set({
                                top: (groupHeight / 2 - itemHeight),
                                originX: 'left'
                            });
                            var activeObj = canvas.getActiveObject();
                            if (activeObj) {
                                activeObj.set({
                                    top: canvas.height - (activeObj.height * activeObj.scaleY)
                                });
                                activeObj.setCoords();
                                canvas.renderAll();
                            } else {
                                alert('Please select a item');
                                return false;
                            }
                        } else {
                            obj.set({
                                top: (groupHeight / 2 - itemHeight),
                                originX: 'left'
                            });
                        }
                        break;
                    case 'height':
                        if (tempidsel != obj.id) {
                            obj.set({ height: 0 });
                            obj.set({ height: tempheight });
                        }
                        break;
                    case 'width':
                        if (tempidsel != obj.id) {
                            obj.set({ width: 0 });
                            obj.set({ width: tempwidth });
                        }
                        break;
                    case 'both':
                        if (tempidsel != obj.id) {
                            obj.set({ width: 0 });
                            obj.set({ height: tempheight });
                            obj.set({ width: tempwidth });
                        }
                        break;
                }
            });
            group.setObjectsCoords();
            group.setCoords();
            //}
            canvas.renderAll();
            updateCanvasState();
        }
    };

