        generated_slides[slide_index].loadActions = slide_load_actions;
        animationOnControls = animationOnControls.filter(obj => obj.id !== animationOnId);
        generated_slides[slide_index].animationOnControls = animationOnControls;
        $(item).closest('.singleAction').remove();
        loadActionList = $('.loadActionList').html();
        clickActionList = $('.clickActionList').html();
        generated_slides[slide_index].action_list = clickActionList;
        generated_slides[slide_index].load_action_list = loadActionList;

