    //Distribute Objects Equally ===================================================================================
    /**
     * Structured reference for get new view dimensions.
     *
     * @param {*} group Runtime parameter preserved from the source implementation.
     * @param {*} val Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    function getNewViewDimensions(group, val) {
        var objects = canvas.getActiveObject()._objects, minWidth = 0, minHeight = 0, w, h;
        switch (val) {
            case 'vertical':
                for (i = 0; i < objects.length; i++) {
                    minWidth += objects[i].width * objects[i].scaleX;
                    h = objects[i].height * objects[i].scaleY;
                    if (h > minHeight) {
                        minHeight = h;
                    }
                }
                break;
            case 'horizontal':
                for (var i = 0; i < objects.length; i++) {
                    minHeight += objects[i].height * objects[i].scaleY;
                    w = objects[i].width * objects[i].scaleX;
                    if (w > minWidth) {
                        minWidth = w;
                    }
                }
                break;
        }
        return {
            width: minWidth,
            height: minHeight
        }
    }

    //SHOW MESSAGE BOX ==============================================================================================
    /**
     * Display the inline alert box used for editor feedback messages.
     *
     * @param {*} message Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    showAlertBox = function (message) {
        $("#alertMsg").fadeIn(30);
        if (message != "") {
            $('#alertMsg').html(message);
        }
        $("#alertMsg").removeClass("display-hide");
        $("#alertMsg").fadeOut(5000);
    };

    /* STAMP: 2026-09-11 - Compact 24px SVG cursor replaces the oversized
     * legacy brush presentation. The hotspot sits on the brush tip so the
     * object beneath the tip receives the formatting. */
    var formatPainterCursor = 'url("data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 width=%2224%22 height=%2224%22 viewBox=%220 0 24 24%22%3E%3Crect x=%221%22 y=%221%22 width=%2222%22 height=%2222%22 rx=%226%22 fill=%22%23172536%22 stroke=%22%23ffffff%22 stroke-opacity=%22.9%22/%3E%3Cpath d=%22M6.2 17.8c1.2-.1 2.1-.5 2.7-1.2.5-.6.6-1.3.4-2l-2.4-2.4c-.7-.2-1.4-.1-2 .4-.7.6-1.1 1.5-1.2 2.7-.1 1.1-.5 1.8-1.1 2.4 1.1.3 2.4.4 3.6.1Z%22 fill=%22%2365b8ff%22/%3E%3Cpath d=%22m8.1 13.9-3-3L13.8 3a1.8 1.8 0 0 1 2.5.1l1.8 1.8a1.8 1.8 0 0 1 .1 2.5l-7.9 8.7Z%22 fill=%22%23ffffff%22/%3E%3Cpath d=%22m12.7 5.3 3 3%22 stroke=%22%2365b8ff%22 stroke-width=%221.5%22 stroke-linecap=%22round%22/%3E%3C/svg%3E") 5 18, crosshair';

    function resetFormatPainterState() {
        IsFormatPaint = 0;
        formatpaintid = "";
        canvas.hoverCursor = 'move';
        $(".formatpaint").show();
        window.dispatchEvent(new window.CustomEvent("cg:format-painter-changed", {
            detail: { active: false, sourceId: "" }
        }));
    }

    function isFormatPainterTextObject(obj) {
        var type = String(obj && obj.type || "").toLowerCase();
        return type === "text" || type === "textbox" || type === "i-text";
    }

    function isFormatPainterShapeObject(obj) {
        return ["rect", "circle", "triangle", "line", "polygon", "polyline", "ellipse", "path"]
            .indexOf(String(obj && obj.type || "").toLowerCase()) >= 0;
    }

    function areFormatPainterTargetsCompatible(sourceObj, targetObj) {
        if (!sourceObj || !targetObj || sourceObj.id == targetObj.id) {
            return false;
        }

        if (sourceObj.type == "group" || targetObj.type == "group") {
            return sourceObj.type == "group" && targetObj.type == "group";
        }

        if (isFormatPainterTextObject(sourceObj) && isFormatPainterTextObject(targetObj)) {
            return true;
        }

        if (isFormatPainterShapeObject(sourceObj) && isFormatPainterShapeObject(targetObj)) {
            return true;
        }

        return sourceObj.type == targetObj.type;
    }

    function buildFormatPainterProps(sourceObj) {
        var baseProps = {
            fill: sourceObj.fill,
            stroke: sourceObj.stroke,
            strokeWidth: sourceObj.strokeWidth,
            strokeDashArray: sourceObj.strokeDashArray ? sourceObj.strokeDashArray.concat() : sourceObj.strokeDashArray,
            strokeLineCap: sourceObj.strokeLineCap,
            strokeLineJoin: sourceObj.strokeLineJoin,
            strokeMiterLimit: sourceObj.strokeMiterLimit,
            opacity: sourceObj.opacity,
            shadow: sourceObj.shadow && typeof sourceObj.shadow.toObject === "function"
                ? new fabric.Shadow(sourceObj.shadow.toObject())
                : sourceObj.shadow,
            backgroundColor: sourceObj.backgroundColor,
            globalCompositeOperation: sourceObj.globalCompositeOperation
        };

        if (isFormatPainterTextObject(sourceObj)) {
            baseProps.fontFamily = sourceObj.fontFamily;
            baseProps.fontSize = sourceObj.fontSize;
            baseProps.fontWeight = sourceObj.fontWeight;
            baseProps.fontStyle = sourceObj.fontStyle;
            baseProps.textDecoration = sourceObj.textDecoration;
            baseProps.textAlign = sourceObj.textAlign;
            baseProps.lineHeight = sourceObj.lineHeight;
            baseProps.charSpacing = sourceObj.charSpacing;
            baseProps.textBackgroundColor = sourceObj.textBackgroundColor;
            baseProps.typingEffect = sourceObj.typingEffect;
            baseProps.typingSpeed = sourceObj.typingSpeed;
            baseProps.underline = sourceObj.underline;
            baseProps.fontVariant = sourceObj.fontVariant;
            baseProps.fontStretch = sourceObj.fontStretch;
            baseProps.direction = sourceObj.direction;
        }

        return baseProps;
    }

    function validateFormatPainterGroup(sourceGroup, targetGroup) {
        if (!sourceGroup || !targetGroup || !sourceGroup._objects || !targetGroup._objects) {
            return {
                valid: false,
                message: "Format painter could not read the selected groups."
            };
        }

        if (sourceGroup._objects.length != targetGroup._objects.length) {
            return {
                valid: false,
                message: "Format painter can only be applied to groups with the same structure."
            };
        }

        for (var i = 0; i < sourceGroup._objects.length; i++) {
            if (!areFormatPainterTargetsCompatible(sourceGroup._objects[i], targetGroup._objects[i])) {
                return {
                    valid: false,
                    message: "Format painter can only be applied to matching group items."
                };
            }
        }

        return { valid: true };
    }

    function applyFormatPainterToObject(sourceObj, targetObj) {
        var props = buildFormatPainterProps(sourceObj);
        targetObj.set(props);

        if (isFormatPainterTextObject(targetObj)) {
            /* STAMP: 2026-09-11 - Existing character overrides must not mask
             * the source object's painted typography on the target content. */
            var textProps = {
                fill: props.fill,
                stroke: props.stroke,
                strokeWidth: props.strokeWidth,
                fontFamily: props.fontFamily,
                fontSize: props.fontSize,
                fontWeight: props.fontWeight,
                fontStyle: props.fontStyle,
                underline: props.underline,
                textBackgroundColor: props.textBackgroundColor
            };
            if (typeof targetObj.setSelectionStyles === "function" && typeof targetObj.text === "string") {
                targetObj.setSelectionStyles(textProps, 0, targetObj.text.length);
            }
            targetObj.initDimensions();
        }
        targetObj.dirty = true;
        targetObj.setCoords();
    }

    function applyFormatPainterToGroup(sourceGroup, targetGroup) {
        for (var i = 0; i < sourceGroup._objects.length; i++) {
            var sourceChild = sourceGroup._objects[i];
            var targetChild = targetGroup._objects[i];
            if (!sourceChild || !targetChild) {
                continue;
            }

            if (sourceChild.type == "group" && targetChild.type == "group") {
                applyFormatPainterToGroup(sourceChild, targetChild);
            } else {
                applyFormatPainterToObject(sourceChild, targetChild);
            }
        }

        targetGroup.setCoords();
    }

    function tryApplyFormatPainter(targetObj) {
        if (IsFormatPaint != 1 || !formatpaintid || !targetObj) {
            return false;
        }

        var sourceObj = canvas.getObjectById(formatpaintid);
        if (!sourceObj) {
            resetFormatPainterState();
            showAlertBox("Format painter source object was not found.");
            return false;
        }

        var isMultipleSelection = String(targetObj.type || "").toLowerCase() === "activeselection";
        if (!isMultipleSelection && sourceObj.id == targetObj.id) {
            return false;
        }

        /* STAMP: 2026-09-11 - An armed painter may be consumed by a multiple
         * selection. Paint every compatible member and leave other kinds
         * unchanged; the source itself is naturally excluded by compatibility. */
        var targets = isMultipleSelection
            ? (targetObj._objects || []).filter(function (item) {
                return areFormatPainterTargetsCompatible(sourceObj, item);
            })
            : [targetObj];
        if (!targets.length || (!isMultipleSelection && !areFormatPainterTargetsCompatible(sourceObj, targetObj))) {
            showAlertBox("Choose a matching object type for format painter.");
            return false;
        }

        var paintedCount = 0;
        var validationMessage = "";
        targets.forEach(function (target) {
            if (sourceObj.type == "group") {
                var groupValidation = validateFormatPainterGroup(sourceObj, target);
                if (!groupValidation.valid) {
                    validationMessage = groupValidation.message;
                    return;
                }
                applyFormatPainterToGroup(sourceObj, target);
            } else {
                applyFormatPainterToObject(sourceObj, target);
            }
            paintedCount++;
        });
        if (!paintedCount) {
            showAlertBox(validationMessage || "Choose a matching object type for format painter.");
            return false;
        }
        if (isMultipleSelection) targetObj.setCoords();

        canvas.renderAll();
        updateCanvasState();
        if (selected_slide_id) {
            updateSlideThumbnail(selected_slide_id, canvas.toDataURL());
        }
        resetFormatPainterState();
        showAlertBox(paintedCount > 1 ? "Formatting applied to " + paintedCount + " objects." : "Formatting applied.");
        return true;
    }

    /**
     * STAMP: 2026-09-11 - Public one-shot Format Painter entry point used by
     * every individual-object Quick Action toolbar. Content, identity, actions,
     * automation, position, dimensions, and transforms remain target-owned.
     *
     * @param {fabric.Object} sourceObj Selected formatting source.
     * @returns {boolean} True when painter mode was armed.
     */
    window.CGStartFormatPainter = function (sourceObj) {
        if (!sourceObj || String(sourceObj.type || "").toLowerCase() === "activeselection") return false;
        formatpaintid = sourceObj.id;
        IsFormatPaint = 1;
        $(".formatpaint").hide();
        canvas.hoverCursor = formatPainterCursor;
        window.dispatchEvent(new window.CustomEvent("cg:format-painter-changed", {
            detail: { active: true, sourceId: sourceObj.id }
        }));
        showAlertBox("Format painter ready. Select a matching object to apply the copied style.");
        return true;
    };

    window.CGIsFormatPainterActive = function (sourceObj) {
        return IsFormatPaint == 1 && (!sourceObj || sourceObj.id == formatpaintid);
    };

    //HIGHLIGHT OR ANIMATE OBJECT ===================================================================================
    /**
     * Highlight the requested object in canvas and sidebar contexts.
     *
     * @param {*} id Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    highlightObject = function (id) {
        var obj = canvas.getObjectById(id);
        if (obj != undefined) {
            var objTop = obj.top;
            var objDown = obj.top + 10;
            obj.animate('top', objDown, {
                duration: 300,
                onChange: canvas.renderAll.bind(canvas)
            });

            setTimeout(function () {
                obj.animate('top', objTop, {
                    duration: 300,
                    onChange: canvas.renderAll.bind(canvas)
                });
            }, 200);

        }
    };

    //MAKE OBJECT ACTIVE =============================================================================================
    /**
     * Set the requested object as active and sync the sidebar selection state.
     *
     * @param {*} objId Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    makeObjectActive = function (objId) {
        $(".singleAction").hide();
        $('.loadActionList').find('.singleAction').each(function () {
            $(this).show();
        });
        canvas.getObjects().forEach(function (o) {
            if (o.id === objId) {

                canvas.setActiveObject(o);
            }
        });
        var activeObject = canvas.getActiveObject();
        //canvas.bringToFront(activeObject);
        canvas.requestRenderAll();
    };
    /**
     * Reveal and focus the requested object in the object navigation panel.
     *
     * @param {*} objId Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    showActiveobject = function (objId) {
        objId = objId.replace("SelectTargetObject_", "");
        var activeObject = canvas.getObjectById(objId);
        canvas.bringObjectToFront(activeObject);
    };

    //Manage Active State================================================================================================================
    $('#chktxtmode').on('switchChange.bootstrapSwitch', function (event, state) {
        var ao = canvas.getActiveObject();
        if (!ao) {
            event.preventDefault();
            event.stopPropagation();
            return false;
        } else {
            if (!state) {
                //change to active state        
                var ao_id = ao.get('id');
                var ao_hover_id = ao.get('id') + '_hover';
                let is_active_obj = slide_controls.find(o => o.id === ao_hover_id);
                var normalObj = canvas.getObjectById(ao_id);
                if (!is_active_obj) {
                    fnClone(normalObj, true);
                } else {
                    canvas.discardActiveObject();
                    var cloneObject = canvas.getObjectById(ao_hover_id);
                    canvas.setActiveObject(cloneObject);
                    cloneObject.opacity = 1;
                    canvas.bringObjectToFront(cloneObject);
                }
                normalObj.opacity = 0;
            } else {
                //change to normal
                var ao_hover_id = ao.get('id');
                var ao_id = ao_hover_id.replace('_hover', '');
                var cloneObject = canvas.getObjectById(ao_hover_id);
                cloneObject.opacity = 0;
                canvas.discardActiveObject();
                var nObj = canvas.getObjectById(ao_id);
                nObj.opacity = 1;
                canvas.setActiveObject(nObj);
                canvas.bringObjectToFront(nObj);
            }
            canvas.renderAll();
            //    active_obj.selectable = false;
        }
    });

