    //Show Hide Object ===============================================================================================    
    $(document).on("click", ".showhideobject", function () {
        var objId = $(this).attr("id").replace("showhideobject_", "");
        canvas.discardActiveObject();
        canvas.getObjects().forEach(function (o) {
            if (o.id === objId) {
                canvas.setActiveObject(o);
                var activeObject = canvas.getObjectById(o.id);
                var opacity = activeObject.visible;
                var selectable = activeObject.selectable;
                var active = activeObject.active;
                if (opacity == false) {
                    $("#ishobj_" + objId + "").removeClass("noshowicon");
                    $("#ishobj_" + objId + "").addClass("showicon");
                    activeObject.set({ visible: 1, selectable: true, active: true });

                } else {
                    $("#ishobj_" + objId + "").addClass("noshowicon");
                    $("#ishobj_" + objId + "").removeClass("showicon");
                    activeObject.set({ visible: 0, selectable: false, active: false });
                    canvas.discardActiveObject();
                }
            }
        });
        canvas.requestRenderAll();
        updateCanvasState();
        LoadTimeline();
    });

