    //Show Hide Object ===============================================================================================    
    $(document).on("click", ".lockobject", function () {
        var objId = $(this).attr("id").replace("lockobject_", "");
        canvas.discardActiveObject();
        canvas.getObjects().forEach(function (o) {
            if (o.id === objId) {
                canvas.setActiveObject(o);
                var activeObject = canvas.getActiveObject();
                var lock = activeObject.lockMovementX;
                if (lock == false) {
                    $("#ilckobj_" + objId + "").addClass("noshow");
                    var activeObject = canvas.getActiveObject();
                    var activeGroup = canvas.getActiveObjects();
                    if (activeObject) {
                        activeObject.lockMovementX = true;
                        activeObject.lockMovementY = true;
                        activeObject.lockScalingX = true;
                        activeObject.lockScalingY = true;
                        activeObject.lockRotation = true;
                        activeObject.editable = false;
                    }
                    if (activeGroup) {
                        for (i = 0; i < activeGroup.length; i++) {
                            canvas.item(i).lockMovementX = true;
                            canvas.item(i).lockMovementY = true;
                            canvas.item(i).lockScalingX = true;
                            canvas.item(i).lockScalingY = true;
                            canvas.item(i).lockRotation = true;
                            canvas.item(i).editable = false;
                        }
                    }

                } else {
                    $("#ilckobj_" + objId + "").removeClass("noshow");
                    var activeObject = canvas.getActiveObject();
                    var activeGroup = canvas.getActiveObjects();
                    if (activeObject) {
                        activeObject.lockMovementX = false;
                        activeObject.lockMovementY = false;
                        activeObject.lockScalingX = false;
                        activeObject.lockScalingY = false;
                        activeObject.lockRotation = false;
                        activeObject.editable = true;
                    }
                    if (activeGroup) {
                        for (i = 0; i < activeGroup.length; i++) {
                            canvas.item(i).lockMovementX = false;
                            canvas.item(i).lockMovementY = false;
                            canvas.item(i).lockScalingX = false;
                            canvas.item(i).lockScalingY = false;
                            canvas.item(i).lockRotation = false;
                            canvas.item(i).editable = true;
                        }
                    }
                }
            }
        });
        canvas.requestRenderAll();
        updateCanvasState();
        LoadTimeline();
    });

