    var syncObjectListSortable = function () {
        var $list = $("#divobjlistList");

        if (!$list.length || !$.fn.sortable) {
            return;
        }

        if ($list.hasClass("ui-sortable")) {
            try {
                $list.sortable("destroy");
            } catch (sortErr) {
                console.warn("Object list sortable destroy skipped.", sortErr);
            }
        }

        $list.sortable({
            items: "> .divobjlst",
            handle: ".objdraghandle",
            cancel: ".chkobjsel, .lstobjname, .showsel, .ShareProp, .formatpaint, .showhideobject, .cloneobjectmenu, .DeleteObject, .SelectTargetObject, .SelectTargetObjecthide, .removetmeff, .remactn, .efftimeline, .upaudlst, input, textarea, button, audio",
            distance: 8,
            tolerance: "pointer",
            placeholder: "divobjlst-sort-placeholder",
            start: function (event, ui) {
                objectListDragStartIndex = ui.item.index();
                objectListDragObjectId = ui.item.attr("data-object-id") || ui.item.attr("id").replace("div_", "");
                ui.placeholder.height(ui.item.outerHeight());
            },
            stop: function (event, ui) {
                var dropIndex = ui.item.index();
                var draggedObjectId = objectListDragObjectId || ui.item.attr("data-object-id") || ui.item.attr("id").replace("div_", "");

                if (objectListDragStartIndex === null || dropIndex === objectListDragStartIndex) {
                    objectListDragStartIndex = null;
                    objectListDragObjectId = "";
                    return;
                }

                objectListDragStartIndex = null;
                objectListDragObjectId = "";
                reorderCanvasObjectByListIndex(draggedObjectId, dropIndex);
            }
        }).disableSelection();
    };

    var reorderCanvasObjectByListIndex = function (objectId, targetIndex) {
        if (!canvas || typeof canvas.getObjectById !== "function") {
            return;
        }

        var targetObject = canvas.getObjectById(objectId);
        var canvasObjects = canvas.getObjects ? canvas.getObjects() : canvas._objects;

        if (!targetObject || !canvasObjects || targetIndex < 0 || targetIndex >= canvasObjects.length) {
            return;
        }

        var currentIndex = canvasObjects.indexOf(targetObject);
        if (currentIndex < 0 || currentIndex === targetIndex) {
            return;
        }

        if (typeof canvas.discardActiveObject === "function") {
            canvas.discardActiveObject();
        }

        if (typeof canvas.moveTo === "function") {
            canvas.moveObjectTo(targetObject, targetIndex);
        } else if (Array.isArray(canvas._objects)) {
            canvas._objects.splice(currentIndex, 1);
            canvas._objects.splice(targetIndex, 0, targetObject);
        }

        if (typeof canvas.setActiveObject === "function") {
            canvas.setActiveObject(targetObject);
        }

        canvas.requestRenderAll();
        updateCanvasState();
        LoadTimeline();
    };

