    /**
     * Find the first serialized object that matches the requested name.
     *
     * @param {*} objects Runtime parameter preserved from the source implementation.
     * @param {*} name Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    /* STAMP: 2026-09-08 - Share every serialized Fabric/custom property while
       retaining the destination identity used by its slide and group records. */
    var sharedObjectIdentityProperties = { id: true, name: true, type: true, objects: true };
    function findSharedObject(objects, source) {
        var sameType = objects.filter(function (item) {
            return item && String(item.type).toLowerCase() === String(source.type).toLowerCase();
        });
        var byId = source.id && sameType.find(function (item) { return item.id === source.id; });
        if (byId) return byId;
        var byName = source.name && sameType.filter(function (item) { return item.name === source.name; });
        // Ambiguous or unnamed objects are not safe matches merely because their type agrees.
        return byName && byName.length === 1 ? byName[0] : null;
    }
    function copySharedObjectProperties(target, source, idMap) {
        if (source.id && target.id && idMap) idMap[source.id] = target.id;
        Object.keys(target).forEach(function (property) {
            if (!sharedObjectIdentityProperties[property] && !Object.prototype.hasOwnProperty.call(source, property)) {
                delete target[property];
            }
        });
        Object.keys(source).forEach(function (property) {
            if (!sharedObjectIdentityProperties[property] && source[property] !== undefined) {
                target[property] = cloneTransferValue(source[property]);
            }
        });
        if (Array.isArray(source.objects) && Array.isArray(target.objects)) {
            source.objects.forEach(function (child, index) {
                var match = findSharedObject(target.objects, child);
                // Cloned legacy groups can have new child IDs; identical structure
                // permits positional matching within the already matched group only.
                if (!match && source.objects.length === target.objects.length &&
                    target.objects[index] && target.objects[index].type === child.type) {
                    match = target.objects[index];
                }
                if (match) copySharedObjectProperties(match, child, idMap);
            });
        }
    }
    function applyObjectReplacement(targetObjects, targetName, sourceObj, innerIndex, idMap) {
        var target = findSharedObject(targetObjects, sourceObj);
        if (!target) return false;
        if (innerIndex !== "" && innerIndex != null) {
            var index = Number(innerIndex);
            var child = sourceObj.objects && sourceObj.objects[index];
            if (!child || !Array.isArray(target.objects)) return false;
            var match = findSharedObject(target.objects, child);
            if (!match && target.objects.length === sourceObj.objects.length &&
                target.objects[index] && target.objects[index].type === child.type) match = target.objects[index];
            if (!match) return false;
            copySharedObjectProperties(match, child, idMap);
        } else {
            copySharedObjectProperties(target, sourceObj, idMap);
        }
        return true;
    }

    /* =========================================================================
       1) CLICK: .ShareProp
       - User clicks a share icon/button on a single object
       - We store selected object info and show slides modal
       ========================================================================= */
    $(document).on("click", ".ShareProp", function () {
        // Extract object identity from DOM attributes (your existing structure)
        var objId = $(this).attr("id").replace("ShareProp_", "");
        var objname = $(this).attr("name");
        var objindex = $(this).attr("data-index");

        // Reset global selection and store the new selection
        resetShareSelectionState();
        setShareSelectionState({ ids: objId, names: objname, index: objindex });

        // Open slides selection modal
        openSlidesModal();

        // Set active object on canvas so user sees what is being shared
        setActiveCanvasObjectById(currobj);
    });

    /* =========================================================================
       2) CLICK: #btnshareprop
       - User clicks "Share" inside modal
       - For each checked slide:
           - Copy matching object JSON from current slide -> target slide
           - Works for:
              a) Multiple objects (comma-separated IDs/names)
              b) Single object (currobjname)
              c) Inner object replace (currobjindex set)
       ========================================================================= */
    // STAMP: 2026-09-07 - Update each checked slide atomically, without navigation.
    $("#btnshareprop").on("click", async function () {
        var button = $(this);
        if (button.prop("disabled")) return;
        var checked = $(".sellos:checked").map(function () { return Number($(this).attr("name")); }).get();
        if (!checked.length) { $("#sharePropertiesStatus").text("Select at least one slide.").prop("hidden", false); return; }
        canvas.getObjects().forEach(restoreObjectHoverPaint);
        var sourceObjects = canvas.toObject(["id"]).objects || [];
        var sourceIds = String(currobj || "").split(",");
        var sources = sourceObjects.filter(function (item) { return sourceIds.indexOf(item.id) >= 0; });
        if (!sources.length) { $("#sharePropertiesStatus").text("No source object selected. Close this window, select an object and choose Share Properties again.").prop("hidden", false); return; }
        var automationSourceIds = [];
        if (sources.length === 1 && currobjindex !== "" && currobjindex != null) {
            var sharedChild = sources[0].objects && sources[0].objects[Number(currobjindex)];
            automationSourceIds = getTransferObjectIds(sharedChild);
        } else {
            sources.forEach(function (source) {
                automationSourceIds = automationSourceIds.concat(getTransferObjectIds(source));
            });
        }
        var sourceAutomation = captureObjectAutomation(generated_slides[slide_index], automationSourceIds, false);
        var updated = 0;
        button.prop("disabled", true);
        $("#sharePropertiesStatus").text("Sharing properties…").prop("hidden", false);
        try {
            for (var targetIndex of checked) {
                if (targetIndex === slide_index || !generated_slides[targetIndex]) continue;
                var slide = generated_slides[targetIndex];
                var history = ensureSlideHistoryState(slide.id, slide.jsonobj);
                var current = history.canvasState[history.currentStateIndex];
                var json = typeof current === "string" ? JSON.parse(current) : JSON.parse(JSON.stringify(current));
                var changed = false;
                var sharedObjectIdMap = {};
                sources.forEach(function (source) {
                    if (applyObjectReplacement(json.objects || [], source.name, source, sources.length > 1 ? null : currobjindex, sharedObjectIdMap)) changed = true;
                });
                if (!changed) continue;
                slide.jsonobj = json;
                applyObjectAutomation(slide, sourceAutomation, sharedObjectIdMap, true, true);
                var next = JSON.stringify(json);
                if (next !== (typeof current === "string" ? current : JSON.stringify(current))) {
                    history.canvasState = history.canvasState.slice(0, history.currentStateIndex + 1);
                    history.canvasState.push(next);
                    if (history.canvasState.length > ruConfig.maxStatesPerSlide) history.canvasState.shift();
                    history.currentStateIndex = history.canvasState.length - 1;
                }
                updated++;
                // Refresh previews offscreen; never change the user's active slide.
                var preview = new fabric.StaticCanvas(document.createElement("canvas"), {
                    width: canvas.getWidth(), height: canvas.getHeight(), renderOnAddRemove: false
                });
                try {
                    await preview.loadFromJSON(json);
                    preview.renderAll();
                    slide.svg = encodeURIComponent(preview.toSVG());
                    slide.imgprev = preview.toDataURL();
                    updateSlideThumbnail(slide.id, slide.imgprev);
                } catch (error) {
                    console.warn("Shared properties saved; slide preview could not refresh", error);
                } finally {
                    preview.dispose();
                }
            }
            if (updated) {
                $("#btnsharepropclose").click();
                showAlertBox("Properties shared to " + updated + " slide(s).");
            } else {
                $("#sharePropertiesStatus").text("No matching objects found. Objects must have the same ID, or a unique matching name and type.").prop("hidden", false);
            }
        } catch (error) {
            console.error("Share Properties failed", error);
            $("#sharePropertiesStatus").text("Unable to finish sharing properties. " + (error.message || "Please try again.")).prop("hidden", false);
        } finally {
            button.prop("disabled", false);
        }
    });

