        var items = activeObject._objects;
        var selectedChild = items[selectedarray];
        $("#editgrptxt").val(items[selectedarray].text);
        var Name = items[selectedarray].name;
        var type = items[selectedarray].type;

        /* STAMP: 2026-09-08 - A row change is selection only. Discard shared
           picker state and bind legacy group indices to this exact child so
           no value from the previously edited child is applied implicitly. */
        closeColorPickerPopup();
        $("#hexColorInput").val("").removeClass("is-invalid");
        colorMode = "";
        hdntextbackstrokehover = "0";
        grpfont = (type == "textbox" || type == "i-text" || type == "text") ? Number(selectedarray) : -1;
        grpshp = (type == "rect" || type == "circle" || type == "triangle" || type == "line" || type == "polygon") ? Number(selectedarray) : -1;
        $("#tdtall, #tdtalc, #tdtalr, #tdtalj").css("background", "transparent");
        $("#tdbold, #tditalic, #tdunderline").css("background", "#444");
        $("#div_bold, #div_italic, #div_underline").removeClass("div-font-style-selected");
        $(".textAlignment").removeClass("div-font-style-selected");
        capturePropertyResetSnapshot(selectedChild, true);
