    //Select Object ===================================================================================================
    /**
     * Select the specified canvas object and synchronize sidebar and canvas focus.
     *
     * @param {*} objId Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    Selectobj = function (objId) {
        $(".showsel").css("background", "#fff");
        $(".showsel").css("color", "#000");
        $(".showsel").find("a").css("color", "#000");
        $("#showsel_" + objId + "").css("background", "#444");
        $("#showsel_" + objId + "").css("color", "#fff");
        $("#showsel_" + objId + "").find("a").css("color", "#fff");
        canvas.getObjects().forEach(function (o) {
            if (o.id === objId) {
                if (CurrentSelObj == "" || CurrentSelObj != objId) {
                    CurrentSelObj = objId;
                    var divlen = $("#chkobj_" + objId + "").length;
                    if (parseInt(divlen) > 0) {
                        var contactTopPosition = $("#div_" + objId + "").position().top;
                        $("#myObjnav").animate({ scrollTop: contactTopPosition });
                    }
                    canvas.setActiveObject(o);
                }
            } else {
                $("#chkobj_" + o.id + "").prop("checked", false);
            }
        });
    };

    //Select Object ===================================================================================================
    /**
     * Discard the active canvas selection for the specified object context.
     *
     * @param {*} objId Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    DeSelectobj = function (objId) {
        canvas.getObjects().forEach(function (o) {
            if (o.id === objId) {
                $("#showsel_" + objId + "").css("background", "#fff");
                $("#showsel_" + objId + "").css("color", "#000");
                $("#showsel_" + objId + "").find("a").css("color", "#000");
                canvas.discardActiveObject();
            }
        });
    };

