    /*----------------- Added by Viral ----------------- */
    /**
     * Request slide-audio deletion through the parent-window bridge and await a response.
     *
     * @param {*} payload Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    function deleteSlideAudioToReact(payload) {
        const requestId = crypto.randomUUID();

        window.parent.postMessage(
            {
                type: "DELETE_SLIDE_AUDIO",
                requestId,
                payload
            },
            window.location.origin
        );

        return new Promise((resolve, reject) => {
            /**
             * Structured reference for handler.
             *
             * @param {*} event Runtime parameter preserved from the source implementation.
             * @returns {*} Value and side effects preserved from the source implementation.
             */
            function handler(event) {
                if (event.origin !== window.location.origin) return;

                const msg = event.data;
                if (!msg || msg.requestId !== requestId) return;

                if (msg.type === "DELETE_SLIDE_AUDIO_SUCCESS") {
                    window.removeEventListener("message", handler);
                    resolve(msg.payload); // { url: '...' }
                }

                if (msg.type === "DELETE_SLIDE_AUDIO_ERROR") {
                    window.removeEventListener("message", handler);
                    reject(new Error(msg.error || "Upload failed"));
                }
            }

            window.addEventListener("message", handler);
        });
    }

    /**
     * Validate whether the supplied string can be parsed as a URL.
     *
     * @param {*} str Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    function isValidUrl(str) {
        try {
            new URL(str);
            return true;
        } catch {
            return false;
        }
    }

    /**
     * Extract the trailing file name portion from a valid URL string.
     *
     * @param {*} str Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    function getFileNameFromUrl(str) {
        if (!isValidUrl(str)) return null;

        const url = new URL(str);
        const fileName = url.pathname.split('/').pop(); // last part
        return fileName || null;
    }

    // Confirm delete
    $("#btnConfirmRemoveAudio").on("click", async function () {
        var $confirmButton = $(this);
        var confirmation = $("#confirmRemoveAudioModal");
        var pendingSlideId = confirmation.data("slideId");
        var targetIndex = generated_slides.findIndex(function (slide) { return slide && slide.id === pendingSlideId; });
        if (targetIndex < 0) targetIndex = slide_index;
        var targetSlide = generated_slides[targetIndex];
        var audioUrl = confirmation.data("audioUrl") || (targetSlide && targetSlide.SlideAudio) || $('#getaud').attr('src');
        var fileName = getFileNameFromUrl(audioUrl);
        $confirmButton.prop("disabled", true).text("Removing...");

        try {
            if (fileName) {
                await deleteSlideAudioToReact(fileName);
            }

            if (targetSlide) targetSlide.SlideAudio = "";
            refreshSlideMediaIndicators(pendingSlideId || (targetSlide && targetSlide.id));

            // Reset both the legacy preview and the slide-media modal state.
            $("#getaud").attr("src", "").hide();
            $("#audioPreviewArea").hide();
            $("#audioStatusText").text("No audio");
            $("#slideMediaPreview").empty();
            $("#slideMediaStatus").text("No media attached");
            $("#slideMediaRemoveBtn").prop("hidden", true);
            $("#slideMediaChangeBtn").text("Select audio");
            $("#chkplayonce").prop("checked", false);
            $("#divpaofl").hide();
            $("#divmanageslideaud").show();
            window.setTimeout(syncBlankSlideActions, 0);
            confirmRemoveAudioModal.hide();
        } catch (error) {
            console.error("Unable to remove slide audio", error);
            $("#slideMediaStatus").text("Unable to remove audio. Please try again.");
        } finally {
            $confirmButton.prop("disabled", false).text("Yes, Remove");
        }
    });

