    window.CGLoadTimeline = LoadTimeline;

    /* STAMP: 2026-08-26 - Quick Action hyperlink bridge.
     * Keeps the compact selection toolbar on the established slide action and
     * Fabric serialization paths so links remain editable in legacy panels. */
    window.CGObjectLinkEditor = {
        get: function (objectId, selection) {
            var hasSelectedText = selection && selection.text && selection.end > selection.start;
            var action = slide_actions.find(function (entry) {
                if (!entry || entry.actionFrom !== objectId || entry.function !== "Hyperlink" || entry.isDocument) return false;
                if (!hasSelectedText) return !entry.selText;
                return entry.selText === selection.text
                    && Number(entry.startIndex) === Number(selection.start)
                    && Number(entry.endIndex) === Number(selection.end);
            });
            if (!action) return null;
            return {
                url: action.actionTo || "",
                openInNewTab: action.openInNewTab !== false && action.SelTab !== "SameTab",
                followLink: action.followLink !== false
            };
        },
        save: function (objectId, values) {
            var slide = generated_slides && generated_slides[slide_index];
            var object = canvas && typeof canvas.getObjectById === "function" ? canvas.getObjectById(objectId) : null;
            if (!slide || !object || !values || !values.url) return false;

            var selection = values.selection;
            var hasSelectedText = selection && selection.text && selection.end > selection.start;
            var action = slide_actions.find(function (entry) {
                if (!entry || entry.actionFrom !== objectId || entry.function !== "Hyperlink" || entry.isDocument) return false;
                if (!hasSelectedText) return !entry.selText;
                return entry.selText === selection.text
                    && Number(entry.startIndex) === Number(selection.start)
                    && Number(entry.endIndex) === Number(selection.end);
            });
            if (!action) {
                action = {
                    id: generate_id("ca_"),
                    actionFrom: objectId,
                    event: "click",
                    function: "Hyperlink"
                };
                slide_actions.push(action);
            }

            action.actionTo = values.url;
            action.SelTab = values.openInNewTab ? "NewTab" : "SameTab";
            action.openInNewTab = values.openInNewTab !== false;
            action.followLink = values.followLink !== false;
            action.isDocument = false;

            if (["text", "textbox", "i-text"].indexOf(String(object.type).toLowerCase()) !== -1) {
                if (hasSelectedText && typeof object.setSelectionStyles === "function") {
                    action.startIndex = selection.start;
                    action.endIndex = selection.end;
                    action.selText = selection.text;
                    object.setSelectionStyles({ fill: "#1e01ff", underline: true }, selection.start, selection.end);
                    slide_actions = slide_actions.filter(function (entry) {
                        return entry === action
                            || entry.actionFrom !== objectId
                            || entry.function !== "Hyperlink"
                            || !!entry.selText;
                    });
                } else {
                    delete action.startIndex;
                    delete action.endIndex;
                    delete action.selText;
                    object.set({ fill: "#1e01ff", underline: true });
                    slide_actions = slide_actions.filter(function (entry) {
                        return entry === action
                            || entry.actionFrom !== objectId
                            || entry.function !== "Hyperlink";
                    });
                }
                object.setCoords();
            }

            slide.actions = slide_actions;
            slide.jsonobj = canvas.toObject(["id"]);
            slide.jsonobj.actions = slide_actions;
            slide.svg = encodeURIComponent(canvas.toSVG());
            slide.imgprev = canvas.toDataURL();
            canvas.requestRenderAll();
            canvas.fire("object:modified", { target: object });
            LoadTimeline();
            if (typeof syncSelectedObjectAutomationPanel === "function") syncSelectedObjectAutomationPanel();
            updateCanvasState();
            return true;
        }
    };

    //Select Object By ID ===================================================================================================
    var SelectObject = function (ObjectName) {
        canvas.getObjects().forEach(function (o) {
            if (o.id === ObjectName) {
                canvas.setActiveObject(o);
                canvas.remove(o);
                canvas.renderAll();
            }
        })
    }

    //Menu Action ===========================================================================================================
    $("#drpselactn").on("change", function () {
        IsTarget = 0;
        selectedClickEvent = "";

        var selectedValue = $(this).val();

        // Keep original meaning, just clearer naming + reuse
        var isNotHyperlink = (clickactionallocated !== "Hyperlink" && clickactionallocated !== "");
        var isNotMoveToSlide = (clickactionallocated !== "movetoslide" && clickactionallocated !== "");

        // Helpers (no renames/removals of existing globals; only local cleanup)
        var showDeletePopup = function () {
            showDeletePrompt();
            $("#delobj").hide();
            $("#delanim, #removeactn").show();
            $("#DeleteSelected").hide();
        };

        var resetWrappers = function (showArr, hideArr) {
            (showArr || []).forEach(function (sel) { $(sel).show(); });
            (hideArr || []).forEach(function (sel) { $(sel).hide(); });
        };

        var hideElements = function (arr) {
            if (!arr || !arr.length) return;
            $(arr.join(", ")).hide();
        };

        var showElements = function (arr) {
            if (!arr || !arr.length) return;
            $(arr.join(", ")).show();
        };

        var resetAddDescriptionCommon = function () {
            $("#txtadhead").val("");
            $("#txtaddesc").summernote("code", "");
            $(".fr-view").html("");
            $(".clanimWrapper").hide();

            $("#adddescriptionWrapper").show();

            $("#divupdoc").hide();
            $("#Hyperlink").hide();
            $("#vidupoad").hide();
            $("#vidlink").hide();
            $("#divvidembbed").hide();

            $("#deladaction").hide();

            $("#divprevauddesc").hide();
            $("#divupdescaud").show();
            $("#prevauddesc").attr("src", "");
        };

        // -------------------------
        // Case: 1 (Hyperlink URL)
        // -------------------------
        if (selectedValue === "1") {
            if (isNotHyperlink) {
                showDeletePopup();
            } else {
                resetWrappers(
                    ["#HyperlinkWrapper"],
                    [".animateWrapper", "#slideChangeWrapper", ".authoringtoolWrapper", "#adddescriptionWrapper"]
                );

                selectedClickEvent = "Hyperlink";

                hideElements(["#divupdoc", "#vidupoad", "#divvidembbed"]);
                showElements(["#Hyperlink"]);
            }
        }

        // -------------------------
        // Case: 2 (Hyperlink Document)
        // -------------------------
        if (selectedValue === "2") {
            if (isNotHyperlink) {
                showDeletePopup();
            } else {
                resetWrappers(
                    ["#HyperlinkWrapper"],
                    [".animateWrapper", "#slideChangeWrapper", ".authoringtoolWrapper", "#adddescriptionWrapper"]
                );

                selectedClickEvent = "Hyperlink";

                showElements(["#divupdoc", "#divtabsel"]);
                hideElements(["#vidupoad", "#Hyperlink", "#adddoc", "#divvidembbed"]);
            }
        }

        // -------------------------
        // Case: 3 (Move to Slide)
        // -------------------------
        if (selectedValue === "3") {
            if (isNotMoveToSlide) {
                showDeletePopup();
            } else {
                resetWrappers(
                    ["#slideChangeWrapper"],
                    [".authoringtoolWrapper", "#HyperlinkWrapper", ".animateWrapper", "#adddescriptionWrapper"]
                );

                selectedClickEvent = "movetoslide";

                hideElements(["#divupdoc", "#Hyperlink", "#vidupoad", "#vidlink", "#divvidembbed"]);
            }
        }

        // -------------------------
        // Case: 4 (Add Marker Details - "ad")
        // -------------------------
        if (selectedValue == "4") {
            if (clickactionallocated != "movetoslide" && clickactionallocated != "") {
                showDeletePrompt();
                $("#delobj").hide();
                $("#delanim").show();
                $("#removeactn").show();
                $("#DeleteSelected").hide();
            } else {
                resetAddDescriptionCommon();
                selectedClickEvent = "ad";
            }
        }

        // -------------------------
        // Case: 5 (Add Description - "adesc")
        // -------------------------
        if (selectedValue == "5") {
            if (clickactionallocated != "movetoslide" && clickactionallocated != "") {
                showDeletePrompt();
                $("#delobj").hide();
                $("#delanim").show();
                $("#removeactn").show();
                $("#DeleteSelected").hide();
            } else {
                resetAddDescriptionCommon();
                selectedClickEvent = "adesc";
            }
        }

        // -------------------------
        // Case: 6 (Release Next Unit - "rnu")
        // -------------------------
        if (selectedValue == "6") {
            if (clickactionallocated != "rnu" && clickactionallocated != "") {
                showDeletePrompt();
                $("#delobj").hide();
                $("#delanim").show();
                $("#removeactn").show();
                $("#DeleteSelected").hide();
            } else {
                resetAddDescriptionCommon();
                selectedClickEvent = "rnu";
            }
        }

        // Common reset
        $("#chkonhover").prop("checked", false);
        $(".hoverWrapper").show();
        $("#actnhover").hide();
    });


