    //Change Slide ============================================================================================================
    /**
     * Load a target slide into the editor and synchronize related slide UI state.
     *
     * @param {*} slide_id Runtime parameter preserved from the source implementation.
     * @param {*} fromDelete Runtime parameter preserved from the source implementation.
     * @param {*} fromDuplicate Runtime parameter preserved from the source implementation.
     * @param {*} fromUndo Runtime parameter preserved from the source implementation.
     * @param {*} Index Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    changeSlide = function (slide_id, fromDelete, fromDuplicate, fromUndo, Index) {
        if (ruConfig.isRestoring) return;
        if (selected_slide_id && !fromUndo) updateCanvasState();
        clearSelectionForSlideNavigation();

        selsld = 1;
        slideact = "Change";
        var lastSlideId = selected_slide_id;
        //First save data for old slide.
        if (selected_slide_id === "" && !(fromDelete && generated_slides.length === 1)) {
            return;
        }
        if (!fromDelete) {
            if (!fromDuplicate) {
                updateSlideThumbnail(selected_slide_id, canvas.toDataURL());
            } else {
                updateSlideThumbnail(slide_id, canvas.toDataURL());
            }
            //Save SVG for Slide 

            SetHoverClickValue();
            generated_slides[slide_index].svg = encodeURIComponent(canvas.toSVG());
            generated_slides[slide_index].imgprev = canvas.toDataURL();
            generated_slides[slide_index].groups = slide_groups;
            generated_slides[slide_index].actions = slide_actions;
            generated_slides[slide_index].loadActions = slide_load_actions;
            generated_slides[slide_index].controls = slide_controls;
            generated_slides[slide_index].animationOnControls = animationOnControls;
            generated_slides[slide_index].action_list = clickActionList;
            generated_slides[slide_index].load_action_list = loadActionList;
            generated_slides[slide_index].jsonobj = canvas.toObject(['id']);
            generated_slides[slide_index].UniquepgeName = UniqueID;
            generated_slides[slide_index].ShowPaginate = ShowPaginate;
            generated_slides[slide_index].ShowNavigate = ShowNavigate;
            generated_slides[slide_index].DisableAnimation = settings_DisableAnimation;
            generated_slides[slide_index].AllowZoom = AllowZoom;
            generated_slides[slide_index].HoverBackColor = HoverBackColor;
            generated_slides[slide_index].HoverBackStrokeColor = HoverBackStrokeColor
            generated_slides[slide_index].HoverBackStrokeWidth = HoverBackStrokeWidth
            generated_slides[slide_index].HoverTextColor = HoverTextColor
            generated_slides[slide_index].HoverTransparency = HoverTransparency;
            generated_slides[slide_index].ActiveBackColor = ActiveBackColor;
            generated_slides[slide_index].ActiveBackStrokeColor = ActiveBackStrokeColor
            generated_slides[slide_index].ActiveBackStrokeWidth = ActiveBackStrokeWidth
            generated_slides[slide_index].ActiveTextColor = ActiveTextColor;
            generated_slides[slide_index].ActiveTransparency = ActiveTransparency;
            generated_slides[slide_index].InActiveTransparency = InActiveTransparency;
            generated_slides[slide_index].ButtonTitlt = ButtonTitlt;
            generated_slides[slide_index].order = parseInt(slide_index) + 1;
        }
        //Generate data for CLICKED slide.

        var clicked_slide_index = generated_slides.findIndex(x => x.id === slide_id);
        var clicked_slide = generated_slides[clicked_slide_index];
        selected_slide_id = clicked_slide.id;
        slides_order = clicked_slide.order;
        slide_index = clicked_slide_index;
        slide_groups = clicked_slide.groups;
        slide_actions = (clicked_slide.actions) ? clicked_slide.actions : [];
        //    ////console.log("new slide actions : " + slide_actions);
        slide_load_actions = clicked_slide.loadActions;
        slide_controls = clicked_slide.controls;
        animationOnControls = (clicked_slide.animationOnControls) ? clicked_slide.animationOnControls : [];
        clickActionList = clicked_slide.action_list;
        loadActionList = clicked_slide.load_action_list;
        $('.loadActionList').html(loadActionList);
        $('.clickActionList').html(clickActionList);
        var slideHistory = ensureSlideHistoryState(clicked_slide.id, clicked_slide.jsonobj);
        loadCanvasStateSnapshot(slideHistory.canvasState[slideHistory.currentStateIndex], function () {
            refreshUndoRedoButtons(selected_slide_id);
        });

        var clickedDisableAnimation = getFlag(clicked_slide.DisableAnimation, 0);
        DisableAnimation = clickedDisableAnimation;
        settings_DisableAnimation = clickedDisableAnimation;
        applyDisableAnimationUI(clickedDisableAnimation);

        //Update click and loa animation Object Select Dropdown list
        $('#sel_control').html('');
        ids = [];
        $.each(slide_controls, function (key, sc) {
            var tmp_option = '<option value="' + sc.id + '">' + sc.ctrl_name + '</option>';
            $('#sel_control').append(tmp_option);
        });
        for (i = 0; i < clicked_slide.controls.length; i++) {
            ids.push(clicked_slide.controls[i].id);
        }
        setTimeout(function () { updateDropdownList(); }, 1000);
        $('.slideThumbnail').removeClass('selected');
        $('#' + clicked_slide.id).addClass('selected');
        $('#' + clicked_slide.id).html('');
        $('.sld').removeClass('highlight');
        $('.' + clicked_slide.id).addClass('highlight');
        activeslide = clicked_slide.id;
        if (parseInt(slide_index) > 0) { } else {
            $("#divldanimupdown").show();
        }
        //get Backgroind color
        var bkColor = canvas.backgroundColor;
        if (bkColor != "") {
            $("#canvasbackdiv").css("background-color", bkColor);
        } else {
            $("#canvasbackdiv").css("background-color", "#fff");
        }
        $(".sldactn").hide();
        $("#sldaud_" + activeslide).show();
        //Check if audio file exists        
        if (
            generated_slides[slide_index].SlideAudio === "" ||
            generated_slides[slide_index].SlideAudio === undefined
        ) {
            $("#delsldaudio").hide();
            $("#getaud").hide();
            $("#divpaofl").hide();
            $("#divmanageslideaud").show();
        } else {

            $("#delsldaudio").show();
            $("#audioPreviewArea").show();
            $("#divmanageslideaud").hide();
            $("#saveaudio").hide();
            $("#getaud").show();
            $("#divpaofl").show();
            var audioUrl = generated_slides[slide_index].SlideAudio.replace(/\\/g, "/");
            $("#getaud").attr("src", audioUrl);

            $("#sldaud_" + activeslide)
                .show()
                .attr("title", "Replace or Remove Audio")
                .html("<i class='fa fa-volume-up'></i>");
        }

        //Check if Video file exists         
        if (generated_slides[slide_index].SlideVideo === undefined) {
            generated_slides[slide_index].SlideVideo = undefined;
            $('#txtsldvideoembedlink').val("");
            $("#Addsldvideoembd").show();
            $("#delsldvideoembd").show();
            $("#delsldvideo").hide();
            $("#repsldvideo").hide();
            $("#getvid").hide();
            $("#getvid").html("");
            $("#divmanageslidevidembed").show();
        }
        else {
            if (generated_slides[slide_index].SlideVideo == "") {
                generated_slides[slide_index].SlideVideo = undefined;
                $('#txtsldvideoembedlink').val("");
                $("#Addsldvideoembd").show();
                $("#delsldvideoembd").show();
                $("#delsldvideo").hide();
                $("#repsldvideo").hide();
                $("#getvid").hide();
                $("#getvid").html("");
                $("#divmanageslidevidembed").show();
            }
            else {
                if (generated_slides[slide_index].SlideVideo.includes("data:video")) {
                    $("#videolink").val(generated_slides[slide_index].SlideVideo);
                    $("#delsldvideo").show(); $("#repsldvideo").show(); $("#getvid").show(); $("#divpaofl").show(); $("#divpaofl").show();
                    $("#getvid").attr("src", generated_slides[slide_index].SlideVideo);

                    $("#divmanageslidevidembed").hide();
                    $("#uploadvideo").val("");
                    $(".loadingWrapper").hide();
                }
                if (generated_slides[slide_index].SlideVideo.includes("iframe")) {
                    var slideVideo = generated_slides[slide_index].SlideVideo;
                    $("#divmanageslidevidembed").show();
                    $("#txtsldvideoembedlink").val(slideVideo);
                    $("#Addsldvideoembd").hide();
                    $("#delsldvideoembd").show();
                    renderSlideVideoPreview(slideVideo);
                }
                else {
                    renderSlideVideoPreview("");
                }
            }
        }

        if (generated_slides[slide_index].PlayAudonfv === undefined) { document.getElementById("chkplayonce").checked = false; $("#chkplayonce").parent().removeClass("checked"); } else { if (generated_slides[slide_index].PlayAudonfv == 1) { document.getElementById("chkplayonce").checked = true; $("#chkplayonce").parent().addClass("checked"); } else { document.getElementById("chkplayonce").checked = false; $("#chkplayonce").parent().removeClass("checked"); } }
        setTimeout(function () { $("#myObjnav").fadeIn(); $("#viewobjects").click(); }, 1000);
        CurrentSlideNo = slide_index;
    };

