    //Delet Slide Modal =======================================================================================================
    var pendingDeleteSlideId = "";

    requestDeleteSlide = function (slide_id, e) {
        if (e && typeof e.stopPropagation === "function") {
            e.stopPropagation();
        }
        if (!slide_id || generated_slides.length <= 1) {
            return false;
        }

        pendingDeleteSlideId = slide_id;
        safeShowModal("deleteSlideModal", "Are you sure to delete slide?");
        return false;
    };

    $("#confirmDeleteSlide").on("click", function (e) {
        if (!pendingDeleteSlideId) {
            safeHideModal("deleteSlideModal");
            return;
        }

        deleteSlide(pendingDeleteSlideId, e);
        pendingDeleteSlideId = "";
    });

    //Delete Slide ============================================================================================================
    /**
     * Delete a slide from the deck and refresh thumbnails, indexes, and canvas state.
     *
     * @param {*} slide_id Runtime parameter preserved from the source implementation.
     * @param {*} e Runtime parameter preserved from the source implementation.
     * @returns {*} Value and side effects preserved from the source implementation.
     */
    deleteSlide = function (slide_id, e) {
        delete ruConfig.slideHistory[slide_id];
        generated_slides = generated_slides.filter(obj => obj.id !== slide_id);
        $('.' + slide_id).remove();
        $("#sel_slide option[value='" + slide_id + "']").remove();
        slide_counter--;
        total_slides = total_slides - 1;
        updateDropdownList();
        pendingDeleteSlideId = "";
        safeHideModal("deleteSlideModal");
        changeSlide(generated_slides[0].id, true, false, true);
        if (e && typeof e.stopPropagation === "function") {
            e.stopPropagation();
        }
        if (parseInt(slide_counter) <= 1) {
            //$("#divpaginationstatus").hide();
        }
        //Reset All Slides No
        var count = 1;
        $('.slideorder').each(function () {
            $(this).attr('id', 'sldord_' + count + '');
            $(this).html("Slide " + count);
            if ($(this).next().html().includes("Slide")) {
                $(this).next().html("Slide " + count + "");
            }
            count++;
        });
        SetSlideValues();
        refreshUndoRedoButtons(selected_slide_id);
    };

