    /**
     * Preview modal lifecycle recovery stamped 2026-04-10.
     * Keeps the fullscreen preview mounted at body level, disables the extra
     * backdrop layer, and removes stale preview overlay artifacts on close.
     */
    function cleanupPreviewModalArtifacts() {
        document.body.classList.remove("cg-preview-modal-open");

        document
            .querySelectorAll(".modal-backdrop.cg-preview-modal-backdrop")
            .forEach(function (backdrop) {
                backdrop.remove();
            });

        if (!document.querySelector(".modal.show")) {
            document.body.classList.remove("modal-open");
            document.body.style.removeProperty("overflow");
            document.body.style.removeProperty("padding-right");
        }
    }

    var previewFrame = document.getElementById("previewModalFrame");
    var previewModalElement = document.getElementById("previewFullscreenModal");

    document.addEventListener("hidden.bs.modal", function (event) {
        if (
            event &&
            event.target &&
            event.target.id !== "previewFullscreenModal"
        ) {
            resetStandardModalArtifacts();
        }
    });

    if (previewModalElement) {
        if (previewModalElement.parentNode !== document.body) {
            document.body.appendChild(previewModalElement);
        }

        previewModalElement.addEventListener("show.bs.modal", function () {
            cleanupPreviewModalArtifacts();
            document.body.classList.add("cg-preview-modal-open");
        });

        previewModalElement.addEventListener("shown.bs.modal", function () {
            var latestBackdrop = document.querySelector(".modal-backdrop:last-of-type");

            if (latestBackdrop) {
                latestBackdrop.classList.add("cg-preview-modal-backdrop");
            }
        });

        previewModalElement.addEventListener("hidden.bs.modal", function () {
            if (previewFrame) {
                previewFrame.src = "about:blank";
            }

            cleanupPreviewModalArtifacts();
        });
    }

    /**
     * Detects browser storage quota failures so preview can fail gracefully
     * with a user-facing warning instead of breaking silently.
     * Documentation stamp: 2026-04-23.
     */
    function isPreviewStorageQuotaError(error) {
        return error && (
            error.name === "QuotaExceededError" ||
            error.name === "NS_ERROR_DOM_QUOTA_REACHED" ||
            error.code === 22 ||
            error.code === 1014
        );
    }

    //Open Preview========================================================================
    function postPreviewContentToParent(contentData) {
        // Send preview data back to the React host when the generator is running in an iframe.
        // This keeps the standalone preview fallback intact when no parent modal exists.
        if (!contentData || !window.parent || window.parent === window || typeof window.parent.postMessage !== "function") {
            return false;
        }

        window.parent.postMessage(
            {
                type: "PREVIEW_CONTENT",
                contentData: contentData
            },
            window.location.origin
        );

        return true;
    }

    // STAMP: 2026-08-20 - Keep large standalone previews in memory instead of
    // localStorage, whose small browser quota is routinely exceeded by slide JSON.
    var pendingStandalonePreviewData = null;

    function sendStandalonePreviewData(targetWindow) {
        if (!pendingStandalonePreviewData || !targetWindow || typeof targetWindow.postMessage !== "function") return;
        targetWindow.postMessage(
            { type: "PREVIEW_SLIDE_DATA", contentData: pendingStandalonePreviewData },
            window.location.origin
        );
    }

    window.addEventListener("message", function (event) {
        if (event.origin !== window.location.origin || !event.data || event.data.type !== "PREVIEW_READY") return;
        sendStandalonePreviewData(event.source);
    });

    /**
     * STAMP: 2026-08-25 - Open the established content preview with any
     * serialized slide payload. Full-deck and individual-slide previews share
     * this path so animations, actions, media, and HTML behave identically.
     *
     * @param {string} slideData Serialized slide array consumed by preview.html.
     * @returns {void}
     */
    function openSerializedContentPreview(slideData) {
        if (!slideData) {
            return;
        }

        if (postPreviewContentToParent(slideData)) {
            return;
        }

        pendingStandalonePreviewData = slideData;
        var previewUrl = 'preview.html?ts=' + Date.now();
        var previewFrame = document.getElementById('previewModalFrame');
        var previewModalElement = document.getElementById('previewFullscreenModal');

        if (previewFrame) {
            previewFrame.onload = function () {
                sendStandalonePreviewData(previewFrame.contentWindow);
            };
            previewFrame.src = previewUrl;
        }

        if (previewModalElement && window.bootstrap && typeof window.bootstrap.Modal === 'function') {
            window.bootstrap.Modal.getOrCreateInstance(previewModalElement).show();
            return;
        }

        var previewWindow = window.open(previewUrl, '_blank');
        if (!previewWindow) {
            window.location.href = previewUrl.replace(/\?ts=\d+$/, '');
        }
    }

     $("#btnpreview").on('click', function () {
        var slideData = setData(); // ✅ Get JSON data from global function
        // localStorage.setItem("preview_slide_data", slideData); // ✅ Save to storage
        openSerializedContentPreview(slideData);
    });

