/* =============================================================================
   Random string (keeps your char-set)
============================================================================= */

//Generate Random Data======================================================================================================
/**
 * Generate a random identifier string using the editor's custom character set.
 *
 * @param {*} length Runtime parameter preserved from the source implementation.
 * @returns {*} Value and side effects preserved from the source implementation.
 */
function random(length) {
    var chars = "abcdefghkmnpqrstuvwxyzABCDEFGHKMNP";
    var pass = "";
    var len = parseInt(length, 10) || 0;

    for (var x = 0; x < len; x++) {
        var i = Math.floor(Math.random() * chars.length);
        pass += chars.charAt(i);
    }
    return pass;
}


/* =============================================================================
   Cookie helpers
============================================================================= */

//Set Cookie ==============================================================================================================
/**
 * Persist a cookie value used by editor preferences or saved palette data.
 *
 * @param {*} key Runtime parameter preserved from the source implementation.
 * @param {*} value Runtime parameter preserved from the source implementation.
 * @param {*} days Runtime parameter preserved from the source implementation.
 * @returns {*} Value and side effects preserved from the source implementation.
 */
function setCookie(key, value, days) {
    var expires = new Date();

    if (days) {
        expires.setTime(expires.getTime() + (days * 24 * 60 * 60 * 1000));
        document.cookie = key + "=" + encodeURIComponent(value || "") + ";expires=" + expires.toUTCString() + ";path=/";
    } else {
        // long-lived cookie
        document.cookie = key + "=" + encodeURIComponent(value || "") + ";expires=Fri, 30 Dec 9999 23:59:59 GMT;path=/";
    }
}

//Get Cookie ==============================================================================================================
/**
 * Read a cookie value used by editor preferences or saved palette data.
 *
 * @param {*} key Runtime parameter preserved from the source implementation.
 * @returns {*} Value and side effects preserved from the source implementation.
 */
function getCookie(key) {
    var match = document.cookie.match("(^|;) ?" + key + "=([^;]*)(;|$)");
    return match ? decodeURIComponent(match[2]) : null;
}


/* =============================================================================
   Saved colors (delete + repaint)
   - Major cleanup: treat cookie as CSV safely instead of doing many .replace()
============================================================================= */

//Delete Color ==============================================================================================================
/**
 * Remove a saved color from cookie storage and repaint the palette UI.
 *
 * @param {*} colorToDelete Runtime parameter preserved from the source implementation.
 * @returns {*} Value and side effects preserved from the source implementation.
 */
function DeleteColor(colorToDelete) {
    var raw = getCookie("Color") || "";

    // Normalize: remove leading commas/spaces
    raw = raw.replace(/^\s*,+/, "").trim();
    if (!raw) {
        setCookie("Color", "");
        $(".lblsavedcolor").html("");
        return;
    }

    // Split -> filter -> join
    var list = raw
        .split(",")
        .map(function (x) { return (x || "").trim(); })
        .filter(function (x) { return !!x && x !== colorToDelete; });

    if (!list.length) {
        setCookie("Color", "");
        $(".lblsavedcolor").html("");
        return;
    }

    // Save back + repaint palette
    var saved = list.join(",");
    setCookie("Color", saved);
    renderSavedColors(saved);
}

// repaint the palette UI from CSV string
/**
 * Render the saved color palette from its CSV cookie representation.
 *
 * @param {*} savedColorsCsv Runtime parameter preserved from the source implementation.
 * @returns {*} Value and side effects preserved from the source implementation.
 */
function renderSavedColors(savedColorsCsv) {
    if (!savedColorsCsv) {
        $(".lblsavedcolor").html("");
        return;
    }

    var resultColor = savedColorsCsv.split(",");
    var html = "";

    for (var i = 0; i < resultColor.length; i++) {
        var c = (resultColor[i] || "").trim();
        if (!c) continue;

        html += "<div class='cg-saved-color'>";
        html += "<button type='button' class='delcolorsaved' data-color='" + c + "' aria-label='Delete saved color " + c + "'><i class='fa fa-times' aria-hidden='true'></i></button>";
        html += "<span class='fr-command fr-select-color cg-color-swatch' style='background: " + c + ";' tabindex='-1' aria-selected='false' role='button' data-cmd='textColor' title='" + c + "'>";
        html += "<span class='fr-sr-only'>Color " + c + "</span></span>";
        html += "</div>";
    }

    $(".lblsavedcolor").html(html);
}


/* =============================================================================
   bytesToSize (FIXED)
   - Your original returned `(bytes / pow, 2)` which is a comma-operator bug.
============================================================================= */

//Check File Size ==========================================================================================================
/**
 * Convert a byte count into a human-readable size string.
 *
 * @param {*} bytes Runtime parameter preserved from the source implementation.
 * @returns {*} Value and side effects preserved from the source implementation.
 */
function bytesToSize(bytes) {
    var sizes = ["Bytes", "KB", "MB", "GB", "TB"];
    var b = Number(bytes) || 0;
    if (b === 0) return "0 Byte";

    var i = Math.floor(Math.log(b) / Math.log(1024));
    i = Math.min(i, sizes.length - 1);

    var value = b / Math.pow(1024, i);
    return value.toFixed(2) + " " + sizes[i];
}


/* =============================================================================
   replaceAll / escapeRegExp
============================================================================= */

/**
 * Escape regular-expression tokens inside a plain string input.
 *
 * @param {*} string Runtime parameter preserved from the source implementation.
 * @returns {*} Value and side effects preserved from the source implementation.
 */
function escapeRegExp(string) {
    return (string || "").replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

//Replace All================================================================================================================
/**
 * Replace every occurrence of a term inside a string using a safe escaped regex.
 *
 * @param {*} str Runtime parameter preserved from the source implementation.
 * @param {*} term Runtime parameter preserved from the source implementation.
 * @param {*} replacement Runtime parameter preserved from the source implementation.
 * @returns {*} Value and side effects preserved from the source implementation.
 */
function replaceAll(str, term, replacement) {
    if (typeof str === "string" && str.trim() !== "") {
        return str.replace(new RegExp(escapeRegExp(term), "g"), replacement);
    }
    return str;
}


/* =============================================================================
   download helper
============================================================================= */

//Download File ============================================================================================================
/**
 * Trigger a client-side text-file download with the provided content.
 *
 * @param {*} filename Runtime parameter preserved from the source implementation.
 * @param {*} text Runtime parameter preserved from the source implementation.
 * @returns {*} Value and side effects preserved from the source implementation.
 */
function download(filename, text) {
    var element = document.createElement("a");
    element.setAttribute("href", "data:text/plain;charset=utf-8," + encodeURIComponent(text || ""));
    element.setAttribute("download", filename || "download.txt");

    element.style.display = "none";
    document.body.appendChild(element);
    element.click();
    document.body.removeChild(element);
}


