/* =============================================================================
   Canvas JSON loaders (keep your async interface, but make them consistent)
============================================================================= */

/**
 * Load serialized Fabric JSON into the main canvas and resolve when rendering completes.
 *
 * @param {*} json Runtime parameter preserved from the source implementation.
 * @returns {*} Value and side effects preserved from the source implementation.
 */
function loadJsonOnCanvas(json) {
    return canvas.loadFromJSON(json || {}).then(function () {
            canvas.renderAll();
            return true;
    });
}

/**
 * Load serialized Fabric JSON into a temporary canvas for preview generation.
 *
 * @param {*} anyCanvas Runtime parameter preserved from the source implementation.
 * @param {*} json Runtime parameter preserved from the source implementation.
 * @returns {*} Value and side effects preserved from the source implementation.
 */
function loadJsonOnTempCanvas(anyCanvas, json) {
    return new Promise(function (res) {
        anyCanvas.loadFromJSON(json, function () {
            anyCanvas.renderAll();
            res();
        });
    });
}


/* =============================================================================
   getDataAsync (FIXED)
   - Your version monkey-patched canvas.loadFromJSON and never restored it.
   - This version wraps getData + waits until the canvas finishes loading once.
   - Requires a tiny hook inside getData: call `window.__resolveGetDataAsync?.()`
     after your *final* canvas.loadFromJSON completes (see below).
============================================================================= */

/**
 * Wrap slide-data ingestion so callers can await completion consistently.
 *
 * @param {*} importJS Runtime parameter preserved from the source implementation.
 * @returns {*} Value and side effects preserved from the source implementation.
 */
function getDataAsync(importJS) {
    return new Promise(function (resolve) {
        // store resolver so getData can resolve it
        window.__resolveGetDataAsync = function () {
            // resolve only once
            if (window.__resolveGetDataAsync) {
                var fn = window.__resolveGetDataAsync;
                window.__resolveGetDataAsync = null;
                fn = null;
                resolve();
            }
        };

        // call original getData
        getData(importJS);

        // fallback safety: if getData never calls load/resolve, resolve anyway
        setTimeout(function () {
            if (window.__resolveGetDataAsync) {
                window.__resolveGetDataAsync = null;
                resolve();
            }
        }, 5000);
    });
}


