/* =============================================================================
   Helpers (keep behavior, reduce repetition)
============================================================================= */

// Safe JSON parse for ImportJS that may contain "<br />" line breaks
/**
 * Parse imported slide JSON while normalizing embedded line-break markup.
 *
 * @param {*} ImportJS Runtime parameter preserved from the source implementation.
 * @returns {*} Value and side effects preserved from the source implementation.
 */
function parseImportSlides(ImportJS) {
    if (ImportJS === undefined || ImportJS === "") return null;
    try {
        // STAMP: 2026-08-19 - Accept every ContentData shape returned by the API.
        // Older records are JSON strings, while newer endpoints can return parsed
        // arrays, a ContentData wrapper, or a second JSON-encoded string.
        var parsed = ImportJS;
        for (var depth = 0; depth < 2 && typeof parsed === "string"; depth++) {
            var fixed = replaceAll(parsed, "<br />", "\\n");
            parsed = JSON.parse(fixed);
        }
        if (parsed && !Array.isArray(parsed) && parsed.ContentData !== undefined) {
            return parseImportSlides(parsed.ContentData);
        }
        return Array.isArray(parsed) ? parsed : null;
    } catch (e) {
        console.error("parseImportSlides: JSON parse failed", e);
        return null;
    }
}

// Normalize string/object/array to array
/**
 * Normalize a single item or collection into an array shape.
 *
 * @param {*} data Runtime parameter preserved from the source implementation.
 * @returns {*} Value and side effects preserved from the source implementation.
 */
function normalizeToList(data) {
    return Array.isArray(data) ? data : [data];
}

// Toggle a checkbox and its "checked" class (keeps your existing DOM structure)
/**
 * Toggle a checkbox and its wrapper class using the current UI markup conventions.
 *
 * @param {*} selector Runtime parameter preserved from the source implementation.
 * @param {*} isChecked Runtime parameter preserved from the source implementation.
 * @returns {*} Value and side effects preserved from the source implementation.
 */
function setCheckboxWithClass(selector, isChecked) {
    var $el = $(selector);
    $el.prop("checked", !!isChecked);
    $el.parent().toggleClass("checked", !!isChecked);
}

// For your current markup where you used attr("checked", true) previously.
// prop() is the correct way; this keeps UI behavior stable.
/**
 * Toggle a checkbox using both prop and attr for legacy markup compatibility.
 *
 * @param {*} selector Runtime parameter preserved from the source implementation.
 * @param {*} isChecked Runtime parameter preserved from the source implementation.
 * @returns {*} Value and side effects preserved from the source implementation.
 */
function setCheckboxAttrCompat(selector, isChecked) {
    var $el = $(selector);
    $el.prop("checked", !!isChecked);
    $el.attr("checked", !!isChecked); // optional legacy compatibility
    $el.parent().toggleClass("checked", !!isChecked);
}

/**
 * STAMP: 2026-08-31 - Resolve the settings owner from the selected slide.
 *
 * Slide reordering and menu actions can temporarily leave `slide_index` out of
 * step with the visible selection. Prefer the stable slide id so a value set in
 * Navigate Settings is the same value shown later in that slide's Settings.
 */
function getCurrentSettingsSlide() {
    if (!Array.isArray(generated_slides) || generated_slides.length === 0) return null;

    var selectedSlide = generated_slides.find(function (slide) {
        return slide && slide.id === selected_slide_id;
    });

    return selectedSlide || generated_slides[slide_index] || generated_slides[0] || null;
}

// Settings modal chrome helper stamped 2026-05-06
function getCurrentSlideDisableAnimationFlag() {
    var slideRef = getCurrentSettingsSlide();
    if (slideRef) return getFlag(slideRef.DisableAnimation, getFlag(settings_DisableAnimation, 0));

    return getFlag(settings_DisableAnimation, 0);
}

/**
 * STAMP: 2026-09-11 - Shared availability contract for object Quick Actions.
 * The active slide's persisted flag is authoritative whether Disable Animation
 * was applied to one slide or cascaded to the complete deck.
 *
 * @returns {boolean} True when animation authoring is disabled on this slide.
 */
function isCurrentSlideAnimationDisabled() {
    return getCurrentSlideDisableAnimationFlag() === 1;
}

window.isCurrentSlideAnimationDisabled = isCurrentSlideAnimationDisabled;

/** 2026-08-18: Normalize persisted slide-load transitions for legacy JSON safety. */
function normalizeSlideTransition(value) {
    var supported = ["slide-left", "slide-right", "slide-up", "slide-down", "fade-in", "fade-out", "zoom-in", "zoom-out", "flip-horizontal", "flip-vertical", "rotate-in", "bounce-in"];
    return supported.indexOf(value) >= 0 ? value : "none";
}

function updateCurrentSlideTransition(value) {
    if (!Array.isArray(generated_slides) || !generated_slides[slide_index]) return;
    generated_slides[slide_index].SlideTransition = normalizeSlideTransition(value);
    if (generated_slides[slide_index].SlideTransition === "none") {
        generated_slides[slide_index].UseTransitionOnBack = 0;
        setCheckboxAttrCompat("#slideTransitionOnBack", false);
    }
    $("#slideTransitionOnBack").prop("disabled", generated_slides[slide_index].SlideTransition === "none");
    if ($("#slideTransitionAllSlides").is(":checked")) applyCurrentTransitionToAllSlides(true);
}

/** 2026-08-19: Persist optional reuse of this slide's animation on backward navigation. */
function updateCurrentSlideTransitionOnBack(shouldReuse) {
    if (!Array.isArray(generated_slides) || !generated_slides[slide_index]) return;
    generated_slides[slide_index].UseTransitionOnBack = shouldReuse ? 1 : 0;
}

function applyCurrentTransitionToAllSlides(shouldApply) {
    if (!shouldApply || !Array.isArray(generated_slides) || !generated_slides[slide_index]) return;
    var transition = normalizeSlideTransition(generated_slides[slide_index].SlideTransition);
    generated_slides.forEach(function (slide) {
        if (slide) slide.SlideTransition = transition;
    });
}

/** STAMP: 2026-08-20 - Shared provider-panel synchronizer used by modal setup and field handlers. */
function syncArticulationProviderUI() {
    var useElevenLabs = $("#articulationprovider").val() === "elevenlabs";
    $("#cgStandardVoiceOptions").prop("hidden", useElevenLabs);
    $("#cgElevenLabsOptions").prop("hidden", !useElevenLabs);
}

function syncSettingsModalUI(mode) {
    var isSlideMode = mode === "slide";
    var modalEl = document.getElementById("modalsetting");
    var modalTitle = modalEl ? modalEl.querySelector(".modal-title") : null;
    var navRow = document.getElementById("cgSlideSettingsNavigationRow");
    var boundaryRow = document.getElementById("cgCanvasBoundarySettingsRow");
    var transitionRow = document.getElementById("cgSlideTransitionRow");
    var transitionSelect = document.getElementById("slideLoadTransition");
    var transitionOnBack = document.getElementById("slideTransitionOnBack");
    var articulationRow = document.getElementById("cgSlideArticulationRow");
    var autoNavigateRow = document.getElementById("cgSlideAutoNavigateRow");
    var currentSlide = getCurrentSettingsSlide();
    var showCustomNavigation = getFlag(currentSlide && currentSlide.ShowNavigate, getFlag(ShowNavigate, 1)) === 1;
    var canConfigureTransition = isSlideMode && generated_slides.length > 1 && showCustomNavigation;

    if (modalTitle) {
        modalTitle.textContent = isSlideMode ? "Slide Settings!" : "Navigate Settings!";
    }

    if (navRow) {
        navRow.hidden = false;
    }
    if (boundaryRow) boundaryRow.hidden = isSlideMode;
    setCheckboxAttrCompat("#allowObjectsOutsideCanvas", allowObjectsOutsideCanvas);

    if (transitionRow) transitionRow.hidden = !canConfigureTransition;
    if (articulationRow) articulationRow.hidden = !isSlideMode;
    if (autoNavigateRow) autoNavigateRow.hidden = !isSlideMode;
    if (transitionSelect) transitionSelect.value = normalizeSlideTransition(currentSlide && currentSlide.SlideTransition);
    if (transitionOnBack) transitionOnBack.disabled = normalizeSlideTransition(currentSlide && currentSlide.SlideTransition) === "none";
    setCheckboxAttrCompat("#slideTransitionOnBack", getFlag(currentSlide && currentSlide.UseTransitionOnBack, 0) === 1);
    setCheckboxAttrCompat("#slideTransitionAllSlides", false);

    setCheckboxAttrCompat("#disableanimation", getCurrentSlideDisableAnimationFlag() == 1);
    var disableAnimationLocked = isSlideMode
        && getFlag(currentSlide && currentSlide.DisableAnimationTopMenuLock, 0) === 1;
    $("#disableanimation")
        .prop("disabled", disableAnimationLocked)
        .attr("aria-disabled", disableAnimationLocked ? "true" : "false")
        .attr("title", disableAnimationLocked ? "Managed from Navigate Settings" : "");
    setCheckboxAttrCompat("#autonavivate", showCustomNavigation);
    $("#lijtosld").prop("disabled", showCustomNavigation).toggle(!showCustomNavigation);
    var autoNavigateEnabled = getFlag(currentSlide && currentSlide.AutoNavigate, 0) === 1;
    var autoNavigateSeconds = Math.max(1, Math.min(3600, Math.round(Number(currentSlide && currentSlide.AutoNavigateSeconds) || 3)));
    var autoNavigateHasAudio = !!(currentSlide && typeof currentSlide.SlideAudio === "string" && currentSlide.SlideAudio.trim());
    var autoNavigateHasVideo = !!(currentSlide && typeof currentSlide.SlideVideo === "string" && currentSlide.SlideVideo.trim());
    var autoNavigateMediaType = autoNavigateHasAudio ? "audio" : (autoNavigateHasVideo ? "video" : "");
    var autoNavigateOnMediaEnd = !!autoNavigateMediaType && getFlag(currentSlide && currentSlide.AutoNavigateOnMediaEnd, 0) === 1;
    setCheckboxAttrCompat("#slideautonavigate", autoNavigateEnabled);
    setCheckboxAttrCompat("#slideautonavigateonmediaend", autoNavigateOnMediaEnd);
    $("#slideautonavigateseconds").val(autoNavigateSeconds);
    $("#cgSlideAutoNavigateOptions").prop("hidden", !autoNavigateEnabled);
    $("#cgSlideAutoNavigateMediaEndRow").prop("hidden", !autoNavigateMediaType);
    $("#slideautonavigateonmediaendlabel").text(autoNavigateMediaType === "video" ? "Navigate when video ends" : "Navigate when audio ends");
    $("#cgSlideAutoNavigateManualOptions").prop("hidden", autoNavigateOnMediaEnd);
    var articulationEnabled = getFlag(currentSlide && currentSlide.ArticulateContent, 0) === 1;
    setCheckboxAttrCompat("#articulatecontent", articulationEnabled);
    setCheckboxAttrCompat("#articulateallslides", false);
    $("#articulationscript").val(currentSlide && currentSlide.ArticulationScript ? currentSlide.ArticulationScript : "");
    $("#articulationvoicestyle").val(currentSlide && currentSlide.ArticulationVoiceStyle ? currentSlide.ArticulationVoiceStyle : "female");
    $("#articulationvoice").val(currentSlide && currentSlide.ArticulationVoiceURI ? currentSlide.ArticulationVoiceURI : "");
    $("#articulationpitch").val(currentSlide && currentSlide.ArticulationPitch != null ? currentSlide.ArticulationPitch : 1);
    $("#articulationspeed").val(currentSlide && currentSlide.ArticulationRate != null ? currentSlide.ArticulationRate : 1);
    $("#articulationprovider").val(currentSlide && currentSlide.ArticulationProvider ? currentSlide.ArticulationProvider : "standard");
    $("#elevenlabsvoiceid").val(currentSlide && currentSlide.ElevenLabsVoiceId ? currentSlide.ElevenLabsVoiceId : "");
    $("#elevenlabsmodel").val(currentSlide && currentSlide.ElevenLabsModel ? currentSlide.ElevenLabsModel : "eleven_multilingual_v2");
    $("#elevenlabsstability").val(currentSlide && currentSlide.ElevenLabsStability != null ? currentSlide.ElevenLabsStability : 0.5);
    $("#elevenlabssimilarity").val(currentSlide && currentSlide.ElevenLabsSimilarity != null ? currentSlide.ElevenLabsSimilarity : 0.75);
    syncArticulationProviderUI();
    $("#articulationpitchvalue").text(Number($("#articulationpitch").val()).toFixed(1));
    $("#articulationspeedvalue").text(Number($("#articulationspeed").val()).toFixed(1) + "x");
    $("#cgArticulationOptions").prop("hidden", !articulationEnabled);
}

function openSettingsModal(mode) {
    settingMode = mode || "default";
    syncSettingsModalUI(settingMode);
    var modal = new bootstrap.Modal(document.getElementById("modalsetting"));
    modal.show();
}

function openSlideSettingsFromMenu(slideId, e) {
    if (e) {
        e.stopPropagation();
        e.preventDefault();
    }

    if (slideId) {
        changeSlide(slideId, false, false, false);
    }

    openSettingsModal("slide");
}

// Read 0/1 flag safely (undefined => defaultValue)
/**
 * Normalize a slide flag value into a safe 0 or 1 result.
 *
 * @param {*} val Runtime parameter preserved from the source implementation.
 * @param {*} defaultValue Runtime parameter preserved from the source implementation.
 * @returns {*} Value and side effects preserved from the source implementation.
 */
function getFlag(val, defaultValue) {
    if (val === undefined || val === null) return defaultValue;
    return (val == 1) ? 1 : 0;
}

// Disable animation UI (keeps your trigger("change") side-effects)
/**
 * Apply the disable-animation flag to the UI and trigger dependent side effects.
 *
 * @param {*} flag01 Runtime parameter preserved from the source implementation.
 * @returns {*} Value and side effects preserved from the source implementation.
 */
function applyDisableAnimationUI(flag01) {
    $("#disableanimation")
        .prop("checked", flag01 == 1)
        .trigger("change");
}

// Apply ShowPaginate/ShowNavigate/AllowZoom UI + related show/hide bits
/**
 * Apply global pagination, navigation, and zoom flags to the settings UI.
 *
 * @param {*} sp Runtime parameter preserved from the source implementation.
 * @param {*} sn Runtime parameter preserved from the source implementation.
 * @param {*} zm Runtime parameter preserved from the source implementation.
 * @returns {*} Value and side effects preserved from the source implementation.
 */
function applyGlobalFlagsUI(sp, sn, zm) {
    // paginate
    if (sp == 1) {
        setCheckboxAttrCompat("#autopaginate", true);
    } else {
        setCheckboxAttrCompat("#autopaginate", false);
    }

    // navigate + show/hide lijtosld
    if (sn == 1) {
        setCheckboxAttrCompat("#autonavivate", true);
        $("#lijtosld").prop("disabled", true).hide();
    } else {
        setCheckboxAttrCompat("#autonavivate", false);
        $("#lijtosld").prop("disabled", false).show();
    }

    // zoom
    if (zm == 1) {
        setCheckboxAttrCompat("#enablezoom", true);
    } else {
        setCheckboxAttrCompat("#enablezoom", false);
    }
}

// Load JSON into main canvas (promise-based so you can await if needed)
/**
 * Load serialized Fabric JSON into the main canvas and resolve when rendering completes.
 *
 * @param {*} jsonobj Runtime parameter preserved from the source implementation.
 * @returns {*} Value and side effects preserved from the source implementation.
 */
function loadJsonOnCanvas(jsonobj) {
    var canvasJson = normalizeLegacyFabricCircleAngles(jsonobj || {});
    // Some database rows contain jsonobj as a JSON-encoded value inside the
    // outer ContentData JSON. Normalize it before Fabric attempts enlivening.
    if (typeof canvasJson === "string") {
        try {
            canvasJson = JSON.parse(canvasJson);
        } catch (parseError) {
            console.error("loadJsonOnCanvas: invalid slide jsonobj", parseError);
            return Promise.resolve(false);
        }
    }
    return canvas.loadFromJSON(canvasJson).then(function () {
        if (typeof window.restoreContentGeneratorComponents === "function") {
            window.restoreContentGeneratorComponents(canvas, canvasJson);
        }
        canvas.renderAll();
        return true;
    }).catch(function (e) {
        console.error("loadJsonOnCanvas error:", e);
        if (typeof window.restoreContentGeneratorComponents === "function") {
            window.restoreContentGeneratorComponents(canvas, canvasJson);
        }
        return false;
    });
}

// Load JSON into a temp canvas for thumbnail generation
/**
 * Load serialized Fabric JSON into a temporary canvas for preview generation.
 *
 * @param {*} tempCanvas Runtime parameter preserved from the source implementation.
 * @param {*} jsonobj Runtime parameter preserved from the source implementation.
 * @returns {*} Value and side effects preserved from the source implementation.
 */
function loadJsonOnTempCanvas(tempCanvas, jsonobj) {
    var canvasJson = normalizeLegacyFabricCircleAngles(jsonobj || {});
    return tempCanvas.loadFromJSON(canvasJson).then(function () {
        tempCanvas.renderAll();
        return true;
    }).catch(function (e) {
        console.error("loadJsonOnTempCanvas error:", e);
        return false;
    });
}

/* STAMP: 2026-08-21 - Simple slide-wide object animation sequencing. The
   sequence is stored separately so existing advanced load actions remain intact. */
var slideAnimationDraft = [];
var slideAnimationDragIndex = null;

/* STAMP: 2026-08-25 - Author only entrance animations that reveal and retain
   content. Legacy exit effects remain supported by the player for existing
   saved courses, but are intentionally unavailable for new configuration. */
var SLIDE_ANIMATION_EFFECTS = [
    ["none", "No animation"], ["fadein", "Fade In"],
    ["slideinleft", "Slide From Left"], ["slideinright", "Slide From Right"],
    ["slideintop", "Slide From Top"], ["slideinbottom", "Slide From Bottom"],
    ["zoomin", "Zoom In"], ["rotatein", "Rotate In"], ["bounce", "Bounce"]
];

function normalizeEntranceAnimationEffect(effect) {
    return SLIDE_ANIMATION_EFFECTS.some(function (option) { return option[0] === effect; }) ? effect : "none";
}

var SLIDE_OBJECT_ACTIONS = [
    ["0", "Select Action"], ["1", "Insert Hyperlink"], ["2", "Upload Document"],
    ["3", "Jump to Slides"], ["4", "Add Marker Details"], ["5", "Add Description"],
    ["6", "Release Next Unit"]
];
var slideActionDraftObjectId = null;
var slideActionDraftValue = "0";
var slideActionEditingId = null;
var slideActionUploadedDocument = "";

function syncSlideAnimationMenuVisibility() {
    document.querySelectorAll(".cg-slide-animation-menu-item").forEach(function (item) {
        var slideId = item.getAttribute("data-slide-id");
        var slide = Array.isArray(generated_slides) ? generated_slides.find(function (entry) { return entry && entry.id === slideId; }) : null;
        item.hidden = getFlag(slide && slide.DisableAnimation, 0) === 1;
    });

    /* STAMP: 2026-09-11 - Refresh any selected object's toolbar immediately;
     * selection does not need to be cleared and recreated after settings change. */
    window.dispatchEvent(new window.CustomEvent("cg:animation-availability-changed", {
        detail: { disabled: isCurrentSlideAnimationDisabled() }
    }));
}

function getAnimationObjectLabel(object, index) {
    var text = typeof object.text === "string" ? object.text.replace(/\s+/g, " ").trim() : "";
    if (text.length > 38) text = text.slice(0, 35) + "...";
    return text || ((object.type || "object").replace(/(^|[-_])\w/g, function (part) { return part.toUpperCase().replace(/[-_]/, " "); }) + " " + (index + 1));
}

function ensureAnimationObjectIds(objects) {
    objects.forEach(function (object) {
        if (!object.id) object.set("id", generate_id("obj_"));
    });
}

function escapeAnimationHtml(value) {
    return String(value || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");
}

/* STAMP: 2026-08-24 - Render a non-mutating glimpse of the real Fabric object
   beside its modal title. Cross-origin image failures fall back to a type chip. */
function getModalObjectPreviewMarkup(object) {
    var previewUrl = "";
    var typeLabel = String(object && object.type || "object").replace(/[-_]/g, " ").slice(0, 1).toUpperCase();
    try {
        if (object && typeof object.toDataURL === "function") {
            previewUrl = object.toDataURL({ format: "png", multiplier: 0.75, enableRetinaScaling: false });
        }
    } catch (previewError) {
        previewUrl = "";
    }
    var objectId = escapeAnimationHtml(object && object.id);
    var label = escapeAnimationHtml(getAnimationObjectLabel(object, 0));
    return previewUrl
        ? '<button type="button" class="cg-object-glimpse" data-object-preview-id="' + objectId + '" aria-label="View larger preview of ' + label + '" title="View larger preview"><img src="' + escapeAnimationHtml(previewUrl) + '" alt=""></button>'
        : '<button type="button" class="cg-object-glimpse cg-object-glimpse--fallback" data-object-preview-id="' + objectId + '" aria-label="View larger preview of ' + label + '" title="View larger preview">' + escapeAnimationHtml(typeLabel) + '</button>';
}

/* STAMP: 2026-08-24 - Open a read-only medium object preview. Animation rows
   can replay their currently selected effect without changing saved object data. */
/** STAMP: 2026-09-07 - Match the live canvas background in read-only previews.
 * A separate background canvas preserves object transparency and animation;
 * no source object, slide data or canvas settings are modified.
 */
function updateObjectPreviewBackground(dialog) {
    var stage = dialog.querySelector(".cg-object-preview__stage");
    if (!stage) return;
    var background = stage.querySelector(".cg-object-preview__background");
    if (!background) {
        background = document.createElement("canvas");
        background.className = "cg-object-preview__background";
        background.setAttribute("aria-hidden", "true");
        stage.insertBefore(background, stage.firstChild);
    }
    background.width = Math.max(1, canvas.getWidth());
    background.height = Math.max(1, canvas.getHeight());
    var context = background.getContext("2d");
    var color = canvas.backgroundColor;
    context.clearRect(0, 0, background.width, background.height);
    context.fillStyle = color && typeof color.toLive === "function"
        ? color.toLive(context) : (color || "#fff");
    context.fillRect(0, 0, background.width, background.height);
}

function openModalObjectPreview(objectId, animationEffect) {
    var object = canvas.getObjects().find(function (candidate) { return candidate && candidate.id === objectId; });
    var dialog = document.getElementById("cgObjectPreviewDialog");
    var image = document.getElementById("cgObjectPreviewImage");
    var title = document.getElementById("cgObjectPreviewTitle");
    var effectName = document.getElementById("cgObjectPreviewEffect");
    if (!object || !dialog || !image || !title || !effectName) return;

    /* STAMP: 2026-08-25 - Escape the animation modal's stacking context so
       thumbnail previews always render above the active Bootstrap dialog. */
    if (dialog.parentNode !== document.body) {
        document.body.appendChild(dialog);
    }

    var bounds = typeof object.getBoundingRect === "function" ? object.getBoundingRect() : { width: 300, height: 300 };
    var largestSide = Math.max(Number(bounds.width) || 1, Number(bounds.height) || 1);
    var multiplier = Math.max(0.25, Math.min(3, 900 / largestSide));
    var previewUrl = "";
    try {
        previewUrl = object.toDataURL({ format: "png", multiplier: multiplier, enableRetinaScaling: false });
    } catch (previewError) {
        previewUrl = "";
    }
    if (!previewUrl) return;

    var effect = animationEffect || "none";
    var effectOption = SLIDE_ANIMATION_EFFECTS.find(function (option) { return option[0] === effect; });
    title.textContent = getAnimationObjectLabel(object, 0);
    effectName.textContent = effectOption && effect !== "none" ? effectOption[1] : "Object preview";
    image.className = "cg-object-preview__image";
    dialog.classList.remove("cg-object-preview--slide");
    image.alt = "Selected canvas object preview";
    updateObjectPreviewBackground(dialog);
    dialog.hidden = false;
    dialog.setAttribute("aria-hidden", "false");
    document.body.classList.add("cg-object-preview-open");

    // STAMP: 2026-09-07 - Start/replay only after the preview image is ready.
    // Reset the animation frame so repeated previews of the same effect replay.
    var previewStarted = false;
    var startPreview = function () {
        if (previewStarted || dialog.hidden || image.getAttribute("src") !== previewUrl) return;
        previewStarted = true;
        image.onload = null;
        if (effect === "none") return;
        void image.offsetWidth;
        window.requestAnimationFrame(function () {
            if (!dialog.hidden && image.getAttribute("src") === previewUrl) {
                image.classList.add("cg-object-preview__image--" + effect);
            }
        });
    };
    image.onload = startPreview;
    image.src = previewUrl;
    if (image.complete && image.naturalWidth) startPreview();
    var closeButton = dialog.querySelector(".cg-object-preview__close");
    if (closeButton) closeButton.focus();
}

function closeModalObjectPreview() {
    var dialog = document.getElementById("cgObjectPreviewDialog");
    var image = document.getElementById("cgObjectPreviewImage");
    if (!dialog) return;
    dialog.hidden = true;
    dialog.setAttribute("aria-hidden", "true");
    if (image) { image.onload = null; image.src = ""; image.className = "cg-object-preview__image"; }
    document.body.classList.remove("cg-object-preview-open");
    dialog.classList.remove("cg-object-preview--slide");
    if (jumpSlidePreviewTrigger && jumpSlidePreviewTrigger.isConnected) jumpSlidePreviewTrigger.focus();
    jumpSlidePreviewTrigger = null;
}

function renderSlideAnimationRows() {
    var list = document.getElementById("slideAnimationList");
    if (!list) return;
    if (!slideAnimationDraft.length) {
        list.innerHTML = '<div class="cg-animation-list__empty">Add an object to this slide to configure animation.</div>';
        return;
    }

    list.innerHTML = slideAnimationDraft.map(function (entry, index) {
        var safeLabel = escapeAnimationHtml(entry.label);
        var options = SLIDE_ANIMATION_EFFECTS.map(function (effect) {
            return '<option value="' + effect[0] + '"' + (effect[0] === entry.effect ? ' selected' : '') + '>' + effect[1] + '</option>';
        }).join("");
        return '<div class="cg-animation-row" role="listitem" draggable="true" data-animation-index="' + index + '">'
            + '<span class="cg-animation-row__handle" title="Drag to reorder"><i class="fa fa-bars" aria-hidden="true"></i></span>'
            + '<span class="cg-animation-row__order">' + (index + 1) + '</span>'
            + '<span class="cg-object-title"><span class="cg-animation-row__name" title="' + safeLabel + '">' + safeLabel + '</span></span>'
            + '<select class="form-select cg-animation-row__effect" aria-label="Animation effect for ' + safeLabel + '">' + options + '</select>'
            + '<button type="button" class="btn btn-light btn-sm cg-animation-row__preview" data-animation-preview aria-label="Preview selected animation for ' + safeLabel + '" title="Preview animation"><i class="fa fa-play" aria-hidden="true"></i></button>'
            + '<span class="cg-animation-row__moves"><button type="button" class="btn btn-light btn-sm" data-animation-move="up" aria-label="Move up"' + (index === 0 ? ' disabled' : '') + '><i class="fa fa-chevron-up"></i></button>'
            + '<button type="button" class="btn btn-light btn-sm" data-animation-move="down" aria-label="Move down"' + (index === slideAnimationDraft.length - 1 ? ' disabled' : '') + '><i class="fa fa-chevron-down"></i></button></span></div>';
    }).join("");
    slideAnimationDraft.forEach(function (entry, index) {
        var object = canvas.getObjects().find(function (candidate) { return candidate && candidate.id === entry.objectId; });
        var title = list.querySelector('[data-animation-index="' + index + '"] .cg-object-title');
        if (object && title) title.insertAdjacentHTML("afterbegin", getModalObjectPreviewMarkup(object));
    });
}

function prepareSlideAnimationModal() {
    var slide = generated_slides[slide_index];
    if (!slide || getFlag(slide.DisableAnimation, 0) === 1) return;
    var objects = canvas.getObjects();
    ensureAnimationObjectIds(objects);
    var stored = Array.isArray(slide.AnimationSequence) ? slide.AnimationSequence : [];
    var storedById = {};
    stored.forEach(function (entry) { if (entry && entry.objectId) storedById[entry.objectId] = entry; });
    var ordered = stored.map(function (entry) { return objects.find(function (object) { return object.id === entry.objectId; }); }).filter(Boolean);
    objects.forEach(function (object) { if (ordered.indexOf(object) < 0) ordered.push(object); });
    slideAnimationDraft = ordered.map(function (object, index) {
        var saved = storedById[object.id] || {};
        return { objectId: object.id, label: getAnimationObjectLabel(object, index), effect: normalizeEntranceAnimationEffect(saved.effect), duration: Number(saved.duration) || 0.6 };
    });
    $("#slideAnimationSlideName").text(slide.name || "Slide animation");
    $("#slideAnimationStatus").text("");
    renderSlideAnimationRows();
    bootstrap.Modal.getOrCreateInstance(document.getElementById("slideAnimationModal")).show();
}

function getActionSelectValue(action) {
    if (!action) return "0";
    if (action.function === "Hyperlink") {
        return action.isDocument || (typeof action.actionTo === "string" && action.actionTo.indexOf("CanvasJS/Pages/Documents/") !== -1) ? "2" : "1";
    }
    if (action.function === "ad") return "4";
    if (action.function === "adesc") return "5";
    if (action.function === "rnu") return "6";
    if (action.function === "movetoslide") return "3";
    return "0";
}

function getSlideActionById(actionId) {
    var slide = generated_slides[slide_index];
    return slide && Array.isArray(slide.actions) ? slide.actions.find(function (action) { return action && action.id === actionId; }) : null;
}

/** STAMP: 2026-09-07 - Reuse the slide rail image without loading another slide.
 * SVG fallback supports slides whose saved raster thumbnail is unavailable.
 */
function getJumpSlidePreviewUrl(slide) {
    if (slide.imgprev) return slide.imgprev;
    if (!slide.svg) return "";
    try {
        var svg = slide.svg.indexOf("<svg") >= 0 ? slide.svg : decodeURIComponent(slide.svg);
        return "data:image/svg+xml;charset=utf-8," + encodeURIComponent(svg);
    } catch (previewError) { return ""; }
}

var jumpSlidePreviewTrigger = null;
$(document).on("change", "[data-jump-slide-choice]", function () {
    $(this).closest(".cg-actions-fields").find('[data-action-field="slide"]').val(this.value).trigger("change");
}).on("click", "[data-jump-slide-preview]", function (event) {
    event.preventDefault();
    event.stopPropagation();
    var slideId = this.getAttribute("data-jump-slide-preview");
    var slide = generated_slides.find(function (entry) { return entry && entry.id === slideId; });
    var previewUrl = slide && getJumpSlidePreviewUrl(slide);
    var dialog = document.getElementById("cgObjectPreviewDialog");
    if (!previewUrl || !dialog) return;
    jumpSlidePreviewTrigger = this;
    document.body.appendChild(dialog);
    var image = document.getElementById("cgObjectPreviewImage");
    image.onload = null;
    image.className = "cg-object-preview__image";
    image.src = previewUrl;
    image.alt = "Slide preview";
    document.getElementById("cgObjectPreviewTitle").textContent = slide.name || ("Slide " + (generated_slides.indexOf(slide) + 1));
    document.getElementById("cgObjectPreviewEffect").textContent = "Slide preview";
    dialog.classList.add("cg-object-preview--slide");
    dialog.hidden = false;
    dialog.setAttribute("aria-hidden", "false");
    document.body.classList.add("cg-object-preview-open");
    dialog.querySelector(".cg-object-preview__close").focus();
});

function buildSlideActionFields(objectId, actionValue, savedAction) {
    var action = savedAction || {};
    var fields = "";
    if (actionValue === "1") {
        fields = '<label class="form-label">Hyperlink</label><input type="url" class="form-control" data-action-field="url" placeholder="https://example.com" value="' + escapeAnimationHtml(action.actionTo) + '">'
            + '<div class="cg-actions-fields__split"><label>Open in<select class="form-select" data-action-field="target"><option value="NewTab"' + (action.SelTab !== "SameTab" ? ' selected' : '') + '>New window</option><option value="SameTab"' + (action.SelTab === "SameTab" ? ' selected' : '') + '>Same window</option></select></label>'
            + '<label class="form-check form-switch"><input class="form-check-input" type="checkbox" data-action-field="download"' + (action.Candownload == 1 ? ' checked' : '') + '><span>Can download</span></label></div>';
    } else if (actionValue === "2") {
        slideActionUploadedDocument = action.actionTo || slideActionUploadedDocument;
        fields = '<label class="form-label">Document</label><input type="file" class="form-control" data-action-field="document" accept=".pdf,.doc,.docx" data-cg-drop-label="Drop document here or browse" data-cg-drop-hint="PDF, DOC or DOCX">'
            + '<small class="cg-actions-fields__upload-status">' + (slideActionUploadedDocument ? 'Document ready' : 'Choose a PDF or Word document') + '</small>'
            + '<div class="cg-actions-fields__split"><label>Open in<select class="form-select" data-action-field="target"><option value="NewTab"' + (action.SelTab !== "SameTab" ? ' selected' : '') + '>New window</option><option value="SameTab"' + (action.SelTab === "SameTab" ? ' selected' : '') + '>Same window</option></select></label>'
            + '<label class="form-check form-switch"><input class="form-check-input" type="checkbox" data-action-field="download"' + (action.Candownload == 1 ? ' checked' : '') + '><span>Can download</span></label></div>';
    } else if (actionValue === "3") {
        // STAMP: 2026-09-07 - Thumbnail radios retain the existing saved slide ID field.
        var groupName = generate_id("cg_jump_");
        fields = '<span class="form-label">Open slide</span><input type="hidden" data-action-field="slide" value="' + escapeAnimationHtml(action.actionTo) + '">'
            + '<div class="cg-jump-slides" role="radiogroup" aria-label="Open slide">'
            + generated_slides.map(function (slide, index) {
                if (!slide || slide.id === selected_slide_id) return '';
                var label = escapeAnimationHtml(slide.name || ("Slide " + (index + 1)));
                var thumbnail = getJumpSlidePreviewUrl(slide);
                return '<div class="cg-jump-slide"><label class="cg-jump-slide__choice">'
                    + '<input type="radio" name="' + groupName + '" data-jump-slide-choice value="' + escapeAnimationHtml(slide.id) + '"'
                    + (slide.id === action.actionTo ? ' checked' : '') + '><span class="cg-jump-slide__content">'
                    + '<span>' + label + '</span>'
                    + (thumbnail ? '<img src="' + escapeAnimationHtml(thumbnail) + '" alt="' + label + ' thumbnail" loading="lazy">' : '<span class="cg-jump-slide__empty">Preview unavailable</span>')
                    + '</span></label><button type="button" class="cg-jump-slide__enlarge" data-jump-slide-preview="' + escapeAnimationHtml(slide.id)
                    + '" aria-label="Enlarge ' + label + '" title="Enlarge slide"' + (thumbnail ? '' : ' disabled')
                    + '><i class="fa fa-expand" aria-hidden="true"></i></button></div>';
            }).join("") + '</div>';
    } else if (actionValue === "4" || actionValue === "5") {
        fields = '<label class="form-label">Heading</label><input type="text" class="form-control" data-action-field="heading" value="' + escapeAnimationHtml(action.Heading) + '" placeholder="Enter heading">'
            + '<label class="form-label">Description</label><textarea class="form-control" rows="4" data-action-field="description" placeholder="Enter description">' + escapeAnimationHtml(action.Descr) + '</textarea>';
        if (actionValue === "5") {
            fields += '<label class="form-label">Display style</label><select class="form-select" data-action-field="descriptionType"><option value="Popup"' + (action.DescrType !== "Showcase" ? ' selected' : '') + '>Popup</option><option value="Showcase"' + (action.DescrType === "Showcase" ? ' selected' : '') + '>Showcase</option></select>';
        }
    } else if (actionValue === "6") {
        fields = '<p class="cg-actions-fields__note">This object will release the next unit when selected in the content preview.</p>';
    }
    /* STAMP: 2026-08-25 - Keep the selected action's editor attached to its
       own object row. The action value/id travel with the form so several
       configured rows can remain visible without sharing draft state. */
    return '<div class="cg-actions-fields" data-action-object-id="' + escapeAnimationHtml(objectId)
        + '" data-action-value="' + escapeAnimationHtml(actionValue) + '" data-action-id="'
        + escapeAnimationHtml(savedAction && savedAction.id) + '">' + fields
        + '<div class="cg-actions-fields__footer"><span class="cg-actions-fields__error" role="alert"></span><button type="button" class="btn btn-success btn-sm cg-actions-add-btn">' + (savedAction ? 'Update Action' : 'Add Action') + '</button></div></div>';
}

function renderSlideActionRows() {
    var list = document.getElementById("slideActionsList");
    var slide = generated_slides[slide_index];
    var objects = canvas.getObjects();
    if (!list || !slide) return;
    ensureAnimationObjectIds(objects);
    if (!objects.length) {
        list.innerHTML = '<div class="cg-animation-list__empty">Add an object to this slide to configure actions.</div>';
        return;
    }
    var actions = Array.isArray(slide.actions) ? slide.actions : [];
    list.innerHTML = objects.map(function (object, index) {
        var objectActions = actions.filter(function (action) { return action && action.actionFrom === object.id; });
        var isDraftRow = slideActionDraftObjectId === object.id && slideActionDraftValue !== "0";
        var selectedValue = isDraftRow ? slideActionDraftValue : getActionSelectValue(objectActions[0]);
        var safeLabel = escapeAnimationHtml(getAnimationObjectLabel(object, index));
        var showMoveToSlide = getFlag(slide.ShowNavigate, getFlag(ShowNavigate, 1)) !== 1;
        var options = SLIDE_OBJECT_ACTIONS.filter(function (actionOption) {
            return actionOption[0] !== "3" || showMoveToSlide;
        }).map(function (actionOption) {
            return '<option value="' + actionOption[0] + '"' + (actionOption[0] === selectedValue ? ' selected' : '') + '>' + actionOption[1] + '</option>';
        }).join("");
        var countLabel = objectActions.length > 1 ? '<span class="cg-actions-row__count">' + objectActions.length + ' saved</span>' : '';
        var selectedAction = isDraftRow ? getSlideActionById(slideActionEditingId) : objectActions[0];
        return '<div class="cg-actions-row-wrap"><div class="cg-animation-row cg-actions-row" role="listitem" data-object-id="' + escapeAnimationHtml(object.id) + '">'
            + '<span class="cg-animation-row__order">' + (index + 1) + '</span>'
            + '<span class="cg-object-glimpse-wrap">' + getModalObjectPreviewMarkup(object) + '</span>'
            + '<span class="cg-animation-row__name" title="' + safeLabel + '">' + safeLabel + countLabel + '</span>'
            + '<select class="form-select cg-animation-row__effect cg-actions-row__select" aria-label="Action for ' + safeLabel + '">' + options + '</select>'
            + '<button type="button" class="btn btn-light btn-sm cg-actions-row__edit" data-action-id="' + (objectActions[0] ? escapeAnimationHtml(objectActions[0].id) : '') + '" aria-label="Edit saved action" title="Edit saved action"' + (objectActions.length ? '' : ' disabled') + '><i class="fa fa-pencil"></i></button></div>'
            + (selectedValue !== "0" ? buildSlideActionFields(object.id, selectedValue, selectedAction) : '') + '</div>';
    }).join("");
}

function prepareSlideActionsModal() {
    var slide = generated_slides[slide_index];
    if (!slide) return;
    $("#slideActionsSlideName").text(slide.name || "Slide actions");
    $("#slideActionsStatus").text("");
    slideActionDraftObjectId = null;
    slideActionDraftValue = "0";
    slideActionEditingId = null;
    slideActionUploadedDocument = "";
    renderSlideActionRows();
    bootstrap.Modal.getOrCreateInstance(document.getElementById("slideActionsModal")).show();
}

openSlideActionsModal = function (slideId, event) {
    if (event) { event.preventDefault(); event.stopPropagation(); }
    if (!generated_slides.some(function (slide) { return slide && slide.id === slideId; })) return;
    if (selected_slide_id !== slideId) {
        changeSlide(slideId, false, false, false);
        window.setTimeout(prepareSlideActionsModal, 180);
    } else {
        prepareSlideActionsModal();
    }
};

$(document).on("change", ".cg-actions-row__select", function () {
    var value = this.value;
    var objectId = $(this).closest(".cg-actions-row").attr("data-object-id");
    slideActionDraftObjectId = value === "0" ? null : objectId;
    slideActionDraftValue = value;
    slideActionEditingId = null;
    slideActionUploadedDocument = "";
    renderSlideActionRows();
}).on("click", ".cg-actions-row__edit", function () {
    var row = $(this).closest(".cg-actions-row");
    slideActionDraftObjectId = row.attr("data-object-id");
    slideActionEditingId = $(this).attr("data-action-id") || null;
    slideActionDraftValue = getActionSelectValue(getSlideActionById(slideActionEditingId));
    slideActionUploadedDocument = "";
    renderSlideActionRows();
}).on("change", '[data-action-field="document"]', function () {
    var file = this.files && this.files[0];
    if (!file) return;
    slideActionUploadedDocument = "";
    $(this).siblings(".cg-actions-fields__upload-status").text("Uploading document...");
    window.parent.postMessage({ type: "UPLOAD_DOC", file: file }, "*");
}).on("click", ".cg-actions-add-btn", function () {
    saveSlideActionFromModal($(this).closest(".cg-actions-fields"));
});

function saveSlideActionFromModal(fields) {
    var slide = generated_slides[slide_index];
    var objectId = fields.attr("data-action-object-id");
    var value = String(fields.attr("data-action-value") || "0");
    var editingActionId = fields.attr("data-action-id") || null;
    var error = fields.find(".cg-actions-fields__error");
    var actionTo = "";
    if (value === "1") actionTo = String(fields.find('[data-action-field="url"]').val() || "").trim();
    if (value === "2") actionTo = slideActionUploadedDocument;
    if (value === "3") actionTo = fields.find('[data-action-field="slide"]').val() || "";
    if ((value === "1" || value === "2" || value === "3") && !actionTo) {
        error.text(value === "2" ? "Upload a document before adding the action." : "Complete the required field.");
        return;
    }
    var functionMap = { "1": "Hyperlink", "2": "Hyperlink", "3": "movetoslide", "4": "ad", "5": "adesc", "6": "rnu" };
    var action = getSlideActionById(editingActionId) || { id: generate_id("ca_") };
    action.actionFrom = objectId;
    action.actionTo = actionTo;
    action.event = "click";
    action.function = functionMap[value];
    action.isDocument = value === "2";
    action.SelTab = fields.find('[data-action-field="target"]').val() || "NewTab";
    action.openInNewTab = action.SelTab !== "SameTab";
    if (action.followLink === undefined) action.followLink = true;
    action.Candownload = fields.find('[data-action-field="download"]').is(":checked") ? "1" : "0";
    action.Heading = fields.find('[data-action-field="heading"]').val() || "";
    action.Descr = fields.find('[data-action-field="description"]').val() || "";
    action.DescrType = fields.find('[data-action-field="descriptionType"]').val() || "";
    if (!editingActionId) slide_actions.push(action);
    slide.actions = slide_actions;
    slide.jsonobj = canvas.toObject(["id"]);
    slide.jsonobj.actions = slide_actions;
    slide.svg = encodeURIComponent(canvas.toSVG());
    slide.imgprev = canvas.toDataURL();
    $("#slideActionsStatus").text(editingActionId ? "Action updated." : "Action added.");
    slideActionDraftObjectId = null;
    slideActionDraftValue = "0";
    slideActionEditingId = null;
    slideActionUploadedDocument = "";
    renderSlideActionRows();
    LoadTimeline();
    syncSelectedObjectAutomationPanel();
}

/* STAMP: 2026-08-21 - Keep the object property accordions synchronized with
   the same slide-level animation and action records used by the batch modals. */
function getAutomationPanelObject() {
    var objects = getAutomationPanelObjects();
    return objects.length === 1 ? objects[0] : null;
}

/**
 * STAMP: 2026-09-11 - Return the real Fabric objects represented by the current
 * selection. An ActiveSelection is a temporary editor wrapper and must never
 * receive persisted animation or action records of its own.
 *
 * @returns {Array} Selected top-level Fabric objects in visible selection order.
 */
function getAutomationPanelObjects() {
    var activeObject = canvas && canvas.getActiveObject ? canvas.getActiveObject() : null;
    if (!activeObject) return [];

    if (String(activeObject.type || "").toLowerCase() === "activeselection") {
        return sortObjectsByCanvasPosition(canvas.getActiveObjects().filter(function (object) {
            return object && object !== activeObject;
        }));
    }

    return [activeObject];
}

/**
 * STAMP: 2026-09-11 - Present multi-selected objects in their visual reading
 * order: top to bottom, then left to right. Sorting a copy keeps Fabric's layer
 * stack, ActiveSelection membership, coordinates, and saved slide output intact.
 *
 * @param {Array} objects Selected Fabric objects.
 * @returns {Array} A position-sorted copy of the supplied objects.
 */
function sortObjectsByCanvasPosition(objects) {
    return (objects || []).slice().sort(function (first, second) {
        var firstBounds = typeof first.getBoundingRect === "function"
            ? first.getBoundingRect() : { top: Number(first.top) || 0, left: Number(first.left) || 0 };
        var secondBounds = typeof second.getBoundingRect === "function"
            ? second.getBoundingRect() : { top: Number(second.top) || 0, left: Number(second.left) || 0 };
        var verticalDifference = (Number(firstBounds.top) || 0) - (Number(secondBounds.top) || 0);

        if (Math.abs(verticalDifference) > 1) return verticalDifference;
        return (Number(firstBounds.left) || 0) - (Number(secondBounds.left) || 0);
    });
}

/** STAMP: 2026-09-07 - Compact saved animation choices and read-only previews.
 * Use the same effect catalog and change handler as the slide animation editor.
 * Preview never selects or saves an effect; each option exposes its saved state.
 */
function renderObjectAnimationOptions(selectedEffect) {
    var selected = normalizeEntranceAnimationEffect(selectedEffect);
    $("#ObjectAnimationOptions").html(SLIDE_ANIMATION_EFFECTS.map(function (effect) {
        var checked = selected === effect[0];
        return '<div class="cg-animation-option' + (checked ? ' is-selected' : '') + '">'
            + '<label class="cg-animation-option__choice">'
            + '<input type="radio" name="cgObjectAnimationChoice" value="' + effect[0] + '"'
            + (checked ? ' checked' : '') + '><span>' + effect[1] + '</span></label>'
            + (effect[0] === 'none' ? '' : '<button type="button" class="cg-animation-option__preview" data-object-animation-preview="'
                + effect[0] + '" title="Preview ' + effect[1] + '" aria-label="Preview ' + effect[1]
                + '"><i class="fa fa-play" aria-hidden="true"></i></button>')
            + '</div>';
    }).join(""));
}

/**
 * Persist one selected object's entrance animation through the same slide-level
 * AnimationSequence contract used by the Slide Animation modal.
 *
 * @param {string} objectId Stable Fabric object identifier.
 * @param {string} requestedEffect Supported entrance-effect key.
 * @returns {boolean} True when the animation state was persisted.
 */
function saveObjectAnimationEffect(objectId, requestedEffect) {
    var slide = generated_slides[slide_index];
    var object = canvas.getObjects().find(function (candidate) {
        return candidate && candidate.id === objectId;
    });
    var effect = requestedEffect || "none";
    if (!slide || !object || !SLIDE_ANIMATION_EFFECTS.some(function (option) { return option[0] === effect; })) return false;

    var sequence = Array.isArray(slide.AnimationSequence) ? slide.AnimationSequence : [];
    var existingIndex = sequence.findIndex(function (entry) { return entry && entry.objectId === object.id; });
    if (effect === "none") {
        if (existingIndex >= 0) sequence.splice(existingIndex, 1);
        sequence.forEach(function (entry, index) { entry.order = index + 1; });
    } else if (existingIndex >= 0) {
        sequence[existingIndex].effect = effect;
    } else {
        sequence.push({ objectId: object.id, effect: effect, order: sequence.length + 1, duration: 0.6 });
    }

    slide.AnimationSequence = sequence;
    slide.jsonobj = canvas.toObject(["id"]);
    slide.jsonobj.animationSequence = sequence;
    slide.svg = encodeURIComponent(canvas.toSVG());
    slide.imgprev = canvas.toDataURL();
    return true;
}

/** STAMP: 2026-09-11 - Render one compact animation control row per object in
 * an ActiveSelection. Rows mirror Slide Animation identification controls but
 * do not expose sequence reordering from this contextual selection surface. */
function renderSelectedObjectAnimationRows(objects, slide) {
    var sequence = Array.isArray(slide.AnimationSequence)
        ? slide.AnimationSequence
        : (slide.jsonobj && Array.isArray(slide.jsonobj.animationSequence) ? slide.jsonobj.animationSequence : []);
    slide.AnimationSequence = sequence;
    var sequenceById = {};
    sequence.forEach(function (entry) { if (entry && entry.objectId) sequenceById[entry.objectId] = entry; });

    var markup = '<div class="cg-selected-automation-list" role="list" aria-label="Selected object animations">';
    markup += objects.map(function (object, index) {
        var canvasIndex = Math.max(0, canvas.getObjects().indexOf(object));
        var safeLabel = escapeAnimationHtml(getAnimationObjectLabel(object, canvasIndex));
        var selectedEffect = normalizeEntranceAnimationEffect(sequenceById[object.id] && sequenceById[object.id].effect);
        var options = SLIDE_ANIMATION_EFFECTS.map(function (effect) {
            return '<option value="' + effect[0] + '"' + (effect[0] === selectedEffect ? ' selected' : '') + '>' + effect[1] + '</option>';
        }).join("");
        return '<div class="cg-selected-automation-row" role="listitem" data-object-id="' + escapeAnimationHtml(object.id) + '">'
            + '<span class="cg-animation-row__order">' + (index + 1) + '</span>'
            + '<span class="cg-object-glimpse-wrap">' + getModalObjectPreviewMarkup(object) + '</span>'
            + '<span class="cg-animation-row__name" title="' + safeLabel + '">' + safeLabel + '</span>'
            + '<button type="button" class="cg-selected-automation-row__utility" data-object-animation-preview="' + selectedEffect
            + '" data-object-id="' + escapeAnimationHtml(object.id) + '" aria-label="Preview animation for ' + safeLabel
            + '" title="Preview animation"' + (selectedEffect === "none" ? ' disabled' : '') + '><i class="fa fa-play" aria-hidden="true"></i></button>'
            + '<select class="form-select cg-selected-animation-effect" aria-label="Animation for ' + safeLabel + '">' + options + '</select></div>';
    }).join("");
    markup += '</div>';
    $("#ObjectAnimationOptions").html(markup);
}

/** STAMP: 2026-09-11 - Render Slide Actions-style rows for only the objects in
 * the current ActiveSelection. Existing build/save helpers remain authoritative
 * so every row edits the same action records used by playback and slide modals. */
function renderSelectedObjectActionRows(objects, slide) {
    var actions = Array.isArray(slide.actions)
        ? slide.actions
        : (slide.jsonobj && Array.isArray(slide.jsonobj.actions) ? slide.jsonobj.actions : []);
    slide.actions = actions;
    var showMoveToSlide = getFlag(slide.ShowNavigate, getFlag(ShowNavigate, 1)) !== 1;
    var markup = '<div class="cg-selected-automation-list" role="list" aria-label="Selected object actions">';

    markup += objects.map(function (object, index) {
        var objectActions = actions.filter(function (action) { return action && action.actionFrom === object.id; });
        var isDraftRow = slideActionDraftObjectId === object.id && slideActionDraftValue !== "0";
        var selectedValue = isDraftRow ? slideActionDraftValue : getActionSelectValue(objectActions[0]);
        var selectedAction = isDraftRow ? getSlideActionById(slideActionEditingId) : objectActions[0];
        var canvasIndex = Math.max(0, canvas.getObjects().indexOf(object));
        var safeLabel = escapeAnimationHtml(getAnimationObjectLabel(object, canvasIndex));
        var options = SLIDE_OBJECT_ACTIONS.filter(function (option) {
            return option[0] !== "3" || showMoveToSlide;
        }).map(function (option) {
            return '<option value="' + option[0] + '"' + (option[0] === selectedValue ? ' selected' : '') + '>' + option[1] + '</option>';
        }).join("");
        var countLabel = objectActions.length > 1 ? '<span class="cg-actions-row__count">' + objectActions.length + ' saved</span>' : '';
        return '<div class="cg-selected-action-row-wrap"><div class="cg-selected-automation-row" role="listitem" data-object-id="' + escapeAnimationHtml(object.id) + '">'
            + '<span class="cg-animation-row__order">' + (index + 1) + '</span>'
            + '<span class="cg-object-glimpse-wrap">' + getModalObjectPreviewMarkup(object) + '</span>'
            + '<span class="cg-animation-row__name" title="' + safeLabel + '">' + safeLabel + countLabel + '</span>'
            + '<button type="button" class="cg-selected-automation-row__utility cg-selected-actions-row__edit" data-action-id="'
            + (objectActions[0] ? escapeAnimationHtml(objectActions[0].id) : '') + '" aria-label="Edit saved action for ' + safeLabel
            + '" title="Edit saved action"' + (objectActions.length ? '' : ' disabled') + '><i class="fa fa-pencil" aria-hidden="true"></i></button>'
            + '<select class="form-select cg-selected-actions-row__select" aria-label="Action for ' + safeLabel + '">' + options + '</select></div>'
            + (selectedValue !== "0" ? buildSlideActionFields(object.id, selectedValue, selectedAction) : '') + '</div>';
    }).join("");
    markup += '</div>';
    $("#ObjectActionFields").html(markup);
}

$(document).on("change", 'input[name="cgObjectAnimationChoice"]', function () {
    $("#ObjectAnimationEffect").val(this.value).trigger("change");
}).on("click", "[data-object-animation-preview]", function (event) {
    event.preventDefault();
    event.stopPropagation();
    var objectId = this.getAttribute("data-object-id");
    var object = objectId ? canvas.getObjects().find(function (candidate) {
        return candidate && candidate.id === objectId;
    }) : getAutomationPanelObject();
    if (object) openModalObjectPreview(object.id, this.getAttribute("data-object-animation-preview"));
});

function syncSelectedObjectAutomationPanel() {
    var objects = getAutomationPanelObjects();
    var object = objects.length === 1 ? objects[0] : null;
    var activeObject = canvas && canvas.getActiveObject ? canvas.getActiveObject() : null;
    var isMultiSelection = String(activeObject && activeObject.type || "").toLowerCase() === "activeselection";
    var slide = Array.isArray(generated_slides) ? generated_slides[slide_index] : null;
    if (!objects.length || !slide) {
        $("#ObjectAutomationSettings").hide();
        return;
    }
    ensureAnimationObjectIds(objects);
    $("#ObjectAutomationSettings").show();
    if (isMultiSelection) {
        $("#ObjectAutomationName").text(objects.length + " selected objects");
        $("#ObjectAnimationEffect").prop("hidden", true);
        $("#ObjectActionType").prop("hidden", true);
        $("#ObjectAnimationStatus").text("");
        renderSelectedObjectAnimationRows(objects, slide);
        renderSelectedObjectActionRows(objects, slide);
        return;
    }

    $("#ObjectActionType").prop("hidden", false);
    $("#ObjectAutomationName").text(getAnimationObjectLabel(object, canvas.getObjects().indexOf(object)));

    var sequence = Array.isArray(slide.AnimationSequence)
        ? slide.AnimationSequence
        : (slide.jsonobj && Array.isArray(slide.jsonobj.animationSequence) ? slide.jsonobj.animationSequence : []);
    slide.AnimationSequence = sequence;
    var animation = sequence.find(function (entry) { return entry && entry.objectId === object.id; }) || {};
    var selectedAnimationEffect = normalizeEntranceAnimationEffect(animation.effect);
    $("#ObjectAnimationEffect").html(SLIDE_ANIMATION_EFFECTS.map(function (effect) {
        return '<option value="' + effect[0] + '"' + (effect[0] === selectedAnimationEffect ? ' selected' : '') + '>' + effect[1] + '</option>';
    }).join(""));
    renderObjectAnimationOptions(selectedAnimationEffect);
    $("#ObjectAnimationStatus").text("");

    var actions = Array.isArray(slide.actions)
        ? slide.actions
        : (slide.jsonobj && Array.isArray(slide.jsonobj.actions) ? slide.jsonobj.actions : []);
    slide.actions = actions;
    var savedAction = actions.find(function (entry) { return entry && entry.actionFrom === object.id; });
    var selectedAction = getActionSelectValue(savedAction);
    var showMoveToSlide = getFlag(slide.ShowNavigate, getFlag(ShowNavigate, 1)) !== 1;
    $("#ObjectActionType").html(SLIDE_OBJECT_ACTIONS.filter(function (option) {
        return option[0] !== "3" || showMoveToSlide;
    }).map(function (option) {
        return '<option value="' + option[0] + '"' + (option[0] === selectedAction ? ' selected' : '') + '>' + option[1] + '</option>';
    }).join(""));
    slideActionDraftObjectId = object.id;
    slideActionDraftValue = selectedAction;
    slideActionEditingId = savedAction ? savedAction.id : null;
    slideActionUploadedDocument = savedAction && savedAction.isDocument ? savedAction.actionTo : "";
    $("#ObjectActionFields").html(selectedAction === "0" ? "" : buildSlideActionFields(object.id, selectedAction, savedAction));
}

$(document).on("click", "[data-object-automation-toggle]", function () {
    var name = $(this).attr("data-object-automation-toggle");
    var panel = $('[data-object-automation-panel="' + name + '"]');
    var willOpen = panel.prop("hidden");
    panel.prop("hidden", !willOpen);
    $(this).attr("aria-expanded", willOpen).closest(".cg-object-automation__item").toggleClass("is-open", willOpen);
}).on("change", "#ObjectAnimationEffect", function () {
    var object = getAutomationPanelObject();
    var effect = this.value || "none";
    if (!object || !saveObjectAnimationEffect(object.id, effect)) return;
    $("#ObjectAnimationOptions .cg-animation-option").each(function () {
        var radio = $(this).find('input[type="radio"]');
        var selected = radio.val() === effect;
        radio.prop("checked", selected);
        $(this).toggleClass("is-selected", selected);
    });
    $("#ObjectAnimationStatus").text(effect === "none" ? "Animation removed." : "Animation saved.");
}).on("change", ".cg-selected-animation-effect", function () {
    var objectId = $(this).closest(".cg-selected-automation-row").attr("data-object-id");
    if (!saveObjectAnimationEffect(objectId, this.value)) return;
    var status = this.value === "none" ? "Animation removed." : "Animation saved.";
    syncSelectedObjectAutomationPanel();
    $("#ObjectAnimationStatus").text(status);
}).on("change", ".cg-selected-actions-row__select", function () {
    var row = $(this).closest(".cg-selected-automation-row");
    var objectId = row.attr("data-object-id");
    var slide = generated_slides[slide_index];
    var existingAction = (Array.isArray(slide && slide.actions) ? slide.actions : []).find(function (entry) {
        return entry && entry.actionFrom === objectId;
    });
    slideActionDraftObjectId = this.value === "0" ? null : objectId;
    slideActionDraftValue = this.value;
    slideActionEditingId = existingAction ? existingAction.id : null;
    slideActionUploadedDocument = existingAction && existingAction.isDocument ? existingAction.actionTo : "";
    renderSelectedObjectActionRows(getAutomationPanelObjects(), slide);
}).on("click", ".cg-selected-actions-row__edit", function () {
    var row = $(this).closest(".cg-selected-automation-row");
    var slide = generated_slides[slide_index];
    slideActionDraftObjectId = row.attr("data-object-id");
    slideActionEditingId = $(this).attr("data-action-id") || null;
    slideActionDraftValue = getActionSelectValue(getSlideActionById(slideActionEditingId));
    slideActionUploadedDocument = "";
    renderSelectedObjectActionRows(getAutomationPanelObjects(), slide);
}).on("change", "#ObjectActionType", function () {
    var object = getAutomationPanelObject();
    var slide = generated_slides[slide_index];
    if (!object || !slide) return;
    var existingAction = (Array.isArray(slide.actions) ? slide.actions : []).find(function (entry) {
        return entry && entry.actionFrom === object.id;
    });
    slideActionDraftObjectId = object.id;
    slideActionDraftValue = this.value;
    slideActionEditingId = existingAction ? existingAction.id : null;
    slideActionUploadedDocument = "";
    if (this.value === "0") {
        if (existingAction) {
            slide_actions = slide_actions.filter(function (entry) { return entry && entry.id !== existingAction.id; });
            slide.actions = slide_actions;
            slide.jsonobj = canvas.toObject(["id"]);
            slide.jsonobj.actions = slide_actions;
            slide.svg = encodeURIComponent(canvas.toSVG());
            slide.imgprev = canvas.toDataURL();
        }
        slideActionEditingId = null;
        $("#ObjectActionFields").empty();
        return;
    }
    $("#ObjectActionFields").html(buildSlideActionFields(object.id, this.value, existingAction));
}).on("click", "#SaveObjectAnimation", function () {
    var object = getAutomationPanelObject();
    var slide = generated_slides[slide_index];
    if (!object || !slide) return;
    var sequence = Array.isArray(slide.AnimationSequence) ? slide.AnimationSequence : [];
    var existing = sequence.find(function (entry) { return entry && entry.objectId === object.id; });
    var effect = $("#ObjectAnimationEffect").val() || "none";
    var duration = Math.max(0.15, Math.min(10, Number($("#ObjectAnimationDuration").val()) || 0.6));
    if (existing) {
        existing.effect = effect;
        existing.duration = duration;
    } else {
        sequence.push({ objectId: object.id, effect: effect, order: sequence.length + 1, duration: duration });
    }
    slide.AnimationSequence = sequence;
    slide.jsonobj = canvas.toObject(["id"]);
    slide.jsonobj.animationSequence = sequence;
    slide.svg = encodeURIComponent(canvas.toSVG());
    slide.imgprev = canvas.toDataURL();
    $("#ObjectAnimationStatus").text("Animation saved.");
});

/* Right-click selects the target and opens its normal property inspector. */
if (canvas && canvas.upperCanvasEl) {
    canvas.upperCanvasEl.addEventListener("contextmenu", function (event) { event.preventDefault(); });
    canvas.on("mouse:down", function (event) {
        if (!event || !event.e || event.e.button !== 2 || !event.target) return;
        event.e.preventDefault();
        canvas.setActiveObject(event.target);
        canvas.requestRenderAll();
        getselobjprop();
        $("#propertybars").show();
        $("#ObjectAutomationSettings").show();
        syncSelectedObjectAutomationPanel();
    });
    canvas.on("selection:cleared", function () { $("#ObjectAutomationSettings").hide(); });
}

openSlideAnimationModal = function (slideId, event) {
    if (event) { event.preventDefault(); event.stopPropagation(); }
    var target = generated_slides.find(function (slide) { return slide && slide.id === slideId; });
    if (!target || getFlag(target.DisableAnimation, 0) === 1) return;
    if (selected_slide_id !== slideId) {
        changeSlide(slideId, false, false, false);
        window.setTimeout(prepareSlideAnimationModal, 180);
    } else {
        prepareSlideAnimationModal();
    }
};

$(document).on("change", ".cg-animation-row__effect", function () {
    var index = Number($(this).closest(".cg-animation-row").attr("data-animation-index"));
    if (slideAnimationDraft[index]) slideAnimationDraft[index].effect = this.value;
}).on("click", "[data-object-preview-id]", function (event) {
    event.preventDefault();
    event.stopPropagation();
    openModalObjectPreview(this.getAttribute("data-object-preview-id"), "none");
}).on("click", "[data-animation-preview]", function (event) {
    event.preventDefault();
    event.stopPropagation();
    var row = $(this).closest(".cg-animation-row");
    var index = Number(row.attr("data-animation-index"));
    var entry = slideAnimationDraft[index];
    if (entry) openModalObjectPreview(entry.objectId, entry.effect);
}).on("click", "[data-object-preview-close]", function () {
    closeModalObjectPreview();
}).on("click", "[data-animation-move]", function () {
    var row = $(this).closest(".cg-animation-row");
    var from = Number(row.attr("data-animation-index"));
    var to = from + ($(this).attr("data-animation-move") === "up" ? -1 : 1);
    if (to < 0 || to >= slideAnimationDraft.length) return;
    var moved = slideAnimationDraft.splice(from, 1)[0];
    slideAnimationDraft.splice(to, 0, moved);
    renderSlideAnimationRows();
}).on("dragstart", ".cg-animation-row", function (event) {
    slideAnimationDragIndex = Number(this.getAttribute("data-animation-index"));
    this.classList.add("is-dragging");
    if (event.originalEvent.dataTransfer) event.originalEvent.dataTransfer.effectAllowed = "move";
}).on("dragover", ".cg-animation-row", function (event) {
    event.preventDefault();
}).on("drop", ".cg-animation-row", function (event) {
    event.preventDefault();
    var to = Number(this.getAttribute("data-animation-index"));
    if (slideAnimationDragIndex === null || to === slideAnimationDragIndex) return;
    var moved = slideAnimationDraft.splice(slideAnimationDragIndex, 1)[0];
    slideAnimationDraft.splice(to, 0, moved);
    slideAnimationDragIndex = null;
    renderSlideAnimationRows();
}).on("dragend", ".cg-animation-row", function () {
    slideAnimationDragIndex = null;
    this.classList.remove("is-dragging");
});

document.addEventListener("keydown", function (event) {
    if (event.key === "Escape" && !document.getElementById("cgObjectPreviewDialog").hidden) closeModalObjectPreview();
});

$(document).on("click", "#saveSlideAnimationBtn", function () {
    var slide = generated_slides[slide_index];
    if (!slide) return;
    var sequence = slideAnimationDraft.map(function (entry, index) {
        return { objectId: entry.objectId, effect: entry.effect, order: index + 1, duration: entry.duration };
    });
    slide.AnimationSequence = sequence;
    slide.jsonobj = canvas.toObject(["id"]);
    slide.jsonobj.animationSequence = sequence;
    slide.svg = encodeURIComponent(canvas.toSVG());
    slide.imgprev = canvas.toDataURL();
    updateSlideThumbnail(slide.id, slide.imgprev);
    $("#slideAnimationStatus").text("Animation order saved.");
    window.setTimeout(function () { bootstrap.Modal.getOrCreateInstance(document.getElementById("slideAnimationModal")).hide(); }, 250);
});

/**
 * STAMP: 2026-08-25 - Preview exactly one slide from its thumbnail menu.
 * The active canvas is serialized first, then the requested slide is cloned
 * into a one-slide deck so preview playback cannot mutate authoring state.
 *
 * @param {string} slideId Slide identifier selected from the thumbnail menu.
 * @param {Event} event Slide-menu click event.
 * @returns {void}
 */
function previewIndividualSlide(slideId, event) {
    if (event) {
        event.preventDefault();
        event.stopPropagation();
    }

    setData();

    var slide = Array.isArray(generated_slides)
        ? generated_slides.find(function (item) { return item && item.id === slideId; })
        : null;
    if (!slide) return;

    var previewSlide = JSON.parse(JSON.stringify(slide));
    openSerializedContentPreview(JSON.stringify([previewSlide]));
}

window.previewIndividualSlide = previewIndividualSlide;

// Build thumbnail HTML (slide list item)
/**
 * Build the shared three-dots slide action menu.
 *
 * @param {string} slideId Slide identifier used by the existing handlers.
 * @returns {string} HTML for the slide action dropdown.
 */
function buildSlideActionMenuHtml(slideId) {
    var slideRef = Array.isArray(generated_slides) ? generated_slides.find(function (slide) { return slide && slide.id === slideId; }) : null;
    var animationHidden = getFlag(slideRef && slideRef.DisableAnimation, 0) === 1 ? ' hidden' : '';
    return buildSlideMediaActionsHtml(slideId)
        + '<div class="dropdown cg-slide-action-dropdown" onclick="event.stopPropagation()">'
        + '  <button type="button" class="btn btn-dark cg-slide-action-button" data-bs-toggle="dropdown" aria-expanded="false" aria-label="Slide actions" onclick="event.stopPropagation()">'
        + '    <i class="fa fa-ellipsis-v" aria-hidden="true"></i>'
        + '  </button>'
        + '  <ul class="dropdown-menu dropdown-menu-end cg-slide-action-menu">'
        + '    <li><button type="button" class="dropdown-item cg-slide-media-menu-item" onclick="previewIndividualSlide(\'' + slideId + '\', event)"><i class="fa fa-eye" aria-hidden="true"></i><span>Preview slide</span></button></li>'
        + '    <li><hr class="dropdown-divider"></li>'
        + '    <li><button type="button" class="dropdown-item" onclick="duplicateSlide(\'' + slideId + '\', event)">Clone slide</button></li>'
        + '    <li><button type="button" class="dropdown-item" onclick="openSlideSettingsFromMenu(\'' + slideId + '\', event)">Settings</button></li>'
        + '    <li><hr class="dropdown-divider"></li>'
        + '    <li><button type="button" class="dropdown-item cg-slide-media-menu-item" onclick="openSlideMediaModal(\'' + slideId + '\', \'audio\', event)"><i class="fa fa-volume-up" aria-hidden="true"></i><span>Audio</span></button></li>'
        + '    <li><button type="button" class="dropdown-item cg-slide-media-menu-item" onclick="openSlideMediaModal(\'' + slideId + '\', \'video\', event)"><i class="fa fa-video-camera" aria-hidden="true"></i><span>Video</span></button></li>'
        + '    <li class="cg-slide-animation-menu-item" data-slide-id="' + slideId + '"' + animationHidden + '><button type="button" class="dropdown-item cg-slide-media-menu-item" onclick="openSlideAnimationModal(\'' + slideId + '\', event)"><i class="fa fa-star" aria-hidden="true"></i><span>Animation</span></button></li>'
        + '    <li><button type="button" class="dropdown-item cg-slide-media-menu-item" onclick="openSlideActionsModal(\'' + slideId + '\', event)"><i class="fa fa-hand-o-up" aria-hidden="true"></i><span>Actions</span></button></li>'
        + '    <li><button type="button" class="dropdown-item cg-slide-media-menu-item" onclick="openSlideAuthoringTools(\'' + slideId + '\', event)"><span class="cg-slide-action-at" aria-hidden="true">AT</span><span>Authoring tools</span></button></li>'
        + '    <li><button type="button" class="dropdown-item cg-slide-media-menu-item" onclick="openIntelligentContentForSlide(\'' + slideId + '\', event)"><i class="fa fa-magic" aria-hidden="true"></i><span>Intelligent content</span></button></li>'
        + '    <li><hr class="dropdown-divider"></li>'
        + '    <li><button type="button" class="dropdown-item text-danger" onclick="requestDeleteSlide(\'' + slideId + '\', event)">Delete slide</button></li>'
        + '  </ul>'
        + '</div>';
}

/* STAMP: 2026-08-19 - Close the slide action dropdown immediately after any
   menu choice while allowing the existing item handler to continue normally. */
document.addEventListener("click", function (event) {
    var menuItem = event.target && event.target.closest ? event.target.closest(".cg-slide-action-menu .dropdown-item") : null;
    if (!menuItem) return;

    var dropdownRoot = menuItem.closest(".cg-slide-action-dropdown");
    var dropdownToggle = dropdownRoot ? dropdownRoot.querySelector("[data-bs-toggle='dropdown']") : null;

    if (dropdownToggle && window.bootstrap && bootstrap.Dropdown) {
        bootstrap.Dropdown.getOrCreateInstance(dropdownToggle).hide();
    }
}, true);

/**
 * Build the HTML for a single slide thumbnail entry in the slide list.
 *
 * @param {*} v Runtime parameter preserved from the source implementation.
 * @param {*} i Runtime parameter preserved from the source implementation.
 * @returns {*} Value and side effects preserved from the source implementation.
 */
function buildSlideThumbHtml(v, i) {
    var html = '<div class="' + v.id + ' sld nosort">';
    html += buildSlideActionMenuHtml(v.id);

    html += '<div id=' + v.id + ' class="slideThumbnail " onclick="changeSlide(\'' + v.id + '\', false, false, false)">' +
        '<h4 style="position: absolute;top: 48px;font-size: 14px;left: 10px;text-align: center;line-height: 17px;width: 195px;width: 108px;">' +
        'Click here to load Slide preview.' +
        '</h4></div>';

    html += '<div class="slideorder" id="sldord_' + i + '">' +
        '<p class="clsnav" id="psld_' + v.id + '" contenteditable="true" onkeyup="ChangeSLDOrderKU(this.id,' + i + ')">Slide ' + (i + 1) + '</p>' +
        '</div>' +
        '<p class="clsname" id="p_' + v.id + '" contenteditable="true" onkeyup="ChangeSDV(this.id)">' + (v.name || "") + '</p>' +
        '</div>';

    return html;
}

// Audio UI (copied from your behavior; grouped)
/**
 * Apply slide-audio information to the audio preview and playback controls.
 *
 * @param {*} v Runtime parameter preserved from the source implementation.
 * @param {*} selectedId Runtime parameter preserved from the source implementation.
 * @returns {*} Value and side effects preserved from the source implementation.
 */
function applySlideAudioUI(v, selectedId) {
    // You had this long one-liner; kept same output, just readable
    $("#delsldaudio,#getaud,#divpaofl").show();
    $("#getaud").attr("src", v.SlideAudio.replace(/\\/g, "/"));

    $("#sldaud_" + selectedId).addClass("is-visible").attr("title", "Replace or Remove Audio");
    $("#sldaud_" + selectedId).html("<i class='fa fa-volume-up'></i>");

    // play once checkbox
    var playOnce = (v.PlayAudonfv !== undefined && v.PlayAudonfv == 1);
    var chk = document.getElementById("chkplayonce");
    if (chk) chk.checked = playOnce;
    $("#chkplayonce").parent().toggleClass("checked", !!playOnce);
}

// Control dropdown (kept behavior)
/**
 * Rebuild the control dropdown using the latest slide control collection.
 *
 * @param {*} slide_controls Runtime parameter preserved from the source implementation.
 * @returns {*} Value and side effects preserved from the source implementation.
 */
function rebuildControlDropdown(slide_controls) {
    // NOTE: original code didn't clear before append; that creates duplicates.
    // Clearing here is almost always correct; if you rely on accumulation, remove .empty().
    $("#sel_control").empty();

    if (!slide_controls || !slide_controls.length) return;
    $.each(slide_controls, function (key, sc) {
        var opt = '<option value="' + sc.id + '">' + sc.ctrl_name + "</option>";
        $("#sel_control").append(opt);
    });
}


/* =============================================================================
   getData (CLEANED): Load slides into editor
============================================================================= */

/**
 * Load serialized slide data into the editor and rebuild slide UI state.
 *
 * @param {*} ImportJS Runtime parameter preserved from the source implementation.
 * @returns {*} Value and side effects preserved from the source implementation.
 */
async function getData(ImportJS) {
    total_slides = 0;
    ruConfig.slideHistory = {};
    refreshUndoRedoButtons("");

    if (ImportJS === undefined || ImportJS === "") {
        return;
    }


    // Show loader
    canvasmode = "edit";
    showLoader("show");

    try {
        generated_slides = parseImportSlides(ImportJS);
        if (!generated_slides || !generated_slides.length) {
            return;
        }

        // Read flags from first slide (same as your code)
        var sp = getFlag(generated_slides[0].ShowPaginate, 0);
        var sn = getFlag(generated_slides[0].ShowNavigate, 1);
        var zm = getFlag(generated_slides[0].AllowZoom, 0);

        // You rely on slide_index in SetHoverClickValue(), so keep it stable
        slide_index = 0;

        // Apply hover/click globals and global toggles
        SetHoverClickValue();
        applyGlobalFlagsUI(sp, sn, zm);

        for (var i = 0; i < generated_slides.length; i++) {
            var v = generated_slides[i];

            // Keep these updated like your original
            slides_order = v.order;

            if (i === 0) {
                await loadJsonOnCanvas(v.jsonobj);

                // Disable animation for first slide
                var da0 = getFlag(v.DisableAnimation, 0);
                applyDisableAnimationUI(da0);

                // Update DOM IDs/classes for first slide (same wiring as your code)
                $("." + selected_slide_id).addClass(v.id).removeClass(selected_slide_id);
                $("#" + selected_slide_id)
                    .attr("id", v.id)
                    .attr("onclick", "event.stopPropagation(); changeSlide('" + v.id + "', false, false, false)");

                $("#p_" + selected_slide_id).attr("id", "p_" + v.id).html("Slide 1");
                $("#" + v.id).prev().attr("onclick", "duplicateSlide('" + v.id + "', event)");

                $("#li_" + selected_slide_id).attr("id", v.id);
                $("#a_" + selected_slide_id).attr("id", v.id);
                $("#sldaud_" + selected_slide_id).attr("id", "sldaud_" + v.id);
                $("#psld_" + selected_slide_id).attr("id", "psld_" + v.id);

                // reset audio icon state for new id (same as your original)
                $("#sldaud_" + v.id).html("");
                $("#sldaud_" + v.id).attr("title", "Add Audio");
                $("#sldaud_" + v.id).html("<i class='fa fa-upload auadd'></i>");

                // Persist back into array + globals
                generated_slides[i] = v;
                selected_slide_id = v.id;
                rebuildSlideActionControls(v.id);

                // Re-apply disable animation (your original did this twice)
                var da1 = getFlag(generated_slides[i].DisableAnimation, 0);
                applyDisableAnimationUI(da1);

                slide_index = i;
                slide_groups = v.groups;

                if (v.actions != "") { slide_actions = v.actions; }
                if (v.loadActions != "") { slide_load_actions = v.loadActions; }
                if (v.controls != "") { slide_controls = v.controls; }
                if (v.animationOnControls != "") { animationOnControls = v.animationOnControls; }
                if (v.action_list != "") { clickActionList = v.action_list; }
                if (v.load_action_list != "") { loadActionList = v.load_action_list; }

                $(".loadActionList").html(loadActionList);
                $(".clickActionList").html(clickActionList);

                // Thumbnail of slide 1
                updateSlideThumbnail(selected_slide_id, canvas.toDataURL());

                // Controls dropdown + ids array fill (kept)
                rebuildControlDropdown(slide_controls);
                for (var k = 0; k < (v.controls || []).length; k++) {
                    ids.push(v.controls[k].id);
                }

                // Audio UI (kept)
                if (v.SlideAudio) {
                    applySlideAudioUI(v, selected_slide_id);
                }

                // Slide select dropdown
                $("#sel_slide").append('<option value="' + v.id + '">Slide 1</option>');
            } else {
                // Show pagination status (same)
                $("#divpaginationstatus").show();

                // Build slide thumb HTML and append
                var thumbHtml = buildSlideThumbHtml(v, i);
                $(".generatedSlides").append(thumbHtml);

                // Apply saved preview if exists
                if (v.imgprev != undefined) {
                    updateSlideThumbnailSaved(v.id, v.imgprev);
                }

                // These were in your code; keep them
                $("#noauto").prop("checked", true);
                if (sp == 1) {
                    ShowPaginate = 1;
                    $(".NavPagin").prop("checked", false);
                    $("#autopaginate").prop("checked", true);
                } else {
                    ShowPaginate = 0;
                }
                if (sn == 1) {
                    ShowNavigate = 1;
                    $(".NavPagin").prop("checked", false);
                    $("#autonavivate").prop("checked", true);
                } else {
                    ShowNavigate = 0;
                }

                // Slide select dropdown
                $("#sel_slide").append('<option value="' + v.id + '">Slide ' + (i + 1) + "</option>");
            }

            // Update dropdown list after DOM settled (same intent)
            setTimeout(function () {
                updateDropdownList();
            }, 1000);

            total_slides++;
        }

        SetSlideValues();

        // 2026-08-18: The first slide was already awaited above. Calling changeSlide
        // here saved/reloaded it asynchronously and could replace its canvas with blank state.
        if (generated_slides.length > 0) {
            var firstSlideId = generated_slides[0].id;
            seedSlideHistory(firstSlideId, generated_slides[0].jsonobj);
            selected_slide_id = firstSlideId;
            slide_index = 0;
            canvas.requestRenderAll();
        }
    } catch (error) {
        console.error("getData failed:", error);
    } finally {
        showLoader("hide");
    }
}


