window.openSlideMediaModal = function (slideId, mediaType, event) {
    if (event) {
        event.preventDefault();
        event.stopPropagation();
    }
    var targetIndex = generated_slides.findIndex(function (item) { return item && item.id === slideId; });
    if (targetIndex < 0) return;
    if (selected_slide_id !== slideId && typeof changeSlide === "function") changeSlide(slideId, false, false, false);
    var slide = generated_slides[targetIndex];
    var value = mediaType === "audio" ? slide.SlideAudio : slide.SlideVideo;
    var preview = document.getElementById("slideMediaPreview");
    var videoEditor = document.getElementById("slideMediaVideoEditor");
    $("#slideMediaModal").data("slideId", slideId).data("mediaType", mediaType);
    $("#slideMediaSlideName").text(slide.name || ("Slide " + (targetIndex + 1)));
    $("#slideMediaModalLabel").text(value
        ? (mediaType === "audio" ? "Audio preview" : "Video preview")
        : (mediaType === "audio" ? "Add slide audio" : "Add embedded video"));
    $("#slideMediaChangeBtn").text(mediaType === "audio"
        ? (value ? "Change audio" : "Select audio")
        : "Change video").prop("hidden", mediaType === "video" && !value);
    $("#slideMediaSaveBtn").prop("hidden", true);
    $("#slideMediaRemoveBtn").prop("hidden", !value);
    $("#slideMediaStatus").text(value ? "Attached to this slide" : "No media attached");
    pendingSlideAudioOptimization = null;
    slideAudioOptimizationToken++;
    $("#slideAudioOptimizer").prop("hidden", true);
    videoEditor.hidden = true;
    preview.innerHTML = "";
    if (mediaType === "audio" && value) {
        var audio = document.createElement("audio");
        audio.controls = true;
        audio.preload = "metadata";
        audio.src = String(value).replace(/\\/g, "/");
        preview.appendChild(audio);
    } else if (mediaType === "video" && value) {
        if (String(value).indexOf("data:video") === 0) {
            var video = document.createElement("video");
            video.controls = true;
            video.src = value;
            preview.appendChild(video);
        } else {
            var wrapper = document.createElement("div");
            wrapper.innerHTML = value;
            var iframe = wrapper.querySelector("iframe");
            if (iframe) {
                var source = iframe.getAttribute("src") || "";
                var isSupportedSource = /^https:\/\/(www\.)?(youtube\.com|youtube-nocookie\.com|player\.vimeo\.com)\//i.test(source);
                if (isSupportedSource) {
                    Array.prototype.slice.call(iframe.attributes).forEach(function (attribute) {
                        if (attribute.name.toLowerCase().indexOf("on") === 0) iframe.removeAttribute(attribute.name);
                    });
                    preview.appendChild(iframe.cloneNode(true));
                }
            }
        }
    } else if (mediaType === "video") {
        videoEditor.hidden = false;
        $("#slideMediaVideoInput").val("").trigger("focus");
        $("#slideMediaSaveBtn").text("Add video").prop("hidden", false);
        $("#slideMediaStatus").text("Paste a YouTube or Vimeo URL, or a valid iframe embed code.");
    }
    bootstrap.Modal.getOrCreateInstance(document.getElementById("slideMediaModal")).show();
};

