/**
 * STAMP: 2026-09-09 - Format the selected slide-audio size in this handler's scope.
 * The image optimizer's private formatBytes helper is not visible here.
 */
function formatSlideAudioBytes(bytes) {
    if (!Number.isFinite(bytes) || bytes < 0) return "";
    if (bytes === 0) return "0 B";
    var units = ["B", "KB", "MB", "GB"];
    var unitIndex = Math.min(Math.floor(Math.log(bytes) / Math.log(1024)), units.length - 1);
    var value = bytes / Math.pow(1024, unitIndex);
    return value.toFixed(value >= 10 || unitIndex === 0 ? 0 : 1) + " " + units[unitIndex];
}

function selectSlideAudioVersion(versionName) {
    var selection = pendingSlideAudioOptimization && pendingSlideAudioOptimization[versionName];
    if (!selection) {
        $("#slideMediaStatus").text(versionName === "optimized"
            ? "The optimized audio is not ready yet."
            : "The original audio is not ready yet.");
        return false;
    }

    slideAudioBase64 = selection.base64;
    slideAudioMime = selection.mime;
    var preview = document.getElementById("slideMediaPreview");
    preview.innerHTML = "";
    var audio = document.createElement("audio");
    audio.controls = true;
    audio.preload = "metadata";
    audio.src = selection.base64;
    preview.appendChild(audio);
    $("#slideMediaStatus").text(
        (versionName === "optimized" ? "Optimized" : "Original")
        + " audio selected (" + formatSlideAudioBytes(selection.size) + "). Save to attach it to this slide."
    );
    $("#slideMediaSaveBtn").text("Save audio").prop("hidden", false);
    $("#useOriginalSlideAudio, #useOptimizedSlideAudio").removeClass("active").attr("aria-pressed", "false");
    $(versionName === "optimized" ? "#useOptimizedSlideAudio" : "#useOriginalSlideAudio")
        .addClass("active").attr("aria-pressed", "true");
    $("#slideAudioOptimizerState").text(versionName === "optimized" ? "Optimized selected" : "Original selected");
    return true;
}

$(document).off("click.cgUseOriginalSlideAudio", "#useOriginalSlideAudio").on("click.cgUseOriginalSlideAudio", "#useOriginalSlideAudio", function (event) {
    event.preventDefault();
    if (selectSlideAudioVersion("original")) $("#slideMediaSaveBtn").trigger("focus");
});

