/* =============================================================================
   getData_New_Slide (ALIGNED + CLEAN)
   - Your version was already cleaner; this just aligns helper usage and
     removes a couple of no-op DOM reassignments.
============================================================================= */

/**
 * Load imported content into a newly created slide and rebuild dependent UI state.
 *
 * This async function preserves the source behavior while making control flow
 * easier to trace in the structured reference copy.
 *
 * @param {*} ImportJS Runtime parameter preserved from the source implementation.
 * @param {*} targetIndex Runtime parameter preserved from the source implementation.
 * @returns {*} Value and side effects preserved from the source implementation.
 */
async function getData_New_Slide(ImportJS, targetIndex) {
    // resolve target slide index
    var idx = (Number.isInteger(targetIndex) ? targetIndex : CurrentSlideNo);
    var slideRef = (generated_slides && generated_slides[idx]) ? generated_slides[idx] : null;

    if (!slideRef) {
        console.warn("getData_New_Slide: invalid slide index", idx);
        return false;
    }

    // parse input: string | object | array
    var raw;
    try {
        raw = (typeof ImportJS === "string")
            ? JSON.parse(replaceAll(ImportJS, "<br />", "\\n"))
            : ImportJS;
    } catch (e) {
        console.error("getData_New_Slide: JSON parse failed", e);
        return false;
    }

    var values = normalizeToList(raw);
    if (!values.length || !values[0]) return false;
    var d0 = values[0];

    // flags
    Isprocess = 1;
    canvas.clear();
    canvasmode = "edit";

    // disable animation checkbox from target slide settings
    applyDisableAnimationUI(getFlag(slideRef.DisableAnimation, 0));

    // bind incoming rows to this slide id
    var NewSlideID = slideRef.id;
    values.forEach(function (v) { v.slideId = NewSlideID; });

    // copy payload into the correct slide
    slideRef.action_list = d0.action_list ?? "";
    slideRef.actions = d0.actions ?? "";
    slideRef.animationOnControls = d0.animationOnControls ?? "";
    slideRef.controls = d0.controls ?? [];
    slideRef.groups = d0.groups ?? [];
    slideRef.id = NewSlideID;
    slideRef.jsonobj = d0.jsonobj ?? {};
    slideRef.loadActions = d0.loadActions ?? "";
    slideRef.load_action_list = d0.load_action_list ?? "";
    slideRef.svg = d0.svg ?? "";
    slideRef.imgprev = d0.imgprev ?? "";
    slideRef.HTMlcontent = d0.HTMlcontent ?? "";

    // load JSON on main canvas
    await loadJsonOnCanvas(slideRef.jsonobj);

    // sync globals
    slides_order = slideRef.order;
    slide_index = idx;
    slide_groups = slideRef.groups;

    if (slideRef.actions) slide_actions = slideRef.actions;
    if (slideRef.loadActions) slide_load_actions = slideRef.loadActions;
    if (slideRef.controls) slide_controls = slideRef.controls;
    if (slideRef.animationOnControls) animationOnControls = slideRef.animationOnControls;
    if (slideRef.action_list) clickActionList = slideRef.action_list;
    if (slideRef.load_action_list) loadActionList = slideRef.load_action_list;

    $(".loadActionList").html(loadActionList || "");
    $(".clickActionList").html(clickActionList || "");

    // thumbnail from offscreen StaticCanvas
    var tmpEl = document.createElement("canvas");
    tmpEl.width = 943; tmpEl.height = 442;

    var tempCanvas = new fabric.StaticCanvas(tmpEl, {
        width: 943,
        height: 442,
        renderOnAddRemove: true,
        preserveObjectStacking: true
    });

    await loadJsonOnTempCanvas(tempCanvas, slideRef.jsonobj);
    updateSlideThumbnail(slideRef.id, tempCanvas.toDataURL());

    // controls dropdown
    rebuildControlDropdown(slide_controls);

    // audio UI (kept)
    if (slideRef.UniquepgeName != null) {
        UniqueID = replaceAll(slideRef.UniquepgeName, "&", "");
        UniqueID = replaceAll(UniqueID, "'", "");
        UniqueID = replaceAll(UniqueID, "’", "");
        UniqueID = replaceAll(UniqueID, "?", "");

        if (slideRef.SlideAudio) {
            applySlideAudioUI(slideRef, slideRef.id);
        }
    }

    // final UI
    $(".loadingWrapper").hide();
    canvas.renderAll();
    $("#propertybars").fadeOut();

    setTimeout(function () {
        $("#myObjnav").fadeIn();
        $("#viewobjects").click();
        if (canvas.item(0)) canvas.setActiveObject(canvas.item(0));
        $(".actnat").show();
        $("#toggleActionsarea").click();
        $("#drpselactn").val("9");
        $("#slideChangeWrapper,#HyperlinkWrapper,.animateWrapper").hide();
        $(".authoringtoolWrapper").show();
        selectedClickEvent = "at";
        $("#divupdoc,#Hyperlink,#vidupoad,#vidlink,#divvidembbed").hide();
    }, 300);

    setTimeout(function () {

        showLoader("hide");
    }, 200);

    return true;
}


